window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0157", [{"word":"creative","ipa_uk":"/kriˈeɪtɪv/","ipa_us":"/kriˈeɪtɪv/","definition_zh":"有创造力的；富于创意的；有新意的；作名词指创意人员","definition_en":"able to produce original ideas or things, or involving imagination rather than routine repetition","core_image":"工作台上一堆被剪碎的旧纸板，被重新拼成一只从没见过的鸟","scene":"手工教室里，孩子们把废纸箱剪碎，又用胶带拼出一只振翅的纸鸟。The teacher praises the class for a creative use of scrap material.","sceneCN":"这里 creative 指「把平常材料用出新花样」（第 1 个义项：能想出或做出前所未见的东西）；句意为老师称赞全班把废料用得有创意。场景要素：碎纸板、胶带、纸鸟、剪刀。","pos":[{"tag":"adj.","zh":"有创造力的；富于创意的；有新意的"},{"tag":"n.","zh":"创意人员（广告、设计等行业）"}],"collocations":[{"phrase":"creative thinking","zh":"创造性思维"},{"phrase":"creative process","zh":"创作过程"},{"phrase":"creative writing","zh":"创意写作"},{"phrase":"creative solution","zh":"有创意的解决办法"},{"phrase":"creative arts","zh":"创意艺术"},{"phrase":"a creative approach","zh":"有创意的做法"}],"forms":[{"label":"比较级","form":"more creative"},{"label":"最高级","form":"most creative"},{"label":"名词（创造力）","form":"creativity"},{"label":"副词","form":"creatively"},{"label":"名词（创造性）","form":"creativeness"}],"derivatives":[{"word":"create","pos":"v.","zh":"由拉丁语「制造、产生」的动词直接进入英语，指使某物从无到有"},{"word":"creation","pos":"n.","zh":"由 create 加名词后缀构成，指创造的行为或成果"},{"word":"creator","pos":"n.","zh":"由 create 加表人后缀构成，指创造者"},{"word":"creativity","pos":"n.","zh":"由 creative 加抽象名词后缀构成，指创造的能力"},{"word":"creatively","pos":"adv.","zh":"由 creative 加副词后缀构成，指以有创意的方式"},{"word":"creativeness","pos":"n.","zh":"由 creative 加构成，指富于创意的性质"},{"word":"uncreative","pos":"adj.","zh":"由否定前缀加 creative 构成，指缺乏创意的"}],"senses":[{"no":"01","title":"Able to produce original ideas","titleCN":"能想出从未有过的主意","definition":"able to think of ideas or make things that did not exist before","definitionCN":"能够想出此前不存在的主意或做出此前不存在的东西","example":"A creative engineer solved the noise problem with a folded metal sheet.","exampleCN":"一位有创造力的工程师用一片折弯的金属板解决了噪声问题。","why":"The adjective attaches the Latin verb for making to a person, so the basic reading is a person who makes rather than repeats.","whyCN":"这个形容词把拉丁语中「制造」的动词挂到人身上，最基本的读法就是会造而不是只会重复的人。"},{"no":"02","title":"Inventive under limits","titleCN":"受限时仍能想出办法","definition":"able to find an unusual but workable way when the obvious route is blocked","definitionCN":"在明显路径被堵住时，仍能找到不寻常但可行的做法","example":"With no truck available, the crew took a creative route through the drainage channel.","exampleCN":"没有卡车可用，工班只好从排水渠走出一条有创意的路线。","why":"When the ordinary path fails, the same making capacity turns into resourcefulness, which is why the word often appears with problems and tight budgets.","whyCN":"常规路径走不通时，同一种「造」的能力就转为随机应变，因此这个词常与难题和紧预算一起出现。"},{"no":"03","title":"Imaginative in the arts","titleCN":"艺术上富于想象","definition":"showing imagination in writing, music, design or performance","definitionCN":"在写作、音乐、设计或表演中显出想象力","example":"The festival is known for its creative programming of unfamiliar chamber works.","exampleCN":"这个音乐节以富有创意地编排冷门室内乐作品而闻名。","why":"The arts gave the word its widest home, because a work that only repeats an earlier form is not felt to be made at all.","whyCN":"艺术给了这个词最宽的落脚处，因为只重复旧形式的作品根本不被视为「造」出来的。"},{"no":"04","title":"Generating new output as a sector","titleCN":"作为行业持续产出新东西","definition":"used about an industry or process that keeps producing new work, products or methods","definitionCN":"用于形容持续产出新作品、新产品或新方法的行业或过程","example":"The region built a creative economy around small design studios.","exampleCN":"这个地区围绕小型设计工作室建立起创意经济。","why":"Once making is applied to an entire sector, the word stops describing a person and starts describing the flow of new output.","whyCN":"当「造」被用到整个行业上，这个词就不再形容某个人，而形容新产出的持续流动。"},{"no":"05","title":"A person in a creative role","titleCN":"创意岗位上的从业者","definition":"a noun for someone employed to produce ideas, as in advertising or design","definitionCN":"作名词，指在广告或设计等行业里被雇来出主意的人","example":"The agency moved three creatives onto the launch campaign.","exampleCN":"这家代理机构把三名创意人员调去做新品发布。","why":"Twentieth-century studios shortened the phrase for a creative person into a bare noun, so the adjective became a job title.","whyCN":"二十世纪的创意行业把「有创意的员工」压缩成一个光秃秃的名词，形容词于是变成了职位名。"},{"no":"06","title":"Technically true but misleading","titleCN":"形式上合规却误导他人","definition":"describing accounting or reporting that follows the letter of the rules while hiding the real picture","definitionCN":"形容账目或报告在字面上遵守规则，却掩盖了真实情况","example":"Auditors rejected the creative accounting that moved losses into a quiet subsidiary.","exampleCN":"审计人员否决了那种把亏损挪进一家不起眼子公司的花账。","why":"Here the making is applied to numbers, and the praise turns into an accusation because what is made is a false impression.","whyCN":"这里「造」被用到数字上，褒义转为指责，因为被造出来的是一种虚假的印象。"},{"no":"07","title":"Producing new forms in language or design","titleCN":"在语言或设计上造出新形式","definition":"describing usage that deliberately breaks an established pattern in order to make a new one","definitionCN":"形容故意打破既有格式、以便造出新格式的用法","example":"The poet's creative spelling forced readers to slow down.","exampleCN":"诗人别出心裁的拼写迫使读者放慢速度。","why":"The word can name rule-breaking that is productive rather than careless, since a new pattern is offered in place of the old.","whyCN":"这个词可以指有产出的破格而非疏忽，因为旧格局的位置上被放进了新格局。"},{"no":"08","title":"Unexpected yet fitting","titleCN":"出人意料又恰好成立","definition":"describing a solution that surprises the audience and still satisfies the problem","definitionCN":"形容既让读者意外、又确实解决问题的做法","example":"Her creative ending made the whole film click into place.","exampleCN":"她那个出人意料的结尾让整部电影一下子合上了。","why":"The strongest use of the word joins surprise with fit: something is new, and it also works, so the two halves of the core image meet.","whyCN":"这个词最有力的用法把「意外」与「合适」并在一起：既新又成立，核心意象的两半就此合拢。"}],"etymology":{"intro":{"en":"Creative comes from Latin creare 'to make, bring forth' plus the adjective suffix -ivus, carried into English through Old French. Dates are approximate.","cn":"creative 来自拉丁语 creare「制造、产生」加形容词后缀，经古法语进入英语。年代均为约数。"},"items":[{"era":"LATIN CREARE","en":"Creare meant 'to make, produce, bring forth'. Its deeper origin is not established; the link often suggested to crescere 'to grow' is a hypothesis, not a proven derivation.","cn":"creare 意为「制造、产生、使出现」。其更早来源未定；常有人把它与意为「生长」的 crescere 联系起来，那只是假说，并非已证实的派生。"},{"era":"LATIN CREATUS","en":"The past participle creatus and the noun creatio supplied both the idea of a thing made and the name of the act of making.","cn":"过去分词 creatus 与名词 creatio 同时提供了「被造之物」和「制造行为」两个概念。"},{"era":"OLD FRENCH CREATIF","en":"Old French passed the adjective into English in the sixteenth century, at first for divine making and then for human making.","cn":"古法语在十六世纪把这个形容词传入英语，先用于神的创造，再用于人的创造。"},{"era":"ART SENSE","en":"During the eighteenth century the word settled on imagination in art and literature, the sense that still leads most dictionaries.","cn":"到十八世纪，这个词固定在艺术与文学的想象力上，这一义项至今仍排在多数词典的首位。"},{"era":"INDUSTRY SENSE","en":"Advertising and design adopted it as a noun for their staff in the twentieth century, and the bare noun is now ordinary in those trades.","cn":"二十世纪的广告与设计业把它当名词指自己的员工，如今这一名词用法在这些行业里已很平常。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation and deeper root): no single date can be given for the first English use of the adjective, and the pre-Latin origin of creare is unsettled, so any Indo-European form proposed for it is a reconstruction.","cn":"来源不确定（首见书证与更深词根）：这个形容词在英语中的最早用例没有唯一可定的年代；creare 在拉丁语之前的来源亦无定论，凡为其提出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words from the same making family that are routinely swapped; group two holds near neighbours that stress imagination or novelty.","cn":"第一组是同出「制造」词族、常被混用的词；第二组是侧重想象或新意、语义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"create","ipa":"/kriˈeɪt/","tag":"the verb behind it","definition":"The verb for bringing something into being; it names the act, while creative names the capacity to perform that act.","definitionCN":"指使某物产生的动词，说的是行为本身；creative 说的则是具备做出这种行为的能力。"},{"word":"creation","ipa":"/kriˈeɪʃn/","tag":"the act or the product","definition":"Built with the noun suffix for an action or its result, so it means either the making or the thing made, not the quality of a person.","definitionCN":"加了表行为或结果的名词后缀，因此指制造行为或被造之物，而不指人的品质。"},{"word":"creator","ipa":"/kriˈeɪtə/","tag":"the person who makes","definition":"Built with the person suffix, so it points to whoever performs the act; a creative person may never finish a single creator's work.","definitionCN":"加了表人后缀，因此指向行为的实施者；有创意的人未必真的完成一件创造者的作品。"},{"word":"creature","ipa":"/ˈkriːtʃə/","tag":"same verb, different sense","definition":"Formed from the same Latin verb, but its sense went to a living being that has been made, so it has nothing to do with originality.","definitionCN":"由同一个拉丁动词构成，但词义转向「被造出的生灵」，因此与新意无关。"},{"word":"creativity","ipa":"/kriəˈtɪvəti/","tag":"the capacity as a noun","definition":"A noun for the capacity itself; it cannot be used for a single clever product, where creative is the right choice.","definitionCN":"指能力本身的名词，不能用来指某一件巧妙的作品，那里应当用 creative。"}]},{"heading":"NEAR MEANING","entries":[{"word":"inventive","ipa":"/ɪnˈventɪv/","tag":"good at devising","definition":"Stresses devising a device, method or story that did not exist; it leans toward practical or structural novelty.","definitionCN":"强调设计出此前不存在的装置、方法或故事，偏向实用或结构上的新颖。"},{"word":"imaginative","ipa":"/ɪˈmædʒɪnətɪv/","tag":"rich in images","definition":"Stresses the inner picture-making that precedes the product; a plan can be imaginative without producing anything usable.","definitionCN":"强调产出之前心中的画面营造；一个方案可以有想象力却做不出可用的东西。"},{"word":"original","ipa":"/əˈrɪdʒənl/","tag":"first of its kind","definition":"Stresses being the first, not the capacity; a single original idea does not make a person creative in general.","definitionCN":"强调「第一个」，而非能力；只有一个原创想法并不等于这个人整体上有创造力。"},{"word":"innovative","ipa":"/ɪˈnəʊvətɪv/","tag":"new and adopted","definition":"Stresses a new method or product that actually gets taken up, so it looks at acceptance rather than at the maker.","definitionCN":"强调新方法或新产品真正被采用，看的是接受度而不是创造者本人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"The Latin verb for making sits inside the adjective, so creative names the capacity to make.","cn":"拉丁语中「制造」的动词就藏在这个形容词里，因此 creative 说的是「造」的能力。"},{"en":"The family runs create, creation, creator, creativity, creatively, uncreative.","cn":"同族词包括 create、creation、creator、creativity、creatively、uncreative。"},{"en":"Fixed phrases mark the field: creative thinking, creative writing, creative solution.","cn":"固定搭配标出使用范围：创造性思维、创意写作、有创意的解决办法。"},{"en":"The same Latin root reappears in creature, where the making produced a living being rather than an idea.","cn":"同一拉丁词根还出现在 creature 中，那里的「造」造出的是生灵而非主意。"},{"en":"Industry uses the bare noun: agencies hire creatives.","cn":"行业里用光秃秃的名词：代理机构会招创意人员。"}],"abstract":[{"en":"Picture a heap of scrap that turns into a bird nobody had drawn before.","cn":"想象一堆废料变成一只此前没人画过的鸟。"},{"en":"Picture a key cut in an odd shape that still opens the locked door.","cn":"想象一把形状古怪却仍能打开锁的钥匙。"},{"en":"Picture a sentence that breaks the grammar book and still makes perfect sense.","cn":"想象一个违反语法书的句子，却依然说得通。"}]},"examples":[{"en":"The workshop teaches children to treat broken tools as creative material.","cn":"工作坊教孩子们把坏掉的工具当作有创意的材料。"},{"en":"Her creative rewrite kept every fact and changed every sentence.","cn":"她的创造性改写保留了全部事实，却换掉了每一个句子。"},{"en":"The company was praised for a creative fix that cost almost nothing.","cn":"这家公司因一个几乎不花钱的巧妙解决办法受到称赞。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「可 create 的」——能凭空造出东西，就是有创造力的","word":"creative"},"root":"拉丁 creare「制造、产生」+ 形容词后缀；creare 与「生长」的 crescere 是否同源尚无定论，更深来源属重构形式。英语 creative。","sensesIntro":{"en":"Eight senses follow one act: something is brought into being. The act is then read as a personal capacity, as resourcefulness under limits, as imagination in art, as an industry's output, as a job title, and finally as rule-breaking that still works.","cn":"八个义项沿同一个动作展开：使某物产生。这个动作随后被读作个人能力、受限条件下的应变、艺术中的想象、行业的产出、一种职位，最后读作仍然成立的破格。"},"semanticMap":{"core":{"en":"CORE IMAGE: a heap of cut paper rearranged into a bird that was never there before.","cn":"核心意象：一堆剪碎的纸被重新排成一只此前并不存在的鸟。"},"chain":["MAKE","IMAGINE","INVENT","ORIGINATE","REINTERPRET","FITTING SURPRISE"],"branches":[{"senses":"01 · 02","en":"CAPACITY AND RESOURCEFULNESS: the same making power, first with free choice and then with the obvious route blocked.","cn":"能力与应变：同一种「造」的力量，先是在自由选择时，后是在明显路径被堵住时。"},{"senses":"03 · 07","en":"FORM-MAKING: art and deliberate rule-breaking both replace an old pattern with a new one.","cn":"造形：艺术与故意破格，都是拿新格局替换旧格局。"},{"senses":"04 · 05","en":"COLLECTIVE MAKING: a sector's steady output, and the people hired to supply it.","cn":"集体之造：一个行业的持续产出，以及被雇来提供这种产出的人。"},{"senses":"06","en":"MAKING A FALSE IMPRESSION: the power turned on numbers, so praise becomes blame.","cn":"造出假象：这种力量被用到数字上，褒义于是变成指责。"},{"senses":"08","en":"SURPRISE THAT FITS: the new thing also has to work, which closes the circle of the core image.","cn":"意外的合适：新东西还得好用，核心意象到此合拢。"}]},"affixes":{"intro":{"en":"Creative is a Latin root plus a Latin adjective suffix, and both parts build a whole English family, so the word can be read morpheme by morpheme.","cn":"creative 是一个拉丁词根加一个拉丁形容词后缀，两部分都构成了一整族英语词，因此可以按语素逐个读出。"},"latinIntro":{"en":"Latin creare supplies create, creation, creator, creature and creativity; the suffix -ivus appears in many English adjectives of tendency.","cn":"拉丁语 creare 衍生出 create、creation、creator、creature 与 creativity；后缀出现在许多表示倾向的英语形容词里。"},"items":[{"word":"creare","structure":"creare (Latin verb, first conjugation)","meaning":"to make, produce","meaningCN":"制造；产生","example":"The root carries the idea of bringing something into being.","exampleCN":"这个词根带着「使某物产生」的意思。"},{"word":"create","structure":"creare + English verb use","meaning":"to bring into being","meaningCN":"使产生；创造","example":"The verb entered English through French in the same family.","exampleCN":"这个动词经法语进入英语，属于同一词族。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix, 'tending to')","meaning":"tending to; having the quality of","meaningCN":"倾向于；具有……性质的","example":"The suffix turns the act of making into a quality of a person.","exampleCN":"这个后缀把「造」的行为转成人的一种品质。"},{"word":"creative","structure":"create + -ive","meaning":"having the power to make","meaningCN":"具有创造能力的","example":"The adjective names the capacity, not one finished product.","exampleCN":"这个形容词指能力，而不是某一件成品。"},{"word":"-ity","structure":"-itas (Latin noun suffix, 'state or quality')","meaning":"the state of being","meaningCN":"……的状态或性质","example":"The suffix turns the adjective into a name for the capacity.","exampleCN":"这个后缀把形容词转为指称能力的名词。"},{"word":"creativity","structure":"creative + -ity","meaning":"the capacity to make new things","meaningCN":"创造新事物的能力","example":"Schools now test creativity as a separate skill.","exampleCN":"学校如今把创造力当作一项独立能力来测。"},{"word":"-or","structure":"-or (Latin agent suffix, 'one who')","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix marks the person who performs the act.","exampleCN":"这个后缀标出行为的实施者。"},{"word":"creator","structure":"create + -or","meaning":"one who makes","meaningCN":"创造者","example":"The creator of the method refused to patent it.","exampleCN":"这套方法的创造者拒绝为它申请专利。"},{"word":"-ion","structure":"-io (Latin noun suffix, 'act or result')","meaning":"act or result","meaningCN":"行为或结果","example":"The suffix names either the making or what is made.","exampleCN":"这个后缀可指制造行为，也可指被造之物。"},{"word":"creation","structure":"create + -ion","meaning":"the act or the thing made","meaningCN":"创造行为或被造之物","example":"The whole creation took three years.","exampleCN":"整个创作花了三年。"},{"word":"-ly","structure":"-lice (English adverb suffix)","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The adverb describes how the making is done.","exampleCN":"这个副词描述「造」是以何种方式完成的。"},{"word":"creatively","structure":"creative + -ly","meaning":"in a creative way","meaningCN":"以有创意的方式","example":"The team solved the leak creatively.","exampleCN":"团队用很有创意的办法解决了漏水。"}],"latinEntries":[{"word":"creare","structure":"creare, creavi, creatum (verb, first conjugation)","meaning":"to make, produce, bring forth","meaningCN":"制造；产生；使出现"},{"word":"creatus","structure":"creatus, -a, -um (past participle)","meaning":"made, produced","meaningCN":"被制造的；被产生的"},{"word":"creatio","structure":"creatio, creationis (f., third declension)","meaning":"a making, a creation","meaningCN":"制造；创造"},{"word":"creator","structure":"creator, creatoris (m., third declension)","meaning":"one who makes","meaningCN":"制造者；创造者"}]}},{"word":"metacognition","ipa_uk":"/ˌmetəkɒɡˈnɪʃn/","ipa_us":"/ˌmetəkɑːɡˈnɪʃn/","definition_zh":"元认知；对自身思维过程的认识与调控","definition_en":"knowledge and control of one's own thinking processes, such as noticing whether one has understood something","core_image":"一个人脑中亮起第二盏灯，照着自己正在思考的那盏灯","scene":"自习室里，一名学生读完一章统计教材，停下来问自己能否用自己的话复述公式。The tutor calls that moment of doubt healthy metacognition.","sceneCN":"这里 metacognition 指「对自己是否真正理解的觉察」（第 1 个义项：对自身思维过程的认识）；句意为导师把这种怀疑的瞬间称为健康的元认知。场景要素：摊开的统计书、写满批注的便签、停下的笔。","pos":[{"tag":"n.","zh":"元认知；对自身认知活动的认识与调节"}],"collocations":[{"phrase":"metacognitive awareness","zh":"元认知意识"},{"phrase":"metacognitive strategy","zh":"元认知策略"},{"phrase":"metacognitive monitoring","zh":"元认知监控"},{"phrase":"metacognitive knowledge","zh":"元认知知识"},{"phrase":"metacognitive regulation","zh":"元认知调节"},{"phrase":"develop metacognition","zh":"发展元认知"}],"forms":[{"label":"复数（罕用）","form":"metacognitions"},{"label":"形容词","form":"metacognitive"},{"label":"副词","form":"metacognitively"}],"derivatives":[{"word":"metacognitive","pos":"adj.","zh":"由 metacognition 加形容词后缀构成，指与元认知有关的"},{"word":"metacognitively","pos":"adv.","zh":"由 metacognitive 加副词后缀构成，指以元认知的方式"},{"word":"cognition","pos":"n.","zh":"由拉丁语「认识」的名词直接进入英语，指认知活动本身，不含自我监控这一层"},{"word":"cognitive","pos":"adj.","zh":"由 cognition 加形容词后缀构成，泛指与心理加工有关的"},{"word":"recognition","pos":"n.","zh":"由表「再次」的前缀加「认识」词根构成，指把某物认作先前见过"}],"senses":[{"no":"01","title":"Awareness of one's own thinking","titleCN":"对自己思维的觉察","definition":"conscious knowledge that one is thinking, remembering or reasoning, and of what one is doing mentally","definitionCN":"对自己正在思考、记忆或推理，以及正在做什么心理活动的自觉认识","example":"She caught herself rereading the same line and began to monitor her own comprehension.","exampleCN":"她发现自己反复读同一行，于是开始监控自己的理解情况。","why":"The Greek prefix adds 'about itself' to the Latin noun for knowing, so the compound literally names knowing about knowing.","whyCN":"希腊语前缀给拉丁语中表「认识」的名词加上「关于自身」，因此这个复合词字面上就是「对认识的认识」。"},{"no":"02","title":"Monitoring comprehension","titleCN":"边读边查是否读懂","definition":"checking, while reading or listening, whether one has actually understood the material","definitionCN":"在阅读或听讲的过程中核查自己是否真的理解了材料","example":"He marked the paragraph he could not paraphrase and returned to it after class.","exampleCN":"他标出那段无法用自己的话复述的文字，课后回头再看。","why":"Awareness becomes useful only when it is aimed at a specific task, and the first task is always the check on understanding.","whyCN":"觉察只有落到具体任务上才有用，而第一项任务永远是核查理解。"},{"no":"03","title":"Planning a learning strategy","titleCN":"预先规划学习策略","definition":"choosing in advance how to study, for example by previewing, spacing or self-testing","definitionCN":"事先选定学习方式，例如预习、分散安排或自测","example":"Before the exam she planned which chapters needed two passes and which needed only one.","exampleCN":"考试前她先规划哪些章节要过两遍、哪些只需过一遍。","why":"Knowing about one's own thinking allows a plan to be fitted to the material, which is why planning is counted as a metacognitive act.","whyCN":"了解自己的思维，才能把计划贴合材料，因此规划被算作一种元认知行为。"},{"no":"04","title":"Evaluating one's own performance","titleCN":"事后评估自己的表现","definition":"reviewing after a task which parts went well and which strategy should change next time","definitionCN":"任务结束后回顾哪些部分做得顺、下次该换哪种策略","example":"After the failed quiz she listed the questions she had rushed and the ones she had misread.","exampleCN":"测验失利后，她列出自己抢答的题和看错题意的题。","why":"The same self-directed gaze can be turned backward, and this backward look is what turns an experience into a lesson.","whyCN":"这种指向自身的目光也可以转向过去，而正是这回望把一次经历变成一堂课。"},{"no":"05","title":"Knowledge about memory and attention","titleCN":"关于记忆与注意的知识","definition":"knowing how memory, attention and forgetting actually work, so that study can be adjusted to them","definitionCN":"了解记忆、注意与遗忘的实际运作，从而据此调整学习方式","example":"He knew that rereading feels easy but tests poorly, so he switched to recall practice.","exampleCN":"他知道重读感觉轻松却考不出效果，于是改用回忆练习。","why":"The compound covers more than moment-by-moment checking: it also holds the stored facts about how minds work.","whyCN":"这个复合词不只覆盖当下的核查，也包含关于心智如何运作的既有知识。"},{"no":"06","title":"Regulating mental effort","titleCN":"调节投入的心力","definition":"deciding how much time and attention a passage or problem deserves","definitionCN":"判断一段材料或一道题值得投入多少时间与注意力","example":"She spent four minutes on the hard item and then moved on, by design rather than by panic.","exampleCN":"她在难题上花了四分钟便按计划转向下一题，而不是慌着放弃。","why":"Once a learner can judge difficulty, effort can be allocated instead of spilled, which is the regulating half of the term.","whyCN":"学习者一旦能判断难度，心力就可以被分配而不是被洒掉，这正是这个术语中「调节」的一半。"},{"no":"07","title":"The research field itself","titleCN":"作为一个研究领域","definition":"the academic study of how people monitor and control their own thinking","definitionCN":"研究人如何监控与调控自身思维的学术领域","example":"The journal devoted a special issue to metacognition in early childhood.","exampleCN":"这份期刊用一整期专号讨论幼儿期的元认知。","why":"A named mental process quickly becomes the name of the discipline that studies it, so the abstract noun also labels a field.","whyCN":"一种被命名的心理过程很快会成为研究它的学科之名，因此这个抽象名词也指一个领域。"},{"no":"08","title":"A skill that can be taught","titleCN":"可被教会的一种能力","definition":"a trainable ability to reflect on and steer one's learning, promoted through prompts and modelling","definitionCN":"通过提示与示范加以培养的、反思并引导自身学习的能力","example":"The reading programme builds metacognition by asking students to predict and then check.","exampleCN":"这套阅读课程让学生先预测再核对，以此培养元认知。","why":"If awareness can be learned, schools can teach it directly, and the term moves from description to curriculum.","whyCN":"如果觉察可以学会，学校就能直接教授，这个术语便从描述变成了课程。"}],"etymology":{"intro":{"en":"Metacognition joins a Greek prefix meaning 'about itself' to the Latin noun for knowing. The compound is a modern scientific coinage. Dates are approximate.","cn":"metacognition 把一个表示「关于自身」的希腊语前缀接到拉丁语中表「认识」的名词上。这个复合词是现代学术造词。年代均为约数。"},"items":[{"era":"GREEK META","en":"Greek meta meant 'after, beyond, behind'. In modern scientific compounds it shifted to 'about itself', as in a study of studies.","cn":"希腊语 meta 原意是「在后、超出、背后」。在现代学术复合词中它转为「关于自身」，如「对研究的研究」。"},{"era":"LATIN COGNOSCERE","en":"Com- 'together, thoroughly' plus gnoscere 'to come to know' produced cognoscere 'to get to know'. The deeper origin of gnoscere is not established.","cn":"意为「共同、彻底」的拉丁前缀加 gnoscere「逐渐知道」构成 cognoscere「认识、得知」。gnoscere 的更早来源未得到证明。"},{"era":"LATIN COGNITIO","en":"The noun cognitio named both the act of knowing and the knowledge that results from it.","cn":"名词 cognitio 既指认识的行为，也指由此获得的知识。"},{"era":"ENGLISH COGNITION","en":"English borrowed cognition in the sixteenth century for the act of knowing; psychology later narrowed it to mental processing.","cn":"英语在十六世纪借入 cognition 表示「认识」这一行为；心理学后来把它收窄为心理加工。"},{"era":"MODERN COINAGE","en":"The compound is generally attributed to the developmental psychologist John Flavell in the nineteen seventies, who used it for knowledge about one's own thinking.","cn":"这个复合词一般认为是发展心理学家弗拉维尔在二十世纪七十年代提出的，用来指关于自身思维的知识。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use): the exact earliest citation is not settled, and the pre-Latin origin of the knowing root is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（最早书证）：确切的最早用例尚无定论；那个表「认识」的词根在拉丁语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words from the same knowing family whose self-referential layer differs; group two holds near neighbours that name reflection rather than the machinery of thought.","cn":"第一组是同出「认识」词族、但自我指向程度不同的词；第二组是侧重反思而非思维机制本身的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cognition","ipa":"/kəˈɡnɪʃn/","tag":"without the self-layer","definition":"The mental act of knowing, remembering or reasoning itself; it says nothing about noticing that one is doing these things.","definitionCN":"指认识、记忆或推理的心理活动本身，并不包含「察觉自己正在做这些事」的意思。"},{"word":"cognitive","ipa":"/ˈkɒɡnətɪv/","tag":"the adjective of cognition","definition":"Relating to mental processes in general, as in cognitive science; it is not the adjective of metacognition.","definitionCN":"泛指与心理加工有关的，如认知科学；它并不是 metacognition 的形容词。"},{"word":"recognition","ipa":"/ˌrekəɡˈnɪʃn/","tag":"again plus knowing","definition":"Built with the prefix meaning 'again' plus the knowing root, so it means identifying something as known before.","definitionCN":"由表「再次」的前缀加「认识」词根构成，因此指把某物认作先前见过。"},{"word":"precognition","ipa":"/ˌpriːkɒɡˈnɪʃn/","tag":"before plus knowing","definition":"Built with the prefix meaning 'before', so it names claimed knowledge of future events, not awareness of one's own thinking.","definitionCN":"由表「在前」的前缀构成，指对未来的所谓预知，而不是对自身思维的觉察。"}]},{"heading":"NEAR MEANING","entries":[{"word":"self-monitoring","ipa":"/ˌself ˈmɒnɪtərɪŋ/","tag":"watching one's own work","definition":"The ongoing check on one's own performance during a task; narrower than metacognition, which also includes stored knowledge and planning.","definitionCN":"指任务进行中对自身表现的持续核查，比元认知窄，后者还包含既有知识与规划。"},{"word":"self-regulation","ipa":"/ˌself ˌriːɡjuˈleɪʃn/","tag":"steering oneself","definition":"The control of effort, emotion and strategy toward a goal; metacognition is the knowing side that guides this control.","definitionCN":"指为达成目标而对心力、情绪与策略加以控制；元认知是指导这种控制的认识一侧。"},{"word":"reflection","ipa":"/rɪˈflekʃn/","tag":"thinking back","definition":"Deliberate thinking about an experience after it happens; metacognition also covers what happens in the middle of a task.","definitionCN":"指事后对某段经历的有意思考；元认知还覆盖任务进行中的当下。"},{"word":"self-awareness","ipa":"/ˌself əˈweənəs/","tag":"knowing one's own state","definition":"Awareness of one's feelings, character and limits; metacognition is the narrower case of awareness applied to thinking.","definitionCN":"指对自身情绪、性格与局限的觉察；元认知是这种觉察用在思维上的较窄情形。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real morphemes, the real research family and the real classroom phrases.","cn":"正常联想：两个真实语素、真实的研究词族与真实的课堂用语。"},"normal":[{"en":"The first element means 'about itself', so the word literally reads thinking about thinking.","cn":"第一个成分意为「关于自身」，因此这个词字面上就是「对思考的思考」。"},{"en":"The second element is the Latin knowing root that also gives cognition, cognitive and recognize.","cn":"第二个成分是拉丁语中表「认识」的词根，也构成 cognition、cognitive 与 recognize。"},{"en":"Classroom phrases fix the term: metacognitive awareness, metacognitive strategy, metacognitive monitoring.","cn":"课堂短语把这个术语固定下来：元认知意识、元认知策略、元认知监控。"},{"en":"It names two halves: knowledge about thinking, and control of thinking while it happens.","cn":"它包含两半：关于思维的知识，以及对进行中思维的调控。"},{"en":"The noun and the adjective differ only in word class, so metacognition is the thing and metacognitive is the quality.","cn":"名词与形容词只差词性：metacognition 指那种能力，metacognitive 指与之有关的性质。"}],"abstract":[{"en":"Picture a camera able to film its own lens.","cn":"想象一台能拍摄自己镜头的相机。"},{"en":"Picture a librarian who keeps a note of how she searches, not only of what she shelves.","cn":"想象一位图书管理员，不只记录书上架的位置，还记录自己是怎么找书的。"},{"en":"Picture a ladder long enough to be leaned against itself.","cn":"想象一架长得足以靠在自己身上的梯子。"}]},"examples":[{"en":"Good readers use metacognition to notice when a sentence stops making sense.","cn":"会读书的人用元认知察觉某句话何时开始读不通。"},{"en":"The course teaches metacognition through short reflections after each quiz.","cn":"这门课在每次小测后安排简短反思，以此教授元认知。"},{"en":"Researchers measure metacognition by comparing confidence with actual accuracy.","cn":"研究者通过比较信心与实际正确率来测量元认知。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「meta 在后 + cognition 认知」——站在认知背后看认知，就是元认知","word":"metacognition"},"root":"希腊语前缀 meta「在后、超出、关于自身」+ 拉丁 cognoscere「认识」；cognoscere 由「共同、彻底」加表「逐渐知道」的词根构成，后者更深来源不确定。英语 metacognition。","sensesIntro":{"en":"Eight senses follow one loop: a mind turns toward its own activity. That turn is then read as bare awareness, as a check on understanding, as planning, as review, as stored knowledge, as effort control, as a research field and as a teachable skill.","cn":"八个义项沿一个回路展开：心智转向自己的活动。这个转向随后被读作单纯的觉察、对理解的核查、规划、回顾、既有知识、心力控制、一个研究领域，以及一种可教的能力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a second lamp inside the head that lights the lamp already thinking.","cn":"核心意象：脑中亮起第二盏灯，照着自己正在思考的那盏灯。"},"chain":["THINK","NOTICE THINKING","CHECK UNDERSTANDING","PLAN STRATEGY","REVIEW RESULT","STUDY THE PROCESS"],"branches":[{"senses":"01 · 05","en":"KNOWING ABOUT THINKING: bare awareness and stored facts about memory are the knowledge half of the term.","cn":"关于思维的知识：单纯的觉察与关于记忆的既有知识，构成这个术语的知识一半。"},{"senses":"02 · 06","en":"ONLINE CONTROL: checking comprehension and rationing effort both happen while the task is running.","cn":"当下调控：核查理解与分配心力，都发生在任务进行之中。"},{"senses":"03 · 04","en":"BEFORE AND AFTER: a plan laid in advance and a review made afterwards bracket the task.","cn":"事前与事后：事先拟定的计划与事后的回顾，把任务夹在中间。"},{"senses":"07","en":"THE FIELD: a named process turns into the discipline that studies it.","cn":"学科：一种被命名的过程变成了研究它的学科。"},{"senses":"08","en":"TEACHABLE SKILL: once awareness can be trained, it enters the curriculum.","cn":"可教的能力：觉察一旦可以训练，就进入了课程。"}]},"affixes":{"intro":{"en":"The word is built from a Greek prefix and a Latin root, an unusual but common pattern in scientific English, and both parts build other words.","cn":"这个词由一个希腊语前缀和一个拉丁词根构成，这是学术英语中不常见却常有的组合，两部分都构成别的词。"},"latinIntro":{"en":"The knowing root gives cognition, cognitive, recognize, recognition and precognition; the Greek prefix recurs in metaphysics, metabolism and metadata.","cn":"表「认识」的词根衍生出 cognition、cognitive、recognize、recognition 与 precognition；希腊语前缀还出现在 metaphysics、metabolism 与 metadata 中。"},"items":[{"word":"meta-","structure":"meta- (Greek prefix, 'after, beyond, about itself')","meaning":"about itself; beyond","meaningCN":"关于自身；超出","example":"The prefix makes the word refer to the process it follows.","exampleCN":"这个前缀让后面的词反过来指向那个过程本身。"},{"word":"cognoscere","structure":"cognoscere (Latin verb, third conjugation)","meaning":"to come to know","meaningCN":"逐渐认识；得知","example":"The root carries the idea of getting to know rather than merely sensing.","exampleCN":"这个词根带着「逐渐认识」的意思，而不只是感觉到。"},{"word":"cognition","structure":"cognoscere + -io (noun of action)","meaning":"the act of knowing","meaningCN":"认识的行为","example":"The noun names the process that the prefix turns back on itself.","exampleCN":"这个名词指那个过程，而前缀让它反过来指向自身。"},{"word":"cognitive","structure":"cognition + -ive","meaning":"relating to mental processing","meaningCN":"与心理加工有关的","example":"The adjective describes the process but adds no self-reference.","exampleCN":"这个形容词描述该过程，却不带自我指向。"},{"word":"recognize","structure":"re- 'again' + cognoscere","meaning":"to know again, identify","meaningCN":"再次认出","example":"The same root with a different prefix produces a very different verb.","exampleCN":"同一词根配另一个前缀，构成意思很不同的动词。"},{"word":"recognition","structure":"recognize + -ion","meaning":"the act of identifying as known","meaningCN":"认出；识别","example":"The noun keeps the 'again' sense of its verb.","exampleCN":"这个名词保留了动词中「再次」的意思。"},{"word":"metacognition","structure":"meta- + cognition","meaning":"knowing about one's own knowing","meaningCN":"对自身认知的认识","example":"The compound unites the two halves into a single technical term.","exampleCN":"这个复合词把两部分合成一个专门术语。"},{"word":"metacognitive","structure":"metacognition + -ive","meaning":"relating to such awareness","meaningCN":"与这种自我觉察有关的","example":"The adjective is the ordinary attributive form in research writing.","exampleCN":"这个形容词是研究写作中常用的定语形式。"},{"word":"metacognitively","structure":"metacognitive + -ly","meaning":"in a self-monitoring manner","meaningCN":"以自我监控的方式","example":"The adverb describes how a learner acts rather than what they know.","exampleCN":"这个副词描述学习者怎样行动，而非知道什么。"}],"latinEntries":[{"word":"cognoscere","structure":"cognoscere, cognovi, cognitum (verb, third conjugation)","meaning":"to get to know, learn","meaningCN":"认识；得知"},{"word":"cognitio","structure":"cognitio, cognitionis (f., third declension)","meaning":"a knowing, knowledge","meaningCN":"认识；知识"},{"word":"cognitus","structure":"cognitus, -a, -um (past participle)","meaning":"known, having been learned","meaningCN":"已知的；被认识的"}]}},{"word":"metacognitive","ipa_uk":"/ˌmetəˈkɒɡnətɪv/","ipa_us":"/ˌmetəˈkɑːɡnətɪv/","definition_zh":"元认知的；与对自身思维过程的认识和调控有关的","definition_en":"relating to the awareness and control of one's own thinking, memory or learning","core_image":"一支笔在笔记本边缘写下一行小字：我刚才那样想，对吗","scene":"考前，辅导老师让学生给每个章节的把握程度打分。He describes the rating as a metacognitive check on what they really know.","sceneCN":"这里 metacognitive 指「针对自身掌握程度的」（第 1 个义项：与对自身思维的认识有关）；句意为他把这种打分称为对所掌握内容的元认知核查。场景要素：章节清单、打分表、铅笔。","pos":[{"tag":"adj.","zh":"元认知的；与自我认知监控有关的"}],"collocations":[{"phrase":"metacognitive awareness","zh":"元认知意识"},{"phrase":"metacognitive strategy","zh":"元认知策略"},{"phrase":"metacognitive monitoring","zh":"元认知监控"},{"phrase":"metacognitive knowledge","zh":"元认知知识"},{"phrase":"metacognitive skill","zh":"元认知技能"},{"phrase":"metacognitive prompt","zh":"元认知提示"}],"forms":[{"label":"比较级","form":"more metacognitive"},{"label":"最高级","form":"most metacognitive"},{"label":"副词","form":"metacognitively"},{"label":"名词","form":"metacognition"}],"derivatives":[{"word":"metacognition","pos":"n.","zh":"由 metacognitive 去掉形容词后缀构成的名词，指元认知这一能力本身"},{"word":"metacognitively","pos":"adv.","zh":"由 metacognitive 加副词后缀构成，指以元认知的方式"},{"word":"cognition","pos":"n.","zh":"同族中不含自我指向的名词，指认知活动本身"},{"word":"cognitive","pos":"adj.","zh":"由 cognition 加形容词后缀构成，泛指与心理加工有关的"}],"senses":[{"no":"01","title":"Relating to awareness of one's own thinking","titleCN":"与对自身思维的觉察有关","definition":"relating to the awareness of one's own thinking, remembering or reasoning","definitionCN":"与对自己正在思考、记忆或推理这一点的觉察有关","example":"The interview asked students how metacognitive they felt during independent study.","exampleCN":"访谈询问学生在自主学习时觉得自己在多大程度上有元认知。","why":"The adjective simply attaches the quality suffix to the noun, so it describes anything that belongs to that self-directed awareness.","whyCN":"这个形容词只是把表性质的后缀加到名词上，因此描述任何属于这种自我指向觉察的事物。"},{"no":"02","title":"Describing a comprehension check","titleCN":"形容对理解的核查","definition":"describing a strategy that stops a reader to ask whether the text has been understood","definitionCN":"形容一种让读者停下来、自查是否读懂的策略","example":"A metacognitive pause after each section caught the errors early.","exampleCN":"每读完一节就作一次元认知式的停顿，早早拦住了错误。","why":"Checking understanding is the first use anyone makes of this awareness, so the adjective most often modifies words for such checks.","whyCN":"核查理解是这种觉察最直接的用途，因此这个形容词最常修饰与核查有关的词。"},{"no":"03","title":"Describing knowledge about one's memory","titleCN":"形容关于自身记忆的知识","definition":"describing knowledge of how one's own memory and attention behave, including their known weaknesses","definitionCN":"形容关于自身记忆与注意如何运作、包括其已知弱点的知识","example":"Her metacognitive notes listed the topics she always confused under pressure.","exampleCN":"她的元认知笔记列出自己在压力下总会混淆的题目。","why":"Stored facts about one's own mind also count, so the adjective covers knowledge as well as moment-to-moment noticing.","whyCN":"关于自己心智的既有知识同样算数，因此这个形容词既覆盖知识，也覆盖当下的觉察。"},{"no":"04","title":"Describing control of effort","titleCN":"形容对心力的调节","definition":"describing the allocation of time and attention according to how hard a task is judged to be","definitionCN":"形容依据任务被判断的难度来分配时间与注意力","example":"A metacognitive habit kept him from sinking forty minutes into one footnote.","exampleCN":"一种元认知习惯让他没有把四十分钟陷进一条脚注里。","why":"Judging difficulty and acting on that judgment links awareness to behaviour, which is why the adjective often appears with control and regulation.","whyCN":"判断难度并据此行动，把觉察与行为连了起来，因此这个形容词常与控制、调节一类词同现。"},{"no":"05","title":"Describing a teaching prompt","titleCN":"形容课堂上的引导提问","definition":"describing a question a teacher asks to make students explain how they reached an answer","definitionCN":"形容教师为让学生说明自己如何得出答案而提出的问题","example":"The metacognitive prompt was simply: what made you choose that method?","exampleCN":"那个元认知提示只有一句：是什么让你选了这个方法？","why":"If the capacity is trainable, the adjective will attach to the tools used to train it, and prompts are the cheapest such tool.","whyCN":"既然这种能力可以训练，这个形容词就会修饰训练它的工具，而提问是最便宜的一种。"},{"no":"06","title":"Describing confidence ratings in research","titleCN":"形容研究中的信心评分","definition":"describing a measure that asks people to rate how sure they are before or after answering","definitionCN":"形容要求人们在作答前后给自己的确定程度打分的一种测量","example":"The metacognitive measure was the gap between predicted and actual scores.","exampleCN":"那项元认知指标就是预测分数与实际分数之间的差距。","why":"A private feeling becomes measurable only when it is turned into a rating, so the adjective enters experimental method.","whyCN":"私下的感觉只有变成评分才可以测量，因此这个形容词进入了实验方法。"},{"no":"07","title":"Describing reflection on an error","titleCN":"形容对错误的回看","definition":"describing the review of a mistake to find which step of one's reasoning went wrong","definitionCN":"形容回看一次错误、找出推理中哪一步出了偏差","example":"A short metacognitive review turned the failed problem into a rule he could reuse.","exampleCN":"一次简短的元认知复盘把那道做错的题变成了可以复用的规则。","why":"The forward-looking gaze can be turned backward, and the adjective follows it there.","whyCN":"这种向前的目光可以转向过去，这个形容词也跟着用到了那里。"},{"no":"08","title":"Describing a system that models itself","titleCN":"形容能对自身建模的系统","definition":"describing, in technical use, a system that represents its own reasoning or uncertainty","definitionCN":"在技术语境中形容一个能表征自身推理或不确定性的系统","example":"The planner adds a metacognitive layer that estimates the reliability of its own forecast.","exampleCN":"这个规划器加了一层元认知结构，用来估计自己预测的可靠程度。","why":"Engineers borrowed the term because a machine that monitors its own confidence faces the same problem as a student who does.","whyCN":"工程师借用了这个术语，因为一台监控自身信心的机器，与一个这样做的学生面对的是同一个问题。"}],"etymology":{"intro":{"en":"Metacognitive is the adjective built on metacognition, itself a modern compound of a Greek prefix and the Latin noun for knowing. Dates are approximate.","cn":"metacognitive 是建立在 metacognition 之上的形容词，而后者本身是一个希腊语前缀加拉丁语「认识」名词的现代复合词。年代均为约数。"},"items":[{"era":"GREEK META","en":"Greek meta meant 'after, beyond, behind'; in scientific compounds it came to mean 'about itself'.","cn":"希腊语 meta 原意是「在后、超出、背后」；在学术复合词中转为「关于自身」。"},{"era":"LATIN COGNOSCERE","en":"The knowing root, built with a prefix meaning 'thoroughly', gave cognoscere 'to get to know' and the noun cognitio.","cn":"那个表「认识」的词根配上意为「彻底」的前缀，构成 cognoscere「认识、得知」及名词 cognitio。"},{"era":"MODERN NOUN","en":"The noun metacognition is generally attributed to the developmental psychologist John Flavell in the nineteen seventies.","cn":"名词 metacognition 一般认为是发展心理学家弗拉维尔在二十世纪七十年代提出的。"},{"era":"DERIVED ADJECTIVE","en":"The adjective followed the noun into psychology and education, where it modifies strategies, knowledge and monitoring.","cn":"这个形容词随后进入心理学与教育学，用来修饰策略、知识与监控。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use of the adjective): the earliest citation is not settled, and the pre-Latin origin of the knowing root is unknown, so any older form is a reconstruction.","cn":"来源不确定（这个形容词的最早书证）：最早用例尚无定论；那个表「认识」的词根在拉丁语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the same-root words that differ in how much self-reference they carry; group two holds adjectives that describe a reflective manner rather than the thinking process.","cn":"第一组是同根词，差别在于自我指向的强弱；第二组是形容反思姿态、而非思维过程本身的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metacognition","ipa":"/ˌmetəkɒɡˈnɪʃn/","tag":"the noun, not the adjective","definition":"The noun names the capacity or the field; it cannot stand before another noun the way this adjective does.","definitionCN":"这是指能力或领域的名词，不能像本词那样放在另一个名词前作定语。"},{"word":"cognitive","ipa":"/ˈkɒɡnətɪv/","tag":"without the self-layer","definition":"Relating to mental processing in general; it lacks the prefix that turns the process back on itself.","definitionCN":"泛指与心理加工有关的，缺少那个让过程转向自身的前缀。"},{"word":"cognition","ipa":"/kəˈɡnɪʃn/","tag":"the process itself","definition":"The process of knowing or reasoning, with no reference to monitoring it.","definitionCN":"指认识或推理的过程，不涉及对这种过程的监控。"},{"word":"precognitive","ipa":"/ˌpriːˈkɒɡnətɪv/","tag":"before, not about","definition":"Built with the prefix meaning 'before', so it describes knowledge claimed ahead of events, not awareness of one's own mind.","definitionCN":"由表「在前」的前缀构成，形容事件之前就有的所谓认识，而不是对自身心智的觉察。"}]},{"heading":"NEAR MEANING","entries":[{"word":"reflective","ipa":"/rɪˈflektɪv/","tag":"given to thinking back","definition":"Describes a person or piece of writing that considers things carefully afterwards; it does not name the monitoring of thought itself.","definitionCN":"形容人或文字事后细加思考，并不直接指对思维的监控。"},{"word":"introspective","ipa":"/ˌɪntrəˈspektɪv/","tag":"looking inward","definition":"Describes the habit of examining one's own feelings and motives; the focus is inner experience rather than learning control.","definitionCN":"形容审视自身感受与动机的习惯，落点在内心体验而非学习调控。"},{"word":"self-regulated","ipa":"/ˌself rɪˈɡjuleɪtɪd/","tag":"steered by oneself","definition":"Describes a learner who sets goals and adjusts effort; it stresses behaviour, while this word stresses the awareness behind it.","definitionCN":"形容能自定目标并调整心力的学习者，落点在行为，而本词落点在行为背后的觉察。"},{"word":"self-aware","ipa":"/ˌself əˈweə/","tag":"knowing one's state","definition":"A general adjective for knowing one's feelings, character or effect on others, without the focus on thinking.","definitionCN":"泛指了解自身情绪、性格或对他人的影响，并不聚焦于思维。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real root and the real research collocations.","cn":"正常联想：真实的前缀、真实的词根与真实的研究搭配。"},"normal":[{"en":"The prefix turns the word back on itself, so it always describes awareness of awareness.","cn":"前缀让这个词转向自身，因此它总在描述「对觉察的觉察」。"},{"en":"The second half is the Latin knowing root shared with cognition and recognize.","cn":"后半部分是拉丁语中表「认识」的词根，与 cognition、recognize 共用。"},{"en":"It typically sits before strategy, knowledge, monitoring and awareness.","cn":"它通常放在 strategy、knowledge、monitoring 与 awareness 之前。"},{"en":"The noun is metacognition and the adverb is metacognitively, one family with three forms.","cn":"名词是 metacognition，副词是 metacognitively，同一个词族有三种词形。"},{"en":"In research it often modifies measure, rating or prompt, because inner certainty has to be turned into a number.","cn":"在研究里它常修饰 measure、rating 或 prompt，因为内心的确定程度必须被变成数字。"}],"abstract":[{"en":"Picture a margin note that asks whether the last paragraph was really understood.","cn":"想象页边的一行小字，问上一段是否真的读懂了。"},{"en":"Picture a scale that weighs itself before weighing the parcel.","cn":"想象一台先称自己、再称包裹的秤。"},{"en":"Picture a mirror placed so that the room can see the mirror.","cn":"想象一面摆得让整个房间都能看见它的镜子。"}]},"examples":[{"en":"A metacognitive question after each chapter keeps the reading honest.","cn":"每章之后提一个元认知问题，能让阅读不至于自欺。"},{"en":"The study compared metacognitive accuracy in experts and beginners.","cn":"这项研究比较了专家与初学者的元认知准确度。"},{"en":"Teachers can model metacognitive talk by saying aloud how they chose a method.","cn":"教师可以示范元认知式的言语，把自己如何选定方法说出来。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「meta 在后面 + cognitive 认知的」——站在认知后面的，就是元认知的","word":"metacognitive"},"root":"希腊语前缀 meta「在后、关于自身」+ 拉丁 cognoscere「认识」+ 形容词后缀；cognoscere 更深来源不确定。英语 metacognitive。","sensesIntro":{"en":"Eight senses follow one adjective through the same loop: a mind turned toward its own working. It describes bare awareness, checks on understanding, stored knowledge, effort control, classroom prompts, confidence ratings, error review and finally a machine that models itself.","cn":"八个义项让同一个形容词沿着同一个回路走：心智转向自己的运作。它依次形容单纯的觉察、对理解的核查、既有知识、心力控制、课堂提问、信心评分、错误复盘，最后是能对自身建模的机器。"},"semanticMap":{"core":{"en":"CORE IMAGE: a margin note asking whether the thought just had was right.","cn":"核心意象：页边写下的一行小字，问刚才那个想法对不对。"},"chain":["AWARE","CHECK","KNOW ONE'S MEMORY","ALLOCATE EFFORT","EXPLAIN REASONING","MODEL ONESELF"],"branches":[{"senses":"01 · 07","en":"THE TURNING GAZE: plain awareness and the review of a mistake are the same look aimed forward and backward.","cn":"转向的目光：单纯的觉察与对错误的回看，是同一道目光朝前与朝后。"},{"senses":"02 · 05","en":"CHECKING AND PROMPTING: a private check and a teacher's question both force understanding into the open.","cn":"核查与提问：私下的自查与教师的提问，都把理解逼到明处。"},{"senses":"03 · 06","en":"KNOWLEDGE AND MEASURE: stored facts about one's mind and the rating of confidence are the same knowledge made countable.","cn":"知识与测量：关于自身心智的既有知识与信心评分，是同一份知识被变成可计数之物。"},{"senses":"04","en":"EFFORT CONTROL: judging difficulty turns awareness into an adjustment of time and attention.","cn":"心力控制：判断难度把觉察变成对时间与注意力的调整。"},{"senses":"08","en":"THE SELF-MODELLING MACHINE: engineering borrows the adjective when a system must estimate its own reliability.","cn":"自我建模的机器：当系统必须估计自身可靠程度时，工程学借用了这个形容词。"}]},"affixes":{"intro":{"en":"The word combines a Greek prefix, a Latin root and a Latin adjective suffix, and each piece also builds other common English words.","cn":"这个词组合了一个希腊语前缀、一个拉丁词根和一个拉丁形容词后缀，每一部分都还构成别的常见英语词。"},"latinIntro":{"en":"The Latin root yields cognition, recognize and precognition; the Greek prefix recurs in metaphysics and metabolism.","cn":"拉丁词根衍生出 cognition、recognize 与 precognition；希腊语前缀还出现在 metaphysics 与 metabolism 中。"},"items":[{"word":"meta-","structure":"meta- (Greek prefix, 'about itself, beyond')","meaning":"about itself","meaningCN":"关于自身","example":"The prefix makes the whole word refer to the process behind it.","exampleCN":"这个前缀让整个词反过来指它背后的那个过程。"},{"word":"cognoscere","structure":"cognoscere (Latin verb, third conjugation)","meaning":"to come to know","meaningCN":"逐渐认识","example":"The root supplies the idea of knowing rather than sensing.","exampleCN":"这个词根提供「认识」而非「感觉」的意思。"},{"word":"cognition","structure":"cognoscere + -io","meaning":"the act of knowing","meaningCN":"认识的行为","example":"The noun is the base that the prefix turns inward.","exampleCN":"这个名词是被前缀转向内部的那个基底。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix)","meaning":"tending to; relating to","meaningCN":"倾向于；与……有关","example":"The suffix makes an adjective of the noun.","exampleCN":"这个后缀把名词变成形容词。"},{"word":"metacognition","structure":"meta- + cognition","meaning":"awareness of one's own knowing","meaningCN":"对自身认知的觉察","example":"The compound is the noun from which this adjective is built.","exampleCN":"这个复合词是本形容词所由构成的名词。"},{"word":"metacognitive","structure":"metacognition + -ive","meaning":"relating to such awareness","meaningCN":"与这种觉察有关的","example":"The adjective is the usual form before strategy, knowledge and monitoring.","exampleCN":"这个形容词是放在策略、知识、监控之前的常用形式。"},{"word":"metacognitively","structure":"metacognitive + -ly","meaning":"in a self-monitoring way","meaningCN":"以自我监控的方式","example":"The adverb describes how someone studies, not what they know.","exampleCN":"这个副词描述人怎样学习，而不是知道什么。"},{"word":"cognitive","structure":"cognoscere + -ivus","meaning":"relating to mental processing","meaningCN":"与心理加工有关的","example":"Without the Greek prefix, the adjective stays at the level of processing.","exampleCN":"没有那个希腊语前缀，这个形容词就停在心理加工的层面。"},{"word":"-ly","structure":"-lice (English adverb suffix)","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The suffix turns the adjective into a manner adverb.","exampleCN":"这个后缀把形容词变成方式副词。"}],"latinEntries":[{"word":"cognoscere","structure":"cognoscere, cognovi, cognitum (verb, third conjugation)","meaning":"to get to know","meaningCN":"认识；得知"},{"word":"cognitio","structure":"cognitio, cognitionis (f., third declension)","meaning":"a knowing","meaningCN":"认识"},{"word":"cognitus","structure":"cognitus, -a, -um (past participle)","meaning":"known","meaningCN":"已知的"}]}},{"word":"self-awareness","ipa_uk":"/ˌself əˈweənəs/","ipa_us":"/ˌself əˈwernəs/","definition_zh":"自我意识；对自身情绪、状态与形象的认识","definition_en":"knowledge of one's own feelings, character, body or effect on other people","core_image":"一个人站在镜前，不只看见脸，还看见自己刚才为什么皱眉","scene":"练功房里，舞者反复看自己排练的录像，留意重心如何移动。The video gives her a sharper self-awareness of how she shifts her weight.","sceneCN":"这里 self-awareness 指「对自身动作状态的清楚认识」（第 1 个义项：对自身状态的认识）；句意为录像让她更清楚地意识到自己怎样转移重心。场景要素：排练录像、地胶、镜子、水杯。","pos":[{"tag":"n.","zh":"自我意识；对自身状态与形象的认识"}],"collocations":[{"phrase":"develop self-awareness","zh":"培养自我意识"},{"phrase":"heightened self-awareness","zh":"更强的自我意识"},{"phrase":"emotional self-awareness","zh":"情绪上的自我觉察"},{"phrase":"a lack of self-awareness","zh":"缺乏自我认识"},{"phrase":"self-awareness of one's limits","zh":"对自身局限的认识"},{"phrase":"public self-awareness","zh":"对他人眼中形象的意识"}],"forms":[{"label":"复数（罕用）","form":"self-awarenesses"},{"label":"形容词","form":"self-aware"},{"label":"相关名词","form":"awareness"}],"derivatives":[{"word":"self-aware","pos":"adj.","zh":"由 self-awareness 去掉名词后缀构成的形容词，指对自身有认识的"},{"word":"awareness","pos":"n.","zh":"该复合词的中心词，指对某事的察觉状态"},{"word":"unaware","pos":"adj.","zh":"由否定前缀加 aware 构成，指未察觉的"},{"word":"self-conscious","pos":"adj.","zh":"另一条复合词，指过度在意他人目光的，与自我认识不是同一件事"},{"word":"self-knowledge","pos":"n.","zh":"另一条复合词，指对自身性格的深层了解，偏静态而非当下觉察"}],"senses":[{"no":"01","title":"Knowledge of one's own feelings and character","titleCN":"对自身情绪与性格的认识","definition":"a clear sense of what one feels, wants and is like as a person","definitionCN":"对自身感受、愿望以及自己是怎样一个人的清楚认识","example":"Years of journaling gave him a quiet self-awareness about his temper.","exampleCN":"多年的日记让他对自己的脾气有了一种沉静的自觉。","why":"The compound joins the pronoun for one's own person to the word for being alert, so its first sense is simply being alert to oneself.","whyCN":"这个复合词把指「自身」的代词接到表示「警觉」的词上，因此第一个义项就是对自己保持警觉。"},{"no":"02","title":"Awareness of how others see you","titleCN":"意识到他人如何看待自己","definition":"recognition of the impression one makes on other people, including the unintended one","definitionCN":"认识到自己给他人留下的印象，包括那些并非本意的印象","example":"The feedback session raised her self-awareness about how often she interrupted.","exampleCN":"反馈环节让她意识到自己打断别人的次数有多频繁。","why":"Once the gaze turns outward and then back, a person can see the version of herself that exists in other minds.","whyCN":"当目光先向外再折回，人就能看见存在于他人心中的那个自己。"},{"no":"03","title":"Awareness of one's body and posture","titleCN":"对身体与姿态的觉察","definition":"noticing where one's body is, how it is balanced and what it is doing","definitionCN":"留意身体的位置、平衡方式与正在做的动作","example":"Ballet training builds self-awareness of the angle of the pelvis.","exampleCN":"芭蕾训练培养对骨盆角度的身体自觉。","why":"Proprioception is the oldest layer of the compound: the body reporting on itself before language does.","whyCN":"本体感觉是这个复合词最古老的一层：身体先于语言向自己报告。"},{"no":"04","title":"Knowing one's limits and biases","titleCN":"知道自己的局限与偏见","definition":"an accurate sense of where one's knowledge stops and where one's judgment is skewed","definitionCN":"对自己知识止于何处、判断偏向何处有准确的感觉","example":"Good forecasters show self-awareness about the topics they overrate.","exampleCN":"优秀的预测者对自己高估的领域有清醒的自觉。","why":"Knowing one's edges is the practical payoff of self-awareness, because a limit that is seen can be planned around.","whyCN":"知道自己的边界是自我意识的实用回报，因为被看见的局限可以被绕开。"},{"no":"05","title":"Monitoring oneself in the moment","titleCN":"在当下监控自己","definition":"catching oneself in the middle of an action and adjusting before it finishes","definitionCN":"在行动进行中察觉自己，并在结束前作出调整","example":"Halfway through the argument she noticed her voice rising and stopped.","exampleCN":"争到一半，她察觉自己声音在升高，于是停了下来。","why":"The same awareness can run live rather than retrospectively, and this live version is what allows correction in real time.","whyCN":"同一种觉察可以不事后而是实时运行，正是这种实时版本让人能够即时修正。"},{"no":"06","title":"Philosophical self-consciousness","titleCN":"哲学意义上的自我意识","definition":"the condition of a subject that is aware of itself as the one experiencing","definitionCN":"主体意识到自己正是那个正在体验的人这一状态","example":"The seminar asked whether self-awareness can exist without language.","exampleCN":"研讨课追问：没有语言是否还能有自我意识。","why":"Philosophy pushed the everyday sense to its limit, asking what it means for a mind to be an object to itself.","whyCN":"哲学把日常义推到极限，追问一颗心智把自己当作对象究竟意味着什么。"},{"no":"07","title":"A system representing its own state","titleCN":"系统对自身状态的表征","definition":"in technical use, the capacity of a system to hold a model of its own condition or reliability","definitionCN":"在技术语境中，指系统持有关于自身状况或可靠性的模型","example":"The monitoring module gives the robot a crude self-awareness of its battery and balance.","exampleCN":"监控模块让机器人对自己的电量和平衡有了粗略的自我感知。","why":"Engineers reuse the everyday term for machines that must report on themselves, and the borrowing is openly approximate.","whyCN":"工程师把日常说法挪用到必须报告自身状态的机器上，这种借用是公开的近似。"},{"no":"08","title":"Reflective awareness of one's learning","titleCN":"对自身学习的反思性觉察","definition":"noticing how one studies, what one avoids and which habits help","definitionCN":"留意自己如何学习、回避什么、哪些习惯有用","example":"The portfolio asks students for self-awareness about their own revision habits.","exampleCN":"这份学习档案要求学生反思自己的复习习惯。","why":"In education the compound narrows to learning, where awareness of habits is the first step to changing them.","whyCN":"在教育语境中，这个复合词收窄到学习上：对习惯的觉察是改变习惯的第一步。"}],"etymology":{"intro":{"en":"Self-awareness joins an Old English pronoun for one's own person to an English word for being watchful, and the compound is modern. Dates are approximate.","cn":"self-awareness 把古英语中指「自身」的代词，接到英语中表「警觉」的词上；这个复合词是近现代产物。年代均为约数。"},"items":[{"era":"OLD ENGLISH SELF","en":"Self worked as a pronoun and an adjective meaning 'the same person'. Its deeper origin is not established.","cn":"self 兼作代词与形容词，意为「同一个人」。其更早来源未得到证明。"},{"era":"OLD ENGLISH GEWAER","en":"Gewær meant 'watchful, wary', from a root for guarding; the modern word aware appears in the sixteenth century.","cn":"gewær 意为「警觉的、留心的」，出自表「看守」的词根；现代词形在十六世纪出现。"},{"era":"COMPOUND FORMED","en":"The compound self-awareness was built in the nineteenth century, first in philosophy and early psychology.","cn":"这个复合词在十九世纪构成，最早出现在哲学与早期心理学中。"},{"era":"PSYCHOLOGY SPLIT","en":"Twentieth-century psychology separated private awareness of one's inner state from public awareness of how one is seen.","cn":"二十世纪心理学把对内在状态的私下觉察，与对「自己如何被看见」的公开觉察区分开来。"},{"era":"MACHINE SENSE","en":"Late twentieth-century engineering added the technical sense of a system that models its own condition.","cn":"二十世纪后期，工程学增添了技术义：系统对自身状况建立模型。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first citation and deeper origin): the exact first printed use of the compound is unsettled, and the pre-Old-English origin of self is unknown, so any earlier form proposed for it is a reconstruction.","cn":"来源不确定（最早书证与更深来源）：这个复合词的确切最早用例尚无定论；self 在古英语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words built on the same self- or awareness stock that are constantly confused; group two holds near neighbours that name knowledge of oneself in other ways.","cn":"第一组是同出「自身」或「觉察」词干、极易混淆的词；第二组是以别的方式指「认识自己」的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"self-conscious","ipa":"/ˌself ˈkɒnʃəs/","tag":"too visible to oneself","definition":"Means awkwardly aware of being watched; the awareness is turned up until it interferes, which is not implied by self-awareness.","definitionCN":"指因被他人注视而局促，觉察强到妨碍行动，这层意思 self-awareness 并不带。"},{"word":"self-consciousness","ipa":"/ˌself kənˈʃəsnəs/","tag":"the state, often uneasy","definition":"The noun matching the uneasy adjective, and also a philosophical term for a subject aware of itself.","definitionCN":"是与那个局促形容词对应的名词，也作哲学术语指自我意识到自身的主体。"},{"word":"awareness","ipa":"/əˈweənəs/","tag":"without the self","definition":"Alertness to anything at all, from traffic to a rumour; it lacks the inward direction of the compound.","definitionCN":"指对任何事物的警觉，从车流到传闻；缺少这个复合词的向内方向。"},{"word":"consciousness","ipa":"/kənˈʃəsnəs/","tag":"waking or sentient state","definition":"The general state of being awake and sentient, far broader than knowing one's own character.","definitionCN":"指清醒而有感觉的一般状态，比「了解自己性格」宽泛得多。"}]},{"heading":"NEAR MEANING","entries":[{"word":"introspection","ipa":"/ˌɪntrəˈspekʃn/","tag":"looking inward","definition":"The deliberate examination of one's own thoughts; it is a method, while self-awareness is the resulting knowledge.","definitionCN":"指有意审视自身念头，是一种方法；自我意识是这样做之后得到的知识。"},{"word":"self-knowledge","ipa":"/ˌself ˈnɒlɪdʒ/","tag":"deep and settled","definition":"A lasting understanding of one's character, gained over years; self-awareness can also be a sharp momentary state.","definitionCN":"指多年积累的、对自身性格的持久了解；自我意识也可以是当下的一瞬清醒。"},{"word":"mindfulness","ipa":"/ˈmaɪndfəlnəs/","tag":"attention without judgment","definition":"A trained attention to the present moment; self-awareness may be anxious, evaluative or purely practical.","definitionCN":"指训练有素地注意当下；自我意识则可能是焦虑的、评判性的或纯实用的。"},{"word":"reflection","ipa":"/rɪˈflekʃn/","tag":"thinking back","definition":"Thinking over an experience afterwards; self-awareness includes instant awareness with no thinking back at all.","definitionCN":"指事后对某段经历的思考；自我意识也包含完全不必回想的即时觉察。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves of the compound and the real phrases it forms.","cn":"正常联想：这个复合词两个真实的构成部分，以及它构成的真实短语。"},"normal":[{"en":"The first half means one's own person and the second means being alert, so together they read 'alert to oneself'.","cn":"前半指「自身」，后半指「警觉」，合起来就是「对自己保持警觉」。"},{"en":"The adjective is self-aware and the bare noun is awareness, a family of three forms.","cn":"形容词是 self-aware，去掉自身成分的名词是 awareness，共三种词形。"},{"en":"Fixed phrases mark the field: develop self-awareness, heightened self-awareness, emotional self-awareness.","cn":"固定搭配标出使用范围：培养自我意识、更强的自我意识、情绪上的自我觉察。"},{"en":"Psychology separates the private version from the public version, where the second is about being seen.","cn":"心理学把私下觉察与公开觉察分开，后者关乎「被看见」。"},{"en":"Engineering borrows the word for machines that must report their own battery or balance.","cn":"工程学把这个词借去指必须报告自身电量或平衡的机器。"}],"abstract":[{"en":"Picture a mirror that shows not only the face but the reason for the frown.","cn":"想象一面不只照出脸、还照出皱眉原因的镜子。"},{"en":"Picture a torch that the walker points at her own feet.","cn":"想象走路的人把手电照向自己的脚。"},{"en":"Picture a report card a machine writes about its own condition.","cn":"想象一台机器给自己写出一份状况报告。"}]},"examples":[{"en":"The training aims to give new managers self-awareness about how they speak under pressure.","cn":"这项培训旨在让新经理意识到自己在压力下说话的样子。"},{"en":"Her self-awareness of the gap between her plan and her practice was unusually exact.","cn":"她对自己计划与实践之间差距的自觉异常精确。"},{"en":"A little self-awareness would have prevented the remark.","cn":"只要有一点自我觉察，那句话就不会说出口。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「self 自己 + awareness 觉察」——对自己保持觉察，就是自我意识","word":"self-awareness"},"root":"古英语 self「自身」+ 英语 aware「警觉的」及其名词后缀；aware 出自意为「看守」的古英语词根，self 的更早来源不确定。英语 self-awareness。","sensesIntro":{"en":"Eight senses follow one gesture: attention turned back on the person who is attending. It covers feelings and character, the image others hold, the body, the edges of one's knowledge, live self-correction, philosophical selfhood, a machine's self-report and the study of one's own habits.","cn":"八个义项沿同一个动作展开：注意力折回到正在注意的人身上。它覆盖情绪与性格、他人心中的形象、身体、知识的边界、实时的自我修正、哲学上的自我、机器的自我报告，以及对自身习惯的审视。"},"semanticMap":{"core":{"en":"CORE IMAGE: someone at a mirror who sees not only the face but the reason for the frown.","cn":"核心意象：站在镜前的人不只看见脸，还看见自己皱眉的原因。"},"chain":["FEEL SOMETHING","NAME THE STATE","SEE ONESELF FROM OUTSIDE","KNOW ONE'S LIMITS","MONITOR WHILE ACTING","MODEL ONE'S OWN STATE"],"branches":[{"senses":"01 · 05","en":"INNER AND LIVE: settled knowledge of one's feelings, and the same knowledge caught in the middle of an action.","cn":"内在与实时：对情绪的稳定认识，以及在行动中途被抓住的同一种认识。"},{"senses":"02","en":"THE OUTSIDE VIEW: the self that exists in other minds is seen only by turning the gaze outward first.","cn":"外部视角：存在于他人心中的自己，只有先把目光向外才看得见。"},{"senses":"03 · 04","en":"BODY AND EDGES: posture is the oldest layer, and the limits of knowledge are the most useful one.","cn":"身体与边界：姿态是最古老的一层，知识的边界是最有用的一层。"},{"senses":"06 · 08","en":"THEORETICAL AND PRACTICAL: philosophy asks what selfhood is, while education asks which study habits one actually has.","cn":"理论与实用：哲学追问自我是什么，教育则追问自己实际有哪些学习习惯。"},{"senses":"07","en":"SELF-REPORTING MACHINE: a system that models its own condition borrows the everyday word.","cn":"自我报告的机器：对自身状况建模的系统借用了这个日常词。"}]},"affixes":{"intro":{"en":"The compound is English throughout: an Old English pronoun plus an English noun, which is why it splits cleanly into two readable halves.","cn":"这个复合词从头到尾都是英语：一个古英语代词加一个英语名词，因此可以干净地切成两个可读的部分。"},"latinIntro":{"en":"There is no Latin element here; the neighbouring family is English, running self, self-aware, awareness, unaware and self-conscious.","cn":"这里没有拉丁语成分；相邻的词族是英语自身的，包括 self、self-aware、awareness、unaware 与 self-conscious。"},"items":[{"word":"self","structure":"self (Old English pronoun and noun)","meaning":"one's own person","meaningCN":"自身","example":"The first half points the whole word back at the person.","exampleCN":"前半部分让整个词指回本人。"},{"word":"aware","structure":"aware (English adjective, from an Old English word for watchful)","meaning":"watchful, noticing","meaningCN":"警觉的；察觉的","example":"The second half supplies the noticing.","exampleCN":"后半部分提供「察觉」的意思。"},{"word":"-ness","structure":"-ness (English noun suffix)","meaning":"state or quality","meaningCN":"状态或性质","example":"The suffix turns the adjective aware into a state that can grow or fade.","exampleCN":"这个后缀把形容词变成可以增减的状态。"},{"word":"awareness","structure":"aware + -ness","meaning":"the state of noticing","meaningCN":"察觉的状态","example":"The bare noun is the centre of the compound.","exampleCN":"这个不带自身成分的名词是复合词的中心。"},{"word":"self-awareness","structure":"self + awareness","meaning":"noticing one's own state","meaningCN":"对自身状态的察觉","example":"The compound aims the bare noun at the person who has it.","exampleCN":"这个复合词把那个名词对准拥有它的本人。"},{"word":"self-aware","structure":"self + aware","meaning":"noticing oneself","meaningCN":"对自身有觉察的","example":"The adjective drops the state suffix and keeps the quality.","exampleCN":"形容词去掉表状态的后缀，只留性质。"},{"word":"unaware","structure":"un- 'not' + aware","meaning":"not noticing","meaningCN":"未察觉的","example":"The negative prefix marks the absence of the whole state.","exampleCN":"否定前缀标出整个状态的缺席。"},{"word":"self-conscious","structure":"self + conscious","meaning":"awkwardly aware of being seen","meaningCN":"因被注视而局促的","example":"A different second half gives a different, uneasy meaning.","exampleCN":"换掉后半部分，意思就变成局促不安。"},{"word":"self-knowledge","structure":"self + knowledge","meaning":"settled understanding of oneself","meaningCN":"对自身的稳定了解","example":"Another compound shows the same first half with a lasting second half.","exampleCN":"另一个复合词用同样的前半，配上表示持久了解的后半。"}],"latinEntries":[]}},{"word":"decision","ipa_uk":"/dɪˈsɪʒn/","ipa_us":"/dɪˈsɪʒn/","definition_zh":"决定；决策；裁决；果断","definition_en":"a choice reached after weighing possibilities, or the act of reaching it; also a formal ruling","core_image":"桌上摊开三张纸，一只手把其中两张推到一边，只留一张","scene":"工程师把三份录用通知摊在桌上，比较了整整一周。After a week of weighing three offers, she finally reaches a decision.","sceneCN":"这里 decision 指「权衡后作出的取舍」（第 1 个义项：经过考虑后选定的结果）；句意为她比较三份录用通知整整一周后终于作出决定。场景要素：三份通知、摊开的桌面、笔。","pos":[{"tag":"n.","zh":"决定；决策；裁决；果断"}],"collocations":[{"phrase":"make a decision","zh":"作出决定"},{"phrase":"reach a decision","zh":"达成决定"},{"phrase":"a difficult decision","zh":"艰难的决定"},{"phrase":"decision-making process","zh":"决策过程"},{"phrase":"a final decision","zh":"最终裁决"},{"phrase":"act with decision","zh":"果断行动"}],"forms":[{"label":"复数","form":"decisions"},{"label":"动词","form":"decide"},{"label":"形容词","form":"decisive"},{"label":"副词","form":"decisively"},{"label":"名词（优柔寡断）","form":"indecision"}],"derivatives":[{"word":"decide","pos":"v.","zh":"由拉丁语「切断」的动词进入英语，指在选项中作出取舍"},{"word":"decisive","pos":"adj.","zh":"由 decide 加形容词后缀构成，指能一锤定音的"},{"word":"decisively","pos":"adv.","zh":"由 decisive 加副词后缀构成，指以果断的方式"},{"word":"decisiveness","pos":"n.","zh":"由 decisive 加构成，指果断的性质"},{"word":"indecision","pos":"n.","zh":"由否定前缀加 decision 构成，指犹豫不决"},{"word":"indecisive","pos":"adj.","zh":"由否定前缀加 decisive 构成，指拿不定主意的"}],"senses":[{"no":"01","title":"A choice reached after weighing","titleCN":"权衡后作出的选择","definition":"a conclusion about what to do, reached after comparing the available possibilities","definitionCN":"在比较各种可能之后得出的、关于该怎么做的结论","example":"The committee's decision was to postpone the launch by one season.","exampleCN":"委员会的决定是把发布推迟一个季度。","why":"The Latin verb underneath means 'to cut off', so the core gesture is separating one option from the rest and keeping it.","whyCN":"它下面的拉丁动词意为「切断」，因此核心动作是把一个选项与其余选项切开并留下。"},{"no":"02","title":"The act of choosing","titleCN":"作选择这一行为","definition":"the process of choosing rather than the choice that results","definitionCN":"指作选择的过程，而非由此得到的结果","example":"Decision took less than a minute once the numbers were on the table.","exampleCN":"数据一摆上桌，作决定用了不到一分钟。","why":"English uses one noun for both the act and the outcome, which is why the same word appears with process and with result.","whyCN":"英语用一个名词同时指行为与结果，因此同一个词既与「过程」也与「结果」搭配。"},{"no":"03","title":"A ruling by a court","titleCN":"法院的裁决","definition":"the formal judgment by which a court settles a case","definitionCN":"法院据以了结案件的正式判定","example":"The court's decision bound all lower tribunals.","exampleCN":"法院的裁决对下级法庭均有约束力。","why":"Law took the word early because a case is literally cut off when a ruling is given.","whyCN":"法律很早就采用这个词，因为一旦作出判定，案件就被切断了。"},{"no":"04","title":"A formal resolution by a body","titleCN":"机构的正式决议","definition":"an official resolution adopted by a committee, board or assembly","definitionCN":"委员会、董事会或大会正式通过的决议","example":"The board recorded its decision in the minutes.","exampleCN":"董事会把决议记入会议记录。","why":"A collective body cannot act without a recorded choice, so the word also names the entry in the minutes.","whyCN":"集体机构不记下选择便无法行动，因此这个词也指会议记录中的那一条。"},{"no":"05","title":"The quality of being decisive","titleCN":"果断这一品质","definition":"firmness in acting or speaking, rather than the choice itself","definitionCN":"行动或言语上的坚定，而非选择本身","example":"She answered with a decision that ended the debate.","exampleCN":"她答得果断，辩论就此结束。","why":"An older abstract use survives in fixed phrases, where the noun names a manner rather than a choice.","whyCN":"一种更古老的抽象用法留在固定短语里，那里的名词指一种作风而非一次选择。"},{"no":"06","title":"A win awarded on points","titleCN":"拳击中按点数判胜","definition":"in boxing, a victory given by the judges rather than by a knockout","definitionCN":"拳击比赛中由裁判判给而非击倒取得的胜利","example":"He won on a unanimous decision after ten rounds.","exampleCN":"十回合后他以一致判定获胜。","why":"Judges also 'cut off' a contest when no knockout settles it, so the legal sense extends naturally to sport.","whyCN":"当无人被击倒时，裁判也要为比赛「切断」一个结果，法律义于是自然延伸到体育。"},{"no":"07","title":"A determination by an official body","titleCN":"行政机构的裁定","definition":"an official determination by an agency that settles a claim or application","definitionCN":"行政机关对申请或主张作出的正式裁定","example":"The agency issued a decision granting the permit.","exampleCN":"该机构作出裁定，批准了这项许可。","why":"Administrative law needs a countable noun for each determination, and the word fills that slot.","whyCN":"行政法需要为每一项裁定准备一个可数名词，这个词正好填上这个位置。"},{"no":"08","title":"A point where a choice must be made","titleCN":"必须作出选择的节点","definition":"a stage in a process at which the next step has to be chosen rather than continued","definitionCN":"流程中必须选定下一步、而不能照旧推进的环节","example":"The project reached a decision before any money was spent.","exampleCN":"项目在任何钱花出去之前就到了必须定夺的节点。","why":"Process language turns the abstract noun into a countable landmark, which is why the word appears before point and gate.","whyCN":"流程语言把这个抽象名词变成可数的地标，因此它常出现在「节点」「关口」一类词之前。"}],"etymology":{"intro":{"en":"Decision comes from Latin decisio, built on decidere 'to cut off, settle', which joins a prefix meaning 'off' to the verb for cutting. Dates are approximate.","cn":"decision 来自拉丁语 decisio，建立在 decidere「切断、了结」之上；后者把表「离开」的前缀接到表「切」的动词上。年代均为约数。"},"items":[{"era":"LATIN CAEDERE","en":"Caedere meant 'to cut, strike down'. The same verb supplies precise, concise, incision and homicide.","cn":"caedere 意为「切、砍倒」。同一个动词还构成 precise、concise、incision 与 homicide。"},{"era":"LATIN DECIDERE","en":"De- 'off, away' plus caedere produced decidere 'to cut off', hence 'to settle, determine'.","cn":"意为「离开、去掉」的拉丁前缀加 caedere 构成 decidere「切下」，因此有「了结、判定」的意思。"},{"era":"LATIN DECISIO","en":"The noun decisio named a settlement or the act of cutting a matter short.","cn":"名词 decisio 指一次了结，或把一件事就此截断的行为。"},{"era":"OLD FRENCH","en":"Old French carried the noun into English in the fifteenth century, at first in legal and administrative settings.","cn":"古法语在十五世纪把这个名词带入英语，最初用于法律与行政场合。"},{"era":"LEGAL AND GENERAL","en":"Law kept the ruling sense while everyday speech took the choosing sense, and both survive side by side.","cn":"法律保留了「裁决」义，日常语言则取「选择」义，两者并行至今。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use of the noun is recorded only approximately, and the deeper origin of caedere is unsettled, so any Indo-European form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：这个名词的最早英语用例只有约略记载；caedere 的更早来源亦无定论，凡为其提出的印欧形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds words that share the cutting root or are mistaken for it; group two holds near neighbours for a choice or a ruling.","cn":"第一组是同出「切」词根、或常被误认为同源的词；第二组是表示选择或裁定的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decide","ipa":"/dɪˈsaɪd/","tag":"the verb","definition":"The verb that produces the noun; it takes an object or a clause, while decision takes a preposition or a verb of making.","definitionCN":"产生这个名词的动词；它可直接带宾语或从句，而 decision 常与介词或「作出」类动词搭配。"},{"word":"decisive","ipa":"/dɪˈsaɪsɪv/","tag":"settling a matter","definition":"An adjective for what settles an outcome, as in a decisive battle; it does not mean the same as having made a decision.","definitionCN":"形容能决定结局的，如决定性战役；它与「已经作出决定」并不等同。"},{"word":"division","ipa":"/dɪˈvɪʒn/","tag":"different root","definition":"From the verb for dividing, where the prefix means 'apart' and the root means 'separate', not 'cut off'; the two are often confused.","definitionCN":"来自表「分开」的动词，其前缀意为「分开」、词根意为「分离」，并非「切断」；两者常被混淆。"},{"word":"precision","ipa":"/prɪˈsɪʒn/","tag":"same cutting root","definition":"Built on the prefix meaning 'beforehand' plus the cutting verb, so it means cutting cleanly, hence exactness.","definitionCN":"由表「事先」的前缀加表「切」的动词构成，意为切得干净，因此指精确。"}]},{"heading":"NEAR MEANING","entries":[{"word":"choice","ipa":"/tʃɔɪs/","tag":"plain everyday word","definition":"The ordinary word for picking one of several things; decision adds the idea of deliberation and closure.","definitionCN":"指从若干事物中取一的日常词；decision 多了反复权衡与一锤定音的意思。"},{"word":"verdict","ipa":"/ˈvɜːdɪkt/","tag":"a spoken finding","definition":"The formal finding of a jury or judge, literally 'a true saying'; it is narrower than the legal sense of decision.","definitionCN":"指陪审团或法官的正式认定，字面是「如实说出」；比 decision 的法律义更窄。"},{"word":"resolution","ipa":"/ˌrezəˈluːʃn/","tag":"a formal resolve","definition":"A formal statement adopted by a body, or a firm personal intention; it stresses the settling of will.","definitionCN":"指机构通过的正式声明，或个人的坚定决心，强调意志的落定。"},{"word":"determination","ipa":"/dɪˌtɜːmɪˈneɪʃn/","tag":"fixing an outcome","definition":"The act of fixing something firmly, as a boundary or an official finding; it stresses finality, not the weighing.","definitionCN":"指把某事牢牢定下，如边界或官方认定；强调终局性，而非权衡过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real cutting root, the real family and the real phrases.","cn":"正常联想：真实的「切」词根、真实的词族与真实的短语。"},"normal":[{"en":"The Latin verb underneath means to cut off, so deciding is cutting the other options away.","cn":"下面的拉丁动词意为「切断」，因此作决定就是把其他选项切走。"},{"en":"The family runs decide, decision, decisive, decisively, indecision, indecisive.","cn":"同族词包括 decide、decision、decisive、decisively、indecision、indecisive。"},{"en":"Fixed phrases mark the process: make a decision, reach a decision, a difficult decision.","cn":"固定搭配标出过程：作出决定、达成决定、艰难的决定。"},{"en":"The same cutting root appears in precise and concise, where cutting cleanly means being exact or brief.","cn":"同一个「切」词根还出现在 precise 与 concise 中，切得干净就是精确或简短。"},{"en":"Law kept the older sense, so a court's decision is still a ruling rather than a preference.","cn":"法律保留了较旧的义项，因此法院的 decision 仍指裁决而非偏好。"}],"abstract":[{"en":"Picture three doors and a hand closing two of them.","cn":"想象三扇门，一只手把其中两扇关上。"},{"en":"Picture a rope cut at one point so the boat can only drift one way.","cn":"想象绳子在某处被剪断，船只能往一个方向漂。"},{"en":"Picture a coin held on its edge for a long time and then let fall.","cn":"想象一枚硬币长时间立在边缘，最后被放开倒下。"}]},"examples":[{"en":"The hardest part of the job is not the analysis but the decision.","cn":"这份工作最难的不是分析，而是拍板。"},{"en":"A late decision cost the team a whole month of preparation.","cn":"迟迟不作决定，让团队损失了整整一个月的准备时间。"},{"en":"The tribunal published its decision on the disputed border.","cn":"法庭公布了关于边界争议的裁决。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「de 去掉 + cis 切」——把别的选项切掉，只留一个，就是决定","word":"decision"},"root":"拉丁 decidere「切断、了结」由意为「离开、去掉」的前缀加 caedere「切」构成；caedere 更深来源不确定。名词 decisio 经古法语进入英语，即 decision。","sensesIntro":{"en":"Eight senses follow one cut: options are separated and one is kept. The cut is then read as the choice, the choosing, a court's ruling, a body's resolution, a manner of firmness, a judge's verdict, an agency's determination and a stage in a process.","cn":"八个义项沿同一刀展开：把选项分开并留下一个。这一刀随后被读作选择结果、作选择的行为、法院裁决、机构决议、果断的作风、裁判的判定、行政机关的裁定，以及流程中的一个节点。"},"semanticMap":{"core":{"en":"CORE IMAGE: three sheets on a table and a hand pushing two of them aside.","cn":"核心意象：桌上摊着三张纸，一只手把其中两张推到一边。"},"chain":["WEIGH OPTIONS","CUT ONE OFF","COMMIT","RULE","RESOLVE FORMALLY","POINT OF CHOICE"],"branches":[{"senses":"01 · 02","en":"THE CUT AND THE CUTTING: the settled choice and the act of settling it are one event seen from two ends.","cn":"切口与切割：落定的选择与作出选择的行为，是同一件事的两端。"},{"senses":"03 · 07","en":"OFFICIAL CUTS: a court's ruling and an agency's determination both end a matter by authority.","cn":"官方之切：法院裁决与行政机关裁定，都以权威了结一件事。"},{"senses":"04","en":"COLLECTIVE CUT: a board cannot act until its choice is recorded as a resolution.","cn":"集体之切：董事会必须把选择记成决议才能行动。"},{"senses":"05","en":"MANNER, NOT CHOICE: the older abstract sense names firmness of speech or action.","cn":"作风而非选择：较古的抽象义指言语或行动上的坚定。"},{"senses":"06 · 08","en":"CUTS IN OTHER FIELDS: judges cut off a bout, and process language cuts a path at a decision point.","cn":"别的领域的切：裁判为一场比赛切出结果，流程语言则在节点上把路径切开。"}]},"affixes":{"intro":{"en":"Decision is a Latin prefix, a Latin cutting root and a Latin noun suffix, and each piece builds other English words.","cn":"decision 由一个拉丁前缀、一个表「切」的拉丁词根和一个拉丁名词后缀构成，每一部分都还构成别的英语词。"},"latinIntro":{"en":"The cutting root supplies precise, concise, incision and homicide; the prefix meaning 'off' recurs in deduce, depart and decline.","cn":"表「切」的词根衍生出 precise、concise、incision 与 homicide；表「离开」的前缀还出现在 deduce、depart 与 decline 中。"},"items":[{"word":"de-","structure":"de- (Latin prefix, 'off, away, down')","meaning":"off; away","meaningCN":"离开；去掉","example":"The prefix says the cutting removes something.","exampleCN":"这个前缀表示这一刀把某物去掉。"},{"word":"caedere","structure":"caedere (Latin verb, third conjugation)","meaning":"to cut, strike down","meaningCN":"切；砍倒","example":"The root supplies the physical image of a cut.","exampleCN":"这个词根提供「切」的具体意象。"},{"word":"decidere","structure":"de- + caedere","meaning":"to cut off, settle","meaningCN":"切断；了结","example":"Cutting a matter off is what settling it felt like.","exampleCN":"把一件事切断了结，正是「判定」当初的感觉。"},{"word":"decision","structure":"decisio (Latin noun) through French","meaning":"a settlement, a choice","meaningCN":"了结；决定","example":"The noun names both the cut and the state it leaves.","exampleCN":"这个名词同时指那一刀和它留下的状态。"},{"word":"-sion","structure":"-sio (Latin noun suffix on the supine stem)","meaning":"act or result","meaningCN":"行为或结果","example":"The suffix turns the verb into a countable event.","exampleCN":"这个后缀把动词变成可数的事件。"},{"word":"decide","structure":"decidere through French","meaning":"to settle, determine","meaningCN":"决定；判定","example":"The verb is the action that the noun records.","exampleCN":"动词是这个名词所记录的动作。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix)","meaning":"tending to settle","meaningCN":"有决定作用的","example":"The suffix gives the adjective its sense of settling an outcome.","exampleCN":"这个后缀让形容词带上「决定结局」的意思。"},{"word":"decisive","structure":"decide + -ive","meaning":"settling a matter","meaningCN":"起决定作用的；果断的","example":"The adjective describes what ends a contest or a doubt.","exampleCN":"这个形容词形容能终止较量或疑虑的事物。"},{"word":"in-","structure":"in- (Latin negative prefix)","meaning":"not","meaningCN":"不","example":"The negative prefix creates the whole family of hesitation words.","exampleCN":"这个否定前缀造出了整个表示犹豫的词族。"},{"word":"indecision","structure":"in- + decision","meaning":"the state of not deciding","meaningCN":"犹豫不决","example":"The noun names the cut that is never made.","exampleCN":"这个名词指始终没有落下的那一刀。"}],"latinEntries":[{"word":"caedere","structure":"caedere, cecidi, caesum (verb, third conjugation)","meaning":"to cut, strike down","meaningCN":"切；砍"},{"word":"decidere","structure":"decidere, decidi, decisum (verb, third conjugation)","meaning":"to cut off, settle","meaningCN":"切断；了结"},{"word":"decisio","structure":"decisio, decisionis (f., third declension)","meaning":"a settlement, a decision","meaningCN":"了结；决定"},{"word":"decisus","structure":"decisus, -a, -um (past participle)","meaning":"cut off, settled","meaningCN":"被切断的；已了结的"}]}},{"word":"decision-making","ipa_uk":"/dɪˈsɪʒn ˈmeɪkɪŋ/","ipa_us":"/dɪˈsɪʒn ˈmeɪkɪŋ/","definition_zh":"决策；决策过程；作出取舍的全过程","definition_en":"the process of choosing among options, especially in organizations, groups or under uncertainty","core_image":"白板上写着五条路线，一支笔把其中四条逐条划掉","scene":"会议室里，五个人把可选方案写到白板上，一条条打分再划掉。The board wants faster decision-making before the funding deadline.","sceneCN":"这里 decision-making 指「在多个方案中作出取舍的全过程」（第 1 个义项：在选项之间作选择的过程）；句意为董事会希望在资金截止前加快决策。场景要素：白板、五条路线、打分表、记号笔。","pos":[{"tag":"n.","zh":"决策；决策过程"}],"collocations":[{"phrase":"decision-making process","zh":"决策过程"},{"phrase":"shared decision-making","zh":"共同决策"},{"phrase":"decision-making authority","zh":"决策权"},{"phrase":"group decision-making","zh":"群体决策"},{"phrase":"evidence-based decision-making","zh":"循证决策"},{"phrase":"decision-making under uncertainty","zh":"不确定条件下的决策"}],"forms":[{"label":"复数（罕用）","form":"decision-makings"},{"label":"定语用法","form":"decision-making body"},{"label":"相关名词","form":"decision-maker"}],"derivatives":[{"word":"decision-maker","pos":"n.","zh":"由 decision-making 去掉动名词后缀后加表人后缀构成，指有权作决定的人"},{"word":"decision","pos":"n.","zh":"该复合词的前半，指一次具体的取舍或裁决"},{"word":"decisive","pos":"adj.","zh":"与 decision 同出「切断」词根，指能一锤定音的或果断的"},{"word":"indecision","pos":"n.","zh":"由否定前缀加 decision 构成，指迟迟无法取舍"}],"senses":[{"no":"01","title":"The process of choosing among options","titleCN":"在选项间作选择的过程","definition":"the whole activity of comparing possibilities and settling on one","definitionCN":"比较各种可能并最终选定一个的整个过程","example":"The workshop mapped every step of decision-making from problem to follow-up.","exampleCN":"工作坊把决策从提出问题到后续跟进的每一步都画了出来。","why":"The compound names the activity rather than the result, so it always looks at the stretch of time in which a choice is formed.","whyCN":"这个复合词指活动而非结果，因此它看的始终是选择形成的那段时间。"},{"no":"02","title":"Decision-making inside an organization","titleCN":"组织内部的决策","definition":"the routines by which a firm or agency turns information into authorized action","definitionCN":"企业或机构把信息转化为获准行动的常规程序","example":"The audit found that decision-making had stalled between two departments.","exampleCN":"审计发现决策在两个部门之间卡住了。","why":"Organizations need a name for the whole chain of meetings, memos and signatures, and this compound supplies it.","whyCN":"组织需要为会议、备忘与签字这一整条链条起个名字，这个复合词正好提供。"},{"no":"03","title":"Group decision-making","titleCN":"群体决策","definition":"the process by which several people reach a joint choice, with its own risks of conformity","definitionCN":"若干人共同作出选择的过程，伴有从众等特有风险","example":"Group decision-making produced a safer plan but a slower timetable.","exampleCN":"群体决策产生了更稳妥的方案，却换来更慢的时间表。","why":"Once more than one mind is involved, the process acquires its own dynamics, so it needs its own label.","whyCN":"一旦不止一个头脑参与，这个过程就有了自己的动力学，因此需要单独的标签。"},{"no":"04","title":"Shared decision-making in medicine","titleCN":"医疗中的共同决策","definition":"the practice of a clinician and a patient choosing a treatment together","definitionCN":"医生与病人共同选定治疗方案的作法","example":"Shared decision-making reduced the number of abandoned treatments.","exampleCN":"共同决策减少了中途放弃治疗的人数。","why":"Here the choice belongs to no single party, so the compound is borrowed to name a partnership rather than a hierarchy.","whyCN":"这里的选择不属于任何一方，于是借这个复合词来指一种伙伴关系而非层级关系。"},{"no":"05","title":"Intuitive decision-making","titleCN":"凭直觉的决策","definition":"choosing quickly on the basis of trained feeling rather than explicit calculation","definitionCN":"依靠训练出的感觉而非明确计算迅速作选择","example":"Firefighters often rely on intuitive decision-making built from years of drills.","exampleCN":"消防员常依靠多年演练积累的直觉决策。","why":"Experts compress experience into a fast judgment, and the compound marks this speed as a distinct mode.","whyCN":"行家把经验压缩成快速判断，这个复合词把这种速度标为一种独立模式。"},{"no":"06","title":"Analytical decision-making","titleCN":"分析式的决策","definition":"choosing by comparing data, models and explicit criteria","definitionCN":"通过比较数据、模型与明确标准来作选择","example":"The team switched to analytical decision-making once the sample was large enough.","exampleCN":"样本足够大之后，团队转向分析式决策。","why":"The same process can be run slowly and in writing, and the compound distinguishes that mode from the fast one.","whyCN":"同一个过程也可以慢慢地、以书面方式运行，这个复合词把这模式与快速模式区分开。"},{"no":"07","title":"Decision-making under uncertainty","titleCN":"不确定条件下的决策","definition":"choosing when the outcomes cannot be known for certain, only estimated","definitionCN":"在结果无法确知、只能估计的情况下作选择","example":"Hiring under uncertainty is the hardest kind of decision-making there is.","exampleCN":"在不确定中招人，是最难的一种决策。","why":"Most real choices lack clean data, so the compound grew a qualifier that names the fog rather than hiding it.","whyCN":"真实的选择大多没有干净的数据，于是这个复合词长出一个限定语，点明迷雾而不是掩盖它。"},{"no":"08","title":"Algorithmic decision-making","titleCN":"算法决策","definition":"choices produced or ranked by automated systems, with human review sometimes added","definitionCN":"由自动化系统作出或排序的选择，有时附加人工复核","example":"The city added human review to its algorithmic decision-making about benefits.","exampleCN":"该市在福利相关的算法决策中加入了人工复核。","why":"When a machine performs the choosing, the same noun is kept and a technical qualifier is added, because the social questions stay the same.","whyCN":"当由机器来做选择时，同一个名词被保留，只加一个技术限定语，因为社会层面的问题并未改变。"}],"etymology":{"intro":{"en":"Decision-making is an English compound of a Latin-derived noun and an English gerund, formed in modern management and psychology. Dates are approximate.","cn":"decision-making 是由一个拉丁来源的名词加一个英语动名词构成的复合词，形成于现代管理学与心理学。年代均为约数。"},"items":[{"era":"LATIN DECIDERE","en":"The first half rests on the Latin verb meaning 'to cut off, settle', built from a prefix meaning 'off' and a verb for cutting.","cn":"前半部分基于拉丁语中意为「切断、了结」的动词，由表「离开」的前缀与表「切」的动词构成。"},{"era":"OLD ENGLISH MACIAN","en":"The second half descends from Old English macian 'to form, construct'; its deeper Germanic origin is not established.","cn":"后半部分源自意为「做成、构造」的古英语动词，其更早的日耳曼语来源未得到证明。"},{"era":"ENGLISH GERUND","en":"The ending is the old English suffix that turns a verb into the name of an activity.","cn":"词尾是古英语中把动词变成活动名称的后缀。"},{"era":"MODERN COMPOUND","en":"The compound took shape in twentieth-century management science and psychology, where the steps of a choice became an object of study.","cn":"这个复合词在二十世纪的管理学与心理学中成形，那里选择步骤本身成了研究对象。"},{"era":"SPREAD TO OTHER FIELDS","en":"Medicine, law and public policy borrowed it in the later twentieth century, adding qualifiers such as shared and algorithmic.","cn":"二十世纪后期，医学、法律与公共政策借用了它，并加上「共同」「算法」一类限定语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use of the compound): no exact earliest citation is settled, and the deeper origin of the English verb for making is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（这个复合词的最早书证）：确切的最早用例尚无定论；那个英语中表「做」的动词更深来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the same-family nouns and verbs that are easy to swap; group two holds neighbouring activities that a choice is often confused with.","cn":"第一组是同词族、极易张冠李戴的名词与动词；第二组是常与「作选择」混淆的相邻活动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decision","ipa":"/dɪˈsɪʒn/","tag":"the single choice","definition":"One settled choice or one ruling; the compound instead names the whole activity that produces such choices.","definitionCN":"指一次落定的选择或一项裁决；而这个复合词指产生这些选择的整个活动。"},{"word":"decision-maker","ipa":"/dɪˈsɪʒn ˈmeɪkə/","tag":"the person","definition":"The person or body that chooses; the compound names what that person does, not who they are.","definitionCN":"指作选择的人或机构；复合词说的是这个人做的事，而不是他是谁。"},{"word":"making","ipa":"/ˈmeɪkɪŋ/","tag":"the second half alone","definition":"The gerund of the verb for making, used for producing or causing; alone it says nothing about options.","definitionCN":"是表「做、造」的动名词，单独用时与选项毫无关系。"},{"word":"decisive","ipa":"/dɪˈsaɪsɪv/","tag":"settling an outcome","definition":"An adjective for what ends a contest or a doubt; it does not name a process.","definitionCN":"形容能终结较量或疑虑的，并不指一个过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"problem-solving","ipa":"/ˈprɒbləm ˌsɒlvɪŋ/","tag":"finding a workable answer","definition":"The search for a solution to a defined difficulty; a decision may follow, but the search itself is not the choosing.","definitionCN":"指为已界定的难题寻找可行解；决策可能随后发生，但寻找本身不是取舍。"},{"word":"planning","ipa":"/ˈplænɪŋ/","tag":"laying out steps","definition":"Deciding in advance what will be done and in what order; it produces a schedule rather than a single commitment.","definitionCN":"指事先确定要做什么、按什么次序做；它产出的是日程而非一次承诺。"},{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"forming an opinion","definition":"The weighing of evidence into an opinion or ruling; decision-making stresses the choosing among actions.","definitionCN":"指把证据权衡成一个看法或裁决；决策强调的是在行动方案间取舍。"},{"word":"choice","ipa":"/tʃɔɪs/","tag":"the everyday word","definition":"The plain noun for picking one of several things, with no suggestion of an organized process.","definitionCN":"指从若干事物中取一的日常名词，不带「有组织的过程」这层意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves, the real compounding pattern and the real professional phrases.","cn":"正常联想：两个真实的构成部分、真实的复合方式与真实的专业搭配。"},"normal":[{"en":"The first half is a noun for a settled choice and the second is the activity of making, so the compound names the making of choices.","cn":"前半是表示落定选择的名词，后半是「做」这一活动，因此复合词说的就是「做出选择」。"},{"en":"The family runs decide, decision, decision-maker, decisive, indecision.","cn":"同族词包括 decide、decision、decision-maker、decisive、indecision。"},{"en":"Professional phrases mark the field: shared decision-making, evidence-based decision-making, decision-making authority.","cn":"专业搭配标出使用范围：共同决策、循证决策、决策权。"},{"en":"The pattern noun plus gerund is very productive in English, as in problem-solving and policy-making.","cn":"名词加动名词的模式在英语里很有生产力，例如表示解题与政策制定的复合词。"},{"en":"Qualifiers show the mode: intuitive, analytical, group, algorithmic, under uncertainty.","cn":"限定语标出模式：直觉的、分析的、群体的、算法的、不确定条件下的。"}],"abstract":[{"en":"Picture five paths on a board and a pen crossing out four.","cn":"想象白板上五条路径，一支笔划掉四条。"},{"en":"Picture a thermostat that weighs two readings before switching the heater.","cn":"想象一个恒温器，在切换加热前先权衡两个读数。"},{"en":"Picture a table where five people each hold one piece of the same decision.","cn":"想象一张桌子，五个人各自握同一个决定的一部分。"}]},"examples":[{"en":"Slow decision-making protected the forest but delayed the road by two years.","cn":"缓慢的决策保护了森林，却把修路推迟了两年。"},{"en":"The clinic trains staff in shared decision-making with older patients.","cn":"这家诊所训练员工与年长病人共同决策。"},{"en":"Poor decision-making under uncertainty is often a matter of missing feedback.","cn":"不确定条件下决策不佳，往往是因为缺少反馈。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「decision 决定 + making 做」——把决定做出来，就是决策","word":"decision-making"},"root":"英语复合词：decision（拉丁 decidere「切断、了结」的名词形）+ making（古英语 macian「做成」的动名词）；两部分的更深来源分别不确定。","sensesIntro":{"en":"Eight senses follow one stretch of activity: options are framed, weighed and cut down to one. The stretch is then read as a general process, as an organizational routine, as a group act, as a medical partnership, as fast intuition, as slow analysis, as choosing in fog, and as choosing done by a machine.","cn":"八个义项沿同一段活动展开：摆出选项、权衡、再削减到一个。这段活动随后被读作一般过程、组织常规、群体行为、医疗中的伙伴关系、快速直觉、缓慢分析、在迷雾中选择，以及由机器完成的选择。"},"semanticMap":{"core":{"en":"CORE IMAGE: five routes on a whiteboard and a pen crossing out four of them.","cn":"核心意象：白板上五条路线，一支笔把其中四条划掉。"},"chain":["FRAME OPTIONS","WEIGH THEM","CHOOSE ONE","ACT ON IT","REVIEW THE RESULT","REPEAT THE CYCLE"],"branches":[{"senses":"01 · 07","en":"THE GENERAL AND THE FOGGY: the plain process, and the same process run when outcomes can only be estimated.","cn":"一般与迷雾：平常的过程，以及结果只能估计时运行的同一过程。"},{"senses":"02 · 03","en":"MANY MINDS: an organization's routine and a group's joint choice both multiply the voices in the room.","cn":"多个头脑：组织常规与群体共同选择，都让房间里的声音变多。"},{"senses":"04","en":"SHARED AUTHORITY: in medicine the choice belongs to clinician and patient together, so the process becomes a partnership.","cn":"共享权威：医疗中选择同属医生与病人，过程因此成为伙伴关系。"},{"senses":"05 · 06","en":"FAST AND SLOW: intuition compresses experience, analysis spreads it out in tables.","cn":"快与慢：直觉把经验压紧，分析把经验摊成表格。"},{"senses":"08","en":"THE MACHINE CHOOSES: automation keeps the noun but adds a qualifier, because the social questions survive.","cn":"机器来选择：自动化保留了这个名词，只加限定语，因为社会层面的问题仍在。"}]},"affixes":{"intro":{"en":"The compound is half Latin and half English, and the English half is a gerund that can also stand alone.","cn":"这个复合词一半来自拉丁语、一半来自英语，英语那一半是可以独立使用的动名词。"},"latinIntro":{"en":"The Latin half brings decide, decisive, decision and indecision; the English half brings make, maker, making and remake.","cn":"拉丁那一半带来 decide、decisive、decision 与 indecision；英语那一半带来 make、maker、making 与 remake。"},"items":[{"word":"decision","structure":"decisio (Latin noun) through French","meaning":"a settled choice","meaningCN":"落定的选择","example":"The first half supplies the object that the activity produces.","exampleCN":"前半提供这项活动所产出的对象。"},{"word":"make","structure":"macian (Old English verb)","meaning":"to form, produce","meaningCN":"做成；产生","example":"The second half supplies the doing.","exampleCN":"后半提供「做」这一动作。"},{"word":"-ing","structure":"-ing (English gerund suffix)","meaning":"the activity of doing","meaningCN":"做某事这一活动","example":"The suffix turns the verb into the name of a process.","exampleCN":"这个后缀把动词变成过程的名称。"},{"word":"decision-making","structure":"decision + making","meaning":"the activity of choosing","meaningCN":"作选择的活动","example":"The compound is the standard term in management and psychology.","exampleCN":"这个复合词是管理学与心理学中的标准术语。"},{"word":"-er","structure":"-er (English agent suffix)","meaning":"one who does","meaningCN":"做某事的人","example":"The suffix produces the person who performs the activity.","exampleCN":"这个后缀造出从事该活动的人。"},{"word":"decision-maker","structure":"decision-making + -er","meaning":"one who chooses","meaningCN":"作决定的人","example":"The person form is far more common than the plural of the compound.","exampleCN":"指人的形式远比这个复合词的复数常用。"},{"word":"decisive","structure":"decision + -ive","meaning":"settling the outcome","meaningCN":"决定结局的","example":"A related adjective describes what ends doubt.","exampleCN":"一个相关形容词形容能终止疑虑的事物。"},{"word":"share","structure":"scearu (Old English noun)","meaning":"a portion","meaningCN":"一份","example":"The qualifier for joint medical choices comes from an everyday English word.","exampleCN":"医疗共同决策前的限定语来自一个日常英语词。"},{"word":"shared","structure":"share + -ed","meaning":"held by more than one party","meaningCN":"由多方共同持有的","example":"The adjective marks a choice that no single party owns.","exampleCN":"这个形容词标出不由任何单方拥有的选择。"}],"latinEntries":[{"word":"decidere","structure":"decidere, decidi, decisum (verb, third conjugation)","meaning":"to cut off, settle","meaningCN":"切断；了结"},{"word":"decisio","structure":"decisio, decisionis (f., third declension)","meaning":"a settlement","meaningCN":"了结；决定"},{"word":"decisus","structure":"decisus, -a, -um (past participle)","meaning":"settled, cut off","meaningCN":"已了结的"}]}},{"word":"judgment","ipa_uk":"/ˈdʒʌdʒmənt/","ipa_us":"/ˈdʒʌdʒmənt/","definition_zh":"判断力；看法；判决；天谴","definition_en":"the ability to form sound opinions, an opinion so formed, or a formal ruling by a court","core_image":"天平上的砝码落下，指针抖了一下，停住","scene":"评审室里，三位评委听完演奏，各自在纸上写下分数。Her judgment of the young pianist was kinder than the others'.","sceneCN":"这里 judgment 指「经思考形成的评价」（第 1 个义项：形成稳妥看法的能力及其结果）；句意为她对那位年轻钢琴家的评价比其他人宽厚。场景要素：评分纸、铅笔、舞台监听音箱。","pos":[{"tag":"n.","zh":"判断力；看法；判决；天谴"}],"collocations":[{"phrase":"exercise judgment","zh":"运用判断力"},{"phrase":"a judgment call","zh":"凭判断作出的决定"},{"phrase":"pass judgment","zh":"作出评判"},{"phrase":"a court judgment","zh":"法院判决"},{"phrase":"sound judgment","zh":"稳妥的判断力"},{"phrase":"sit in judgment","zh":"坐在审判席上评判"}],"forms":[{"label":"复数","form":"judgments"},{"label":"英式拼写变体","form":"judgement"},{"label":"动词","form":"judge"},{"label":"形容词","form":"judicial"}],"derivatives":[{"word":"judge","pos":"n./v.","zh":"与 judgment 同出拉丁语中「法官」一词，指审理者或审理这一行为"},{"word":"judicial","pos":"adj.","zh":"由拉丁语「法庭的」一词进入英语，指与司法有关的"},{"word":"judicious","pos":"adj.","zh":"由 judge 加形容词后缀构成，指有见地的、审慎的"},{"word":"judgmentally","pos":"adv.","zh":"由 judgmental 加副词后缀构成，指以评判的姿态；属另一条形容词线"},{"word":"prejudice","pos":"n.","zh":"由表「在前」的前缀加「判断」的拉丁词构成，指预先形成的判断，后指偏见"}],"senses":[{"no":"01","title":"The ability to form sound opinions","titleCN":"形成稳妥看法的能力","definition":"the capacity to weigh evidence and reach a sensible conclusion","definitionCN":"权衡证据并得出合宜结论的能力","example":"Years of editing gave her a reliable judgment about which submissions would sell.","exampleCN":"多年编辑经验让她对哪些投稿卖得动有可靠的判断。","why":"The Latin word behind it joins law and speaking, so judging originally meant declaring what is right, and the mental capacity sense grew from that authority.","whyCN":"这个词背后的拉丁词把法律与言说连在一起，因此「判断」原指宣示何为正当，心智能力义由此权威感生长出来。"},{"no":"02","title":"An opinion reached","titleCN":"形成的看法","definition":"a conclusion one has come to about a person, work or situation","definitionCN":"对人、作品或情形得出的结论","example":"My judgment is that the proposal is sound but the timing is wrong.","exampleCN":"我的看法是方案本身可靠，但时机不对。","why":"Once the capacity produces something, the same noun names the product, which is why it appears with possessives.","whyCN":"能力一旦产出结果，同一个名词就指那个结果，因此它常带所有格。"},{"no":"03","title":"A ruling by a court","titleCN":"法院的判决","definition":"the formal decision of a court that settles the rights of the parties","definitionCN":"法院了结各方权利义务的正式决定","example":"The judgment ordered the company to restore the wetland.","exampleCN":"判决责令该公司恢复这片湿地。","why":"Law was the earliest home of the word, and the courtroom sense never faded even as the everyday sense broadened.","whyCN":"法律是这个词最早的家，即便日常义后来拓宽，法庭义也从未消退。"},{"no":"04","title":"A formal decision of a tribunal","titleCN":"裁判机构的形式决定","definition":"an award or finding issued by a panel, arbitrator or competition jury","definitionCN":"由评审团、仲裁人或竞赛评委作出的裁定或评定","example":"The arbitration judgment awarded costs to the smaller firm.","exampleCN":"仲裁裁决把费用判给了那家较小的公司。","why":"Any body that must settle a dispute borrows the courtroom noun, so the sense travels from courts to arbitrators and juries.","whyCN":"任何必须了结争议的机构都会借用这个法庭名词，于是这一义从法院延伸到仲裁人与评委。"},{"no":"05","title":"The exercise of judicial authority","titleCN":"司法权威的行使","definition":"the act of deciding as one lawfully entitled to decide, as in the phrase to sit in judgment","definitionCN":"以合法资格作出裁断的行为，如「坐在审判席上」这一说法","example":"The commission sits in judgment on complaints about broadcasters.","exampleCN":"该委员会对针对广播机构的投诉行使裁断权。","why":"The noun can name not just the ruling but the authority being exercised, which is why it survives in formal legal phrasing.","whyCN":"这个名词不只指裁决，也指被行使的权威，因此它在正式法律措辞中留存。"},{"no":"06","title":"Divine judgment","titleCN":"宗教意义上的天谴","definition":"in religious language, the verdict of a higher power on human conduct","definitionCN":"宗教语言中，更高力量对人类行为的裁决","example":"The sermon warned of judgment and of mercy in the same breath.","exampleCN":"布道在同一口气里既警告审判，也提到怜悯。","why":"Religious language took the courtroom image and moved the judge upward, so the word acquired a sense no human court can supply.","whyCN":"宗教语言借走法庭意象，把审判者移到天上，这个词于是获得人间法庭给不了的义项。"},{"no":"07","title":"Critical evaluation in a field","titleCN":"专业领域中的评价","definition":"the trained assessment of quality in a craft, as in editorial or artistic judgment","definitionCN":"对某一行业或艺术品质的专业评估","example":"The curator's judgment on the drawings was trusted by three museums.","exampleCN":"这位策展人对这批素描的品评得到三家博物馆信赖。","why":"Where a field has standards but no rules, practitioners rely on trained judgment, and the word names that reliance.","whyCN":"当一个领域有标准却无规则时，从业者依赖训练出的判断，这个词就指这种依赖。"},{"no":"08","title":"A judgment call","titleCN":"凭判断作出的决定","definition":"a decision that must rest on opinion because the rules and data leave the case open","definitionCN":"规则与数据都未定论、只能凭看法作出的决定","example":"Whether to publish before the holiday was a judgment call.","exampleCN":"要不要在假期前发表，是个只能凭判断的决定。","why":"The fixed phrase marks the point where calculation stops and opinion must act, which is the everyday survival of the old authority sense.","whyCN":"这个固定说法标出计算终止、看法必须上场的那一刻，也是古老权威义在日常中的遗留。"}],"etymology":{"intro":{"en":"Judgment comes through Old French from Latin judicium, built on judex 'judge', which joins jus 'law, right' to dicere 'to say, declare'. Dates are approximate.","cn":"judgment 经古法语来自拉丁语 judicium，其基础是 judex「法官」，由 jus「法律、权利」与 dicere「说、宣告」构成。年代均为约数。"},"items":[{"era":"LATIN JUS","en":"Jus meant 'law, right, justice'. Its deeper origin is not established; the link sometimes proposed to the verb for swearing an oath is a hypothesis.","cn":"jus 意为「法律、权利、正义」。其更早来源未得到证明；有人提出它与表「发誓」的动词有关，那只是假说。"},{"era":"LATIN DICERE","en":"Dicere meant 'to say, declare'. The same verb builds dictate, predict and verdict.","cn":"dicere 意为「说、宣告」。同一个动词还构成 dictate、predict 与 verdict。"},{"era":"LATIN JUDEX","en":"Jus plus dicere produced judex 'one who declares the law', hence the judge.","cn":"jus 加 dicere 构成 judex「宣告法律的人」，即法官。"},{"era":"LATIN JUDICIUM","en":"The noun judicium named the declaring of a right, then the ruling itself and the faculty of ruling well.","cn":"名词 judicium 既指宣告权利，也指裁决本身，以及善于裁断的能力。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French jugement carried the word into English in the fourteenth century, where legal use came first and general use followed.","cn":"古法语 jugement 在十四世纪把这个词带入英语，法律用法先行，一般用法随后。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use is recorded only approximately, and the pre-Latin origin of jus is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：最早的英语用例只有约略记载；jus 在拉丁语之前的来源亦无定论，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root words that are routinely mixed up with judgment; group two holds near neighbours for an opinion or a ruling.","cn":"第一组是同根词，常与本词张冠李戴；第二组是表示看法或裁定的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"judge","ipa":"/dʒʌdʒ/","tag":"the person or the act","definition":"The noun for the official and the verb for what that official does; judgment is the ruling or the capacity, not the person.","definitionCN":"作名词指法官，作动词指法官所做的事；judgment 指裁决或能力，不指人。"},{"word":"judicial","ipa":"/ˈdʒuːdɪʃl/","tag":"relating to courts","definition":"An adjective for the court system and its procedures, not for a person's opinions.","definitionCN":"形容法院系统及其程序，而非个人的看法。"},{"word":"judicious","ipa":"/ˈdʒuːdɪʃəs/","tag":"showing good judgment","definition":"Built to mean full of good judgment, so it is a compliment; it is not the adjective of judgmental.","definitionCN":"构成上意为「富于良好判断」，因此是褒义；它并不是 judgmental 的形容词原形。"},{"word":"prejudice","ipa":"/ˈpredʒudɪs/","tag":"judging beforehand","definition":"Built with the prefix meaning 'before' plus the same judging root, so it literally means a judgment formed in advance.","definitionCN":"由表「在前」的前缀加同一个「判断」词根构成，字面就是「事先形成的判断」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"verdict","ipa":"/ˈvɜːdɪkt/","tag":"the formal finding","definition":"The formal finding of a jury, literally a true saying; it is the courtroom sense of judgment made specific.","definitionCN":"指陪审团的正式认定，字面是「如实说出」，是法院义的具体化。"},{"word":"opinion","ipa":"/əˈpɪnjən/","tag":"what one thinks","definition":"A view held without the weight of authority; judgment suggests that the view was earned by weighing.","definitionCN":"指所持的看法，不带权威分量；judgment 暗示这看法是权衡得来的。"},{"word":"assessment","ipa":"/əˈsesmənt/","tag":"the measuring","definition":"The process or result of measuring something against criteria; judgment adds the personal act of deciding.","definitionCN":"指按标准衡量的过程或结果；judgment 多了「人作出裁断」这一层。"},{"word":"discernment","ipa":"/dɪˈsɜːnmənt/","tag":"fine perception","definition":"The ability to see subtle differences, especially in quality; judgment stresses the conclusion rather than the seeing.","definitionCN":"指看出细微差别的能力，尤其在品质上；judgment 强调结论而非看见。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin pieces, the real family and the real fixed phrases.","cn":"正常联想：两个拉丁成分、真实的词族与真实的固定说法。"},"normal":[{"en":"The Latin noun joins law and declaring, so judgment is law spoken out loud.","cn":"那个拉丁名词把「法律」与「宣告」连在一起，因此判断就是被说出来的法。"},{"en":"The family runs judge, judgment, judicial, judicious, judiciary, prejudice.","cn":"同族词包括 judge、judgment、judicial、judicious、judiciary、prejudice。"},{"en":"Fixed phrases mark the courtroom origin: pass judgment, sit in judgment, a court judgment.","cn":"固定说法标出法庭出身：作出评判、坐在审判席上、法院判决。"},{"en":"The everyday phrase a judgment call marks the point where rules run out.","cn":"日常说法「凭判断的决定」标出规则用尽的那一刻。"},{"en":"British writing often spells the noun judgement, while American writing prefers judgment.","cn":"英式写作常拼作 judgement，美式写作多用 judgment。"}],"abstract":[{"en":"Picture a balance whose pointer stops only after the weights are all placed.","cn":"想象一台天平，砝码全部放好之后指针才停住。"},{"en":"Picture a gavel that falls once and ends every argument in the room.","cn":"想象一把法槌落下一次，房间里所有争论就此结束。"},{"en":"Picture a critic who looks at a painting for a long time before saying a single word.","cn":"想象一位评论家看画很久，才说出一句话。"}]},"examples":[{"en":"The recruiter trusted her judgment more than the test scores.","cn":"招聘者更信她的判断，而不是那些测验分数。"},{"en":"The court issued a judgment that reopened the old case.","cn":"法院作出判决，让这桩旧案重新开庭。"},{"en":"Whether to speak now or wait was a judgment call.","cn":"现在开口还是再等等，是个只能凭判断的决定。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「judge 法官 + ment 行为」——法官作出的，就是判决与判断","word":"judgment"},"root":"拉丁 judicium「裁断」= judex「法官」+ 名词后缀；judex 又由 jus「法律、权利」与 dicere「说、宣告」构成；jus 更深来源不确定。英语 judgment。","sensesIntro":{"en":"Eight senses follow one act of declaring what is right: a capacity, an opinion, a court's ruling, an arbitrator's award, the authority behind it, a heavenly verdict, a craft's evaluation and a call made where rules stop.","cn":"八个义项沿同一个动作展开：宣告何为正当。它依次是能力、看法、法院判决、仲裁裁定、背后的权威、天上的裁决、行业内的品评，以及规则用尽处凭看法作出的决定。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance whose pointer trembles and then stops.","cn":"核心意象：天平上的指针抖了一下，然后停住。"},"chain":["WEIGH","FORM AN OPINION","DECLARE THE RIGHT","EXERCISE AUTHORITY","HEAVENLY VERDICT","SOUND SENSE"],"branches":[{"senses":"01 · 02","en":"CAPACITY AND PRODUCT: the ability to weigh and the opinion it produces are the same act seen inside and outside.","cn":"能力与产物：权衡的能力与它产出的看法，是同一动作的内外两面。"},{"senses":"03 · 05","en":"COURT AND AUTHORITY: a ruling and the lawful power to issue it are inseparable in legal use.","cn":"判决与权威：在法律用法里，裁决与作出裁决的合法权力不可分。"},{"senses":"04","en":"BORROWED COURTROOM: arbitrators and juries use the noun because they too must end a dispute.","cn":"借来的法庭：仲裁人与评委也用这个名词，因为他们同样必须了结争议。"},{"senses":"06","en":"UPWARD VERDICT: religion moves the judge above the room, adding a sense no human court supplies.","cn":"向上的裁决：宗教把审判者移到房间之上，增添了人间法庭给不了的义项。"},{"senses":"07 · 08","en":"TRAINED AND OPEN CASES: professional evaluation and the judgment call both act where written rules fall silent.","cn":"专业与开放情形：行业品评与凭判断的决定，都在明文规则沉默处发挥作用。"}]},"affixes":{"intro":{"en":"Judgment is two Latin pieces plus a Latin noun suffix, and the pieces also build the rest of the legal family.","cn":"judgment 由两个拉丁成分加一个拉丁名词后缀构成，这些成分还构成整个法律词族。"},"latinIntro":{"en":"Latin jus gives justice, jurist and jury; Latin dicere gives dictate, predict, verdict and the same ending in prejudice.","cn":"拉丁 jus 衍生 justice、jurist 与 jury；拉丁 dicere 衍生 dictate、predict、verdict，以及 prejudice 中的同一成分。"},"items":[{"word":"jus","structure":"jus, juris (n., third declension)","meaning":"law, right","meaningCN":"法律；权利","example":"The root supplies the legal half of the meaning.","exampleCN":"这个词根提供词义中「法」的那一半。"},{"word":"dicere","structure":"dicere (Latin verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告","example":"The root supplies the speaking that makes a ruling official.","exampleCN":"这个词根提供使裁决成为正式的那种言说。"},{"word":"judex","structure":"jus + dicere","meaning":"one who declares the law","meaningCN":"宣告法律的人","example":"The compound produced the name of the official.","exampleCN":"这个复合词造出了官员的名称。"},{"word":"judicium","structure":"judex + -ium (Latin noun suffix)","meaning":"a declaring, a ruling","meaningCN":"宣告；裁断","example":"The noun is the base that French and English borrowed.","exampleCN":"这个名词是法语与英语借用的基础。"},{"word":"-ment","structure":"-mentum (Latin noun suffix)","meaning":"result of an action","meaningCN":"行为的结果","example":"The suffix marks the ruling as something produced and recorded.","exampleCN":"这个后缀把裁决标为被产出、被记录之物。"},{"word":"judgment","structure":"judicium through French","meaning":"a ruling or a formed opinion","meaningCN":"裁决；形成的看法","example":"English keeps one noun for the act, the result and the capacity.","exampleCN":"英语用同一个名词指行为、结果与能力。"},{"word":"judge","structure":"judex through French","meaning":"the official who rules","meaningCN":"审理者","example":"The person noun survives beside the abstract one.","exampleCN":"指人的名词与抽象名词并存。"},{"word":"judicial","structure":"judicium + -alis","meaning":"relating to courts","meaningCN":"与司法有关的","example":"The adjective stays inside the legal sense.","exampleCN":"这个形容词留在法律义之内。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix turns a noun of office into an adjective of system.","exampleCN":"这个后缀把职务名词变成制度形容词。"}],"latinEntries":[{"word":"jus","structure":"jus, juris (n., third declension)","meaning":"law, right","meaningCN":"法律；权利"},{"word":"dicere","structure":"dicere, dixi, dictum (verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告"},{"word":"judex","structure":"judex, judicis (m., third declension)","meaning":"a judge","meaningCN":"法官"},{"word":"judicium","structure":"judicium, judicii (n., second declension)","meaning":"a ruling, a judgment","meaningCN":"裁决；判断"}]}},{"word":"judgmental","ipa_uk":"/ˌdʒʌdʒˈmentl/","ipa_us":"/ˌdʒʌdʒˈmentl/","definition_zh":"爱评判的；动辄批评的；带有评价色彩的","definition_en":"inclined to criticize other people or to express moral disapproval, or marked by explicit evaluation","core_image":"一个人举着牌子给路过的每个人打分，牌上写满叉号","scene":"讨论课上，一名学生听完同伴的发言，立刻给人贴上懒惰的标签，却不肯听完理由。The tutor warns that such a judgmental reply shuts down discussion.","sceneCN":"这里 judgmental 指「动辄对人下评判」（第 1 个义项：倾向苛刻地评判他人）；句意为导师警告这种评判式的回应会堵死讨论。场景要素：围坐的课桌、举起的评分牌、被打断的发言者。","pos":[{"tag":"adj.","zh":"爱评判的；动辄批评的；带有评价色彩的"}],"collocations":[{"phrase":"a judgmental tone","zh":"评判式的语气"},{"phrase":"judgmental attitudes","zh":"动辄评判的态度"},{"phrase":"a judgmental remark","zh":"随口评判的一句话"},{"phrase":"judgmental sampling","zh":"判断抽样"},{"phrase":"judgmental of others","zh":"对他人爱下评断"},{"phrase":"less judgmental","zh":"少一些评判"}],"forms":[{"label":"比较级","form":"more judgmental"},{"label":"最高级","form":"most judgmental"},{"label":"副词","form":"judgmentally"},{"label":"名词","form":"judgment"},{"label":"英式拼写变体","form":"judgemental"}],"derivatives":[{"word":"judgment","pos":"n.","zh":"由 judgmental 去掉形容词后缀构成的名词，指判断、看法或裁决"},{"word":"judgmentally","pos":"adv.","zh":"由 judgmental 加副词后缀构成，指以评判的姿态"},{"word":"judge","pos":"n./v.","zh":"同词族的指人名词与动词，指审理者或作出评断"},{"word":"judicious","pos":"adj.","zh":"另一条同根形容词线，指有见地、审慎的，与本词褒贬相反"}],"senses":[{"no":"01","title":"Inclined to criticize others harshly","titleCN":"倾向苛刻地评判他人","definition":"quick to form and voice negative opinions about other people","definitionCN":"很快形成并说出对他人的负面看法","example":"He was judgmental about anyone who left the lab before dark.","exampleCN":"谁在天黑前离开实验室，他都要评断一番。","why":"The adjective simply adds a Latin suffix meaning 'relating to' to judgment, so it describes someone whose judging habit has become a manner.","whyCN":"这个形容词只是在 judgment 后加一个意为「与……有关」的拉丁后缀，因此描述一个人把评判变成了习惯作风。"},{"no":"02","title":"Expressing moral disapproval","titleCN":"表达道德上的不认同","definition":"voicing disapproval in moral terms, as if a conduct were beneath the speaker","definitionCN":"以道德措辞表达不认同，仿佛某种行为低人一等","example":"The article's judgmental language about divorce dated from another era.","exampleCN":"那篇文章对离婚的评判式措辞像是另一个年代的产物。","why":"When judgment moves from facts to morals, criticism acquires a tone of superiority, and the word follows that tone.","whyCN":"当判断从事实移到道德，批评就带上优越感，这个词也跟着那种口吻走。"},{"no":"03","title":"Evaluative rather than descriptive","titleCN":"评价性而非描述性","definition":"describing language that rates something instead of merely reporting it","definitionCN":"形容不是陈述事实、而是给某物打分的语言","example":"A judgmental clause such as a foolish plan reveals the writer's stance.","exampleCN":"像「愚蠢的计划」这样的评价性小句暴露了作者的立场。","why":"Grammar and writing guides use the word for any statement that smuggles a rating into a description.","whyCN":"语法与写作指南用这个词指任何把评分偷偷塞进描述的说法。"},{"no":"04","title":"Censorious in look or tone","titleCN":"神情或语气上带责备","definition":"describing a glance, sigh or tone that passes sentence without words","definitionCN":"形容一个眼神、一声叹息或一种语气，不用文字就定了罪","example":"A judgmental silence followed his excuse.","exampleCN":"他的借口之后是一阵带评判意味的沉默。","why":"The same stance can be carried without vocabulary, so the adjective attaches to faces and pauses too.","whyCN":"同一种姿态可以不靠词汇传达，因此这个形容词也修饰表情与停顿。"},{"no":"05","title":"An evaluative stance that blocks listening","titleCN":"妨碍倾听的评判姿态","definition":"in psychology and education, an attitude of rating a person that prevents open attention to them","definitionCN":"在心理学与教育中，指一种一边听人一边打分的姿态，妨碍开放地关注对方","example":"Counsellors are trained to notice a judgmental reflex and set it aside.","exampleCN":"咨询师受训留意评判的反射，并把它放到一边。","why":"Here the criticism is not about being wrong but about being closed, since a person who is busy rating cannot be listening.","whyCN":"这里的批评不在于判断错误，而在于封闭：忙着打分的人无法同时倾听。"},{"no":"06","title":"Judgmental sampling","titleCN":"判断抽样","definition":"in statistics, selecting a sample by expert judgment rather than at random","definitionCN":"统计学中按专家判断而非随机抽取样本","example":"A judgmental sample of three busy clinics cannot support a national claim.","exampleCN":"只挑三家忙碌诊所的判断样本，撑不起全国性的结论。","why":"The technical sense keeps the neutral meaning of 'resting on judgment' and drops the moral disapproval entirely.","whyCN":"这一技术义保留「依据判断」的中性含义，完全去掉了道德上的不认同。"},{"no":"07","title":"Resting on explicit judgment","titleCN":"依据明确判断的","definition":"neutral and technical, describing a method or estimate that depends on a person's evaluation","definitionCN":"中性、技术性的用法，形容依赖人的评估的方法或估计","example":"The cost figure was judgmental rather than measured.","exampleCN":"这个成本数字是凭判断估计的，而不是量出来的。","why":"English still keeps a neutral sense, which is why the word cannot be treated as an insult in every context.","whyCN":"英语仍保留一个中性义，因此不能把这个词在所有语境里都当成贬语。"},{"no":"08","title":"Turning criticism inward","titleCN":"把评判转向自己","definition":"applied to oneself, describing harsh self-criticism that mirrors the treatment given to others","definitionCN":"用于自身，形容苛待自己的自我批评，与对待他人的方式相同","example":"Her journal was judgmental about every small mistake she made.","exampleCN":"她的日记对每一个小错都严厉评判。","why":"The same rating gaze can be aimed inward, and the word follows it there without changing its edge.","whyCN":"同一种打分目光可以转向内部，这个词跟着用过去，锋利程度不变。"}],"etymology":{"intro":{"en":"Judgmental is judgment plus the Latin adjective suffix -alis; judgment itself goes back through French to Latin judicium. Dates are approximate.","cn":"judgmental 是 judgment 加拉丁形容词后缀；而 judgment 本身经法语可上溯到拉丁语 judicium。年代均为约数。"},"items":[{"era":"LATIN JUDICIUM","en":"The base noun meant 'a declaring of the law', then 'a ruling' and 'the faculty of ruling'.","cn":"作为基础的拉丁名词原指「宣告法律」，后指「裁决」与「裁断能力」。"},{"era":"OLD FRENCH","en":"Old French jugement carried the noun into English in the fourteenth century, first in legal use.","cn":"古法语 jugement 在十四世纪把这个名词带入英语，先用于法律场合。"},{"era":"ENGLISH NOUN","en":"English kept the noun for both the ruling and the opinion throughout its history.","cn":"在整个历史中，英语用这个名词既指裁决也指看法。"},{"era":"LATIN SUFFIX -ALIS","en":"The suffix meaning 'relating to' built hundreds of English adjectives of relation.","cn":"意为「与……有关」的这个后缀，构成了成百上千个表关系的英语形容词。"},{"era":"DERIVED ADJECTIVE","en":"The adjective arose in the nineteenth century and narrowed toward a censorious manner, while keeping a neutral technical sense.","cn":"这个形容词在十九世纪出现，词义向爱责备的做派收窄，同时保留一个中性的技术义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use of the adjective): the earliest citation is not settled, and the pre-Latin origin of the root for law is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（这个形容词的最早书证）：最早用例尚无定论；那个表「法律」的词根在拉丁语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root adjectives and nouns whose value is often reversed; group two holds near neighbours that share the censorious edge.","cn":"第一组是同根形容词与名词，褒贬方向常被弄反；第二组是同样带责备意味的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"judicious","ipa":"/ˈdʒuːdɪʃəs/","tag":"praise, not blame","definition":"Means full of good judgment and is a compliment, whereas judgmental describes an excess of judging.","definitionCN":"意为「富于良好判断」，是褒义；而 judgmental 指评判过度。"},{"word":"judicial","ipa":"/ˈdʒuːdɪʃl/","tag":"relating to courts","definition":"Describes the court system, its procedures and its review; it carries none of the personal criticism.","definitionCN":"形容法院系统、程序与审查，不含对个人的批评。"},{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"the noun, not the manner","definition":"The noun names a ruling or a capacity, so it can be neutral; the adjective describes a manner of using it.","definitionCN":"名词指裁决或能力，本身可以中性；形容词描述使用它的做派。"},{"word":"judgmentalism","ipa":"/ˌdʒʌdʒˈmentəlɪzəm/","tag":"the habit itself","definition":"A rare noun for the tendency to judge others, which names the habit that the adjective describes.","definitionCN":"一个罕用名词，指爱评判他人的倾向，正是这个形容词所描述的习性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"critical","ipa":"/ˈkrɪtɪkl/","tag":"finding faults","definition":"Stresses pointing out faults, often with evidence and without moral superiority.","definitionCN":"强调指出缺陷，往往有据可依，不带道德优越感。"},{"word":"censorious","ipa":"/senˈsɔːriəs/","tag":"eager to condemn","definition":"A formal adjective for a strong habit of condemning, usually in moral matters.","definitionCN":"正式用语，形容动辄谴责，多半在道德事务上。"},{"word":"moralistic","ipa":"/ˌmɒrəˈlɪstɪk/","tag":"preaching morality","definition":"Describes a habit of turning every issue into a moral lesson, with an emphasis on preaching.","definitionCN":"形容把任何事都变成道德教训，落点在说教。"},{"word":"opinionated","ipa":"/əˈpɪnjəneɪtɪd/","tag":"stubborn in views","definition":"Describes someone who holds views very firmly; judgmental adds the element of looking down on others.","definitionCN":"形容人执持己见；judgmental 多了「看低他人」这一层。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun base, the real suffix, the real phrases and the two spellings.","cn":"正常联想：真实的名词基底、真实的后缀、真实的短语与两种拼写。"},"normal":[{"en":"The adjective is judgment plus a suffix meaning relating to, so it describes a judging manner.","cn":"这个形容词就是 judgment 加一个表「与……有关」的后缀，因此描述一种评判做派。"},{"en":"The family runs judge, judgment, judgmental, judgmentally, judicious; note that judicious is praise.","cn":"同族词包括 judge、judgment、judgmental、judgmentally、judicious；注意 judicious 是褒义。"},{"en":"Fixed phrases mark the uses: a judgmental tone, judgmental attitudes, judgmental sampling.","cn":"固定搭配标出用法：评判式语气、动辄评判的态度、判断抽样。"},{"en":"British writing often spells it judgemental, with the extra e of judgement.","cn":"英式写作常拼作 judgemental，多一个 e。"},{"en":"The statistics sense is neutral, so the word is not always an insult.","cn":"统计学义是中性的，因此这个词并非总是贬语。"}],"abstract":[{"en":"Picture a scorecard held up at every passer-by.","cn":"想象对每个路过的人都举一块打分牌。"},{"en":"Picture a door that only opens for people who pass inspection.","cn":"想象一扇只给通过检验的人开的门。"},{"en":"Picture a mirror that criticizes the face it shows.","cn":"想象一面会批评自己照出的那张脸的镜子。"}]},"examples":[{"en":"The review was judgmental about the author rather than about the book.","cn":"这篇书评评断的是作者，而不是这本书。"},{"en":"His judgmental remark ended the conversation before the facts were in.","cn":"他那句评判式的话在事实摆出来之前就结束了对话。"},{"en":"The survey used judgmental sampling, so the margin of error is unknown.","cn":"这项调查用了判断抽样，因此误差范围无从得知。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「judgment 判断 + al 的」——动不动就下判断的，就是爱评判的","word":"judgmental"},"root":"英语 judgment（拉丁 judicium「裁断」）+ 拉丁形容词后缀；judicium 的更深词源见 judgment 条。","sensesIntro":{"en":"Eight senses follow one habit: a rating gaze turned on people. It appears as harsh criticism, moral disapproval, evaluative wording, a censorious silence, a stance that blocks listening, a statistical sampling method, a neutral technical estimate, and the same gaze turned on oneself.","cn":"八个义项沿同一个习惯展开：把打分的目光投向人。它依次表现为苛刻批评、道德不认同、评价性措辞、带责备的沉默、妨碍倾听的姿态、一种统计抽样法、中性的技术估计，以及转向自己的同一道目光。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person holding up a scorecard for everyone who walks past.","cn":"核心意象：一个人对每个路过的人都举起一块打分牌。"},"chain":["JUDGE","CRITICIZE","MORALIZE","RATE IN WORDS","SAMPLE BY EXPERTS","TURN INWARD"],"branches":[{"senses":"01 · 04","en":"HARSH AND SILENT: spoken criticism and a disapproving silence carry the same verdict.","cn":"出声与沉默：说出口的批评与不认同的沉默，带的是同一个判断。"},{"senses":"02 · 05","en":"MORALS THAT CLOSE THE DOOR: moral disapproval and the stance that blocks listening both stop contact.","cn":"关门的道德：道德上的不认同与妨碍倾听的姿态，都中断了接触。"},{"senses":"03 · 07","en":"WORDS AND METHODS: evaluative wording and a judgment-based estimate are the neutral face of the same habit.","cn":"措辞与方法：评价性措辞与依据判断的估计，是同一习惯的中性一面。"},{"senses":"06","en":"EXPERT SELECTION: statistics borrows the neutral sense to name a sample chosen by judgment.","cn":"专家挑选：统计学借用中性义，指按判断选出的样本。"},{"senses":"08","en":"INWARD: the gaze aimed at oneself keeps every edge it had when aimed outward.","cn":"向内：转向自己的目光，锋刃与向外时完全相同。"}]},"affixes":{"intro":{"en":"The word is an English noun base plus a Latin adjective suffix, so it reads as two clean pieces.","cn":"这个词是一个英语名词基底加一个拉丁形容词后缀，因此可以干净地读成两部分。"},"latinIntro":{"en":"The base brings judge, judgment and judicial; the suffix appears in legal, natural, personal and universal.","cn":"基底带来 judge、judgment 与 judicial；后缀还出现在 legal、natural、personal 与 universal 中。"},"items":[{"word":"judgment","structure":"judicium (Latin) through French","meaning":"a ruling or formed opinion","meaningCN":"裁决或形成的看法","example":"The base supplies both the act of judging and its result.","exampleCN":"基底同时提供评判行为与结果。"},{"word":"-al","structure":"-alis (Latin adjective suffix, 'relating to')","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix turns the noun into an adjective of manner.","exampleCN":"这个后缀把名词变成描述做派的形容词。"},{"word":"judgmental","structure":"judgment + -al","meaning":"given to judging others","meaningCN":"爱评判他人的","example":"The adjective specializes the base toward a censorious habit.","exampleCN":"这个形容词把基底专门化，指向爱责备的习性。"},{"word":"-ly","structure":"-lice (English adverb suffix)","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The adverb marks how a remark or silence is delivered.","exampleCN":"这个副词标出话语或沉默是以何种方式给出的。"},{"word":"judgmentally","structure":"judgmental + -ly","meaning":"in a judging manner","meaningCN":"以评判的姿态","example":"The adverb is common in writing about counselling and classrooms.","exampleCN":"这个副词常用于咨询与课堂类写作。"},{"word":"judge","structure":"judex (Latin) through French","meaning":"one who rules","meaningCN":"审理者","example":"The person noun is the oldest member of the family.","exampleCN":"指人的名词是这个词族中最年长的成员。"},{"word":"judicious","structure":"judicium + -osus","meaning":"full of good judgment","meaningCN":"富于良好判断的","example":"A different suffix produces the opposite compliment.","exampleCN":"换一个后缀就造出了方向相反的褒义词。"},{"word":"judicial","structure":"judicium + -alis","meaning":"relating to courts","meaningCN":"与司法有关的","example":"The same suffix as this word, but attached to legal institutions.","exampleCN":"与本词同一后缀，只是接在法律机构上。"},{"word":"judgmentalism","structure":"judgmental + -ism","meaning":"the habit of judging","meaningCN":"爱评判的习气","example":"The noun of the habit is rare but regular in form.","exampleCN":"指这种习气的名词虽罕用，构形却规矩。"}],"latinEntries":[{"word":"judicium","structure":"judicium, judicii (n., second declension)","meaning":"a ruling, a judgment","meaningCN":"裁决；判断"},{"word":"judex","structure":"judex, judicis (m., third declension)","meaning":"a judge","meaningCN":"法官"},{"word":"judicare","structure":"judicare, judicavi, judicatum (verb, first conjugation)","meaning":"to judge, to rule","meaningCN":"评判；裁断"}]}},{"word":"expectation","ipa_uk":"/ˌekspekˈteɪʃn/","ipa_us":"/ˌekspekˈteɪʃn/","definition_zh":"预期；期望；期待的事物；（统计）期望值","definition_en":"a belief that something will happen, a standard one is required to meet, or the average value of a random quantity","core_image":"站台上的人不断望向轨道尽头，心里已经看见列车进站","scene":"菜市场里，摊主把新到的水果摆到最前面，因为他估计周末顾客会更多。He raised his prices in expectation of a busy weekend.","sceneCN":"这里 expectation 指「对将要发生之事的预判」（第 1 个义项：相信某事会发生）；句意为他在预期周末繁忙之下提高了价格。场景要素：水果摊、价签、周末人流。","pos":[{"tag":"n.","zh":"预期；期望；期待的事物；（统计）期望值"}],"collocations":[{"phrase":"meet expectations","zh":"达到预期"},{"phrase":"fall short of expectations","zh":"未达预期"},{"phrase":"expectation of privacy","zh":"对隐私的合理期待"},{"phrase":"statistical expectation","zh":"统计期望值"},{"phrase":"expectations of growth","zh":"对增长的预期"},{"phrase":"against all expectations","zh":"出乎所有预料"}],"forms":[{"label":"复数","form":"expectations"},{"label":"动词","form":"expect"},{"label":"形容词","form":"expectant"},{"label":"否定形容词","form":"unexpected"}],"derivatives":[{"word":"expect","pos":"v.","zh":"产生 expectation 的动词，直接来自拉丁语「向外张望」，指料想某事会发生"},{"word":"expectant","pos":"adj.","zh":"由 expect 加形容词后缀构成，指期待着的，也指即将为人父母的"},{"word":"expected","pos":"adj.","zh":"由 expect 加过去分词后缀构成，指按计划应当发生的"},{"word":"unexpected","pos":"adj.","zh":"由否定前缀加 expected 构成，指出乎意料的"},{"word":"expectancy","pos":"n.","zh":"由 expectant 加抽象名词后缀构成，指期待状态，多用于心理与统计"}],"senses":[{"no":"01","title":"A belief that something will happen","titleCN":"相信某事会发生","definition":"a settled belief that an event will occur, based on evidence or habit","definitionCN":"基于证据或习惯，认为某事件将会发生的稳定信念","example":"The forecast set expectations of rain by evening.","exampleCN":"预报让人们对傍晚下雨有了预期。","why":"The Latin verb underneath means to look out for, so the noun is literally a watching-for, and the belief is that watch turned into a forecast.","whyCN":"下面的拉丁动词意为「向外张望」，因此这个名词字面就是「向外看」，那种信念就是张望变成了预报。"},{"no":"02","title":"A hope that good will come","titleCN":"对好结果的盼望","definition":"an anticipatory feeling that something desired is likely to arrive","definitionCN":"一种认为想要之事很可能到来的期待心情","example":"The children waited with expectation for the first snow.","exampleCN":"孩子们怀着期待等第一场雪。","why":"The same forecast can be coloured by desire, and English lets one noun carry both the neutral prediction and the hopeful version.","whyCN":"同一个预判可以被愿望染色，英语让一个名词同时承载中性的预测与带盼望的版本。"},{"no":"03","title":"A standard one is required to meet","titleCN":"被要求达到的标准","definition":"a level of conduct or performance that others believe one should reach","definitionCN":"他人认为某人应当达到的行为或表现水平","example":"The new coach raised expectations about training attendance.","exampleCN":"新教练提高了对训练出勤的要求。","why":"Once a prediction is about a person's duty, it turns into a standard, and failing it becomes a social event rather than a wrong forecast.","whyCN":"当预判落在人的义务上，它就变成标准，达不到便成为社会事件，而不只是预报失误。"},{"no":"04","title":"The prospect of receiving something","titleCN":"对获得某物的指望","definition":"the chance or prospect of coming into money, property or a role","definitionCN":"获得钱财、产业或职位的可能或指望","example":"He built an extension on the expectation of an inheritance.","exampleCN":"他凭着对一笔遗产的指望加盖了房屋。","why":"Law and family language use the noun for what a person is due to receive, which is the old 'looking forward to' sense made concrete.","whyCN":"法律与家庭用语用这个名词指某人应当得到之物，这是古老「盼望」义的具体化。"},{"no":"05","title":"Statistical expected value","titleCN":"统计上的期望值","definition":"the long-run average of a random quantity, weighted by the probability of each outcome","definitionCN":"随机量在长期中的平均值，按各结果的概率加权","example":"The expectation of the die roll is three and a half.","exampleCN":"掷骰子的期望值是三点五。","why":"Mathematics took the everyday forecast and made it exact: the expected value is the forecast with the arithmetic filled in.","whyCN":"数学把日常的预判精确化：期望值就是填入了算术的预判。"},{"no":"06","title":"Mathematical expectation","titleCN":"概率论中的数学期望","definition":"the operator that assigns to each random variable its probability-weighted mean","definitionCN":"把每个随机变量映到其概率加权均值的运算","example":"The course defines expectation before it defines variance.","exampleCN":"这门课先定义数学期望，再定义方差。","why":"Once the idea becomes an operator, the noun names a tool rather than a state of mind, which is why textbooks treat it as a symbol.","whyCN":"当这个想法变成运算，这个名词就指一件工具而非一种心态，因此教科书把它当作符号处理。"},{"no":"07","title":"Economic expectations","titleCN":"经济预期","definition":"the forecasts that households and firms hold about prices, demand or growth, which then shape their behaviour","definitionCN":"家庭与企业对价格、需求或增长所持的预判，这些预判随后塑造其行为","example":"Inflation expectations can become self-fulfilling.","exampleCN":"通胀预期可能自我实现。","why":"In economics a forecast is also a cause, because people act on what they expect, so the noun names a force and not merely a belief.","whyCN":"在经济学中，预判本身也是原因，因为人按预期行动，因此这个名词指一种力量而非仅是信念。"},{"no":"08","title":"The state of awaiting","titleCN":"等待之中的状态","definition":"the condition of being kept waiting for something that has not yet arrived","definitionCN":"为尚未到来之事而等待的状态","example":"The whole hall stood in expectation as the curtain rose.","exampleCN":"幕布升起时，全场都处于期待之中。","why":"The oldest layer is simply the stretch of time spent looking out, and that state survives in formal and literary phrasing.","whyCN":"最古老的一层就是向外张望的那段时间，这一状态保存在正式与文学措辞里。"}],"etymology":{"intro":{"en":"Expectation comes from Latin exspectatio, built on exspectare 'to look out for', which joins a prefix meaning 'out' to a frequentative verb for looking. Dates are approximate.","cn":"expectation 来自拉丁语 exspectatio，其基础是 exspectare「向外张望」，由表「向外」的前缀与一个表示反复看的动词构成。年代均为约数。"},"items":[{"era":"LATIN EX-","en":"The prefix meant 'out, outward', and it aims the looking beyond the present place.","cn":"这个前缀意为「向外、出去」，它把目光投向当下所在之外。"},{"era":"LATIN SPECTARE","en":"Spectare meant 'to look at, watch', a frequentative form built on the verb for seeing; the deeper origin of that verb is not established.","cn":"spectare 意为「看、观看」，是在表「看见」的动词上构成的反复形式；那个动词的更早来源未得到证明。"},{"era":"LATIN EXSPECTARE","en":"Ex- plus spectare produced exspectare 'to look out for, await', the source of the English verb.","cn":"意为「向外」的拉丁前缀加 spectare 构成 exspectare「向外张望、等待」，即英语动词的来源。"},{"era":"LATIN EXSPECTATIO","en":"The noun named the act of watching for something and the belief that it will come.","cn":"这个名词既指向外张望的行为，也指相信它会来的信念。"},{"era":"FRENCH AND ENGLISH","en":"The noun entered English through French in the fifteenth century, and the mathematical sense was added in the eighteenth.","cn":"这个名词在十五世纪经法语进入英语，数学义则在十八世纪加入。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use is recorded only approximately, and the pre-Latin origin of the verb for seeing is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：最早的英语用例只有约略记载；那个表「看见」的动词在拉丁语之前的来源亦无定论，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root words that are constantly interchanged with the noun; group two holds near neighbours for a forecast or a hope.","cn":"第一组是同根词，常与本名词互换出错；第二组是表示预判或盼望的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"expect","ipa":"/ɪkˈspekt/","tag":"the verb","definition":"The verb that produces the noun; it takes a clause or an object, while the noun takes a preposition or a verb of meeting.","definitionCN":"产生这个名词的动词；它接从句或宾语，而这个名词接介词或「达到」类动词。"},{"word":"expectant","ipa":"/ɪkˈspektənt/","tag":"full of waiting","definition":"An adjective for a person or mood that is waiting; it often describes parents awaiting a baby, a sense the noun lacks.","definitionCN":"形容正在等待的人或气氛，常指即将为人父母，这层意思名词没有。"},{"word":"expectancy","ipa":"/ɪkˈspektənsi/","tag":"the state as a quantity","definition":"A near synonym for the waiting state, but psychology and statistics use it as a measurable variable.","definitionCN":"与「等待状态」近义，但心理学与统计学把它当作可测量的变量。"},{"word":"unexpected","ipa":"/ˌʌnɪkˈspektɪd/","tag":"not foreseen","definition":"Built with a negative prefix, it describes what no forecast covered; the noun has no such negative built in.","definitionCN":"带否定前缀，形容预判未覆盖之事；名词本身不含这种否定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anticipation","ipa":"/ˌæntɪsɪˈpeɪʃn/","tag":"looking ahead with pleasure","definition":"Often carries pleasurable forward-looking, and also the act of acting before an event.","definitionCN":"常带愉悦的向前看，也指在事件之前先行行动。"},{"word":"hope","ipa":"/həʊp/","tag":"wanting, not forecasting","definition":"A desire for a good outcome without the evidential weight that expectation carries.","definitionCN":"指盼望好结果，但没有 expectation 那种证据分量。"},{"word":"prospect","ipa":"/ˈprɒspekt/","tag":"the outlook","definition":"The outlook for something, often used for chances of success or of gain.","definitionCN":"指某事的前景，常用于成功或收益的可能性。"},{"word":"prediction","ipa":"/prɪˈdɪkʃn/","tag":"a stated forecast","definition":"An explicit statement about what will happen; expectation can stay unspoken and vague.","definitionCN":"指明确说出将会发生什么；expectation 可以停留在未说出口的模糊状态。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real looking root, the real family and the real phrases.","cn":"正常联想：真实的前缀、表「看」的词根、真实的词族与真实的短语。"},"normal":[{"en":"The Latin verb means to look out for, so an expectation is a watch kept in advance.","cn":"那个拉丁动词意为「向外张望」，因此预期就是提前守住的目光。"},{"en":"The same looking root gives spectator, spectacle, inspect and respect.","cn":"同一个表「看」的词根还构成 spectator、spectacle、inspect 与 respect。"},{"en":"The family runs expect, expected, unexpected, expectant, expectancy.","cn":"同族词包括 expect、expected、unexpected、expectant、expectancy。"},{"en":"Fixed phrases mark the social sense: meet expectations, fall short of expectations, expectations of growth.","cn":"固定搭配标出社会义：达到预期、未达预期、对增长的预期。"},{"en":"Statistics turns the noun into a number: the expectation of a die roll is three and a half.","cn":"统计学把这个名词变成数字：掷骰子的期望值是三点五。"}],"abstract":[{"en":"Picture a person on a platform looking down empty tracks.","cn":"想象站台上的人望向空荡的轨道尽头。"},{"en":"Picture a scale that predicts the average of a hundred throws before any is made.","cn":"想象一台秤在还没掷之前就预言一百次投掷的平均。"},{"en":"Picture a price tag raised because the seller believes the crowd is coming.","cn":"想象一个价签被抬高，因为摊主相信人群会来。"}]},"examples":[{"en":"The results exceeded every expectation the lab had set.","cn":"结果超出了实验室设定的所有预期。"},{"en":"Patients have a reasonable expectation that their notes stay private.","cn":"病人有理由期待自己的病历保持私密。"},{"en":"Rising expectations of inflation pushed the central bank to act.","cn":"不断上升的通胀预期促使央行采取行动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「向外看」——提前把目光投出去，等它发生，就是预期","word":"expectation"},"root":"拉丁 exspectatio「向外张望」由意为「向外」的前缀加 spectare（反复看，出自表「看见」的词根）；该词根更深来源不确定。英语 expectation。","sensesIntro":{"en":"Eight senses follow one watch: the gaze sent ahead to meet an event. It is read as a belief, as a hope, as a standard, as a due inheritance, as an average, as an operator, as an economic force and as the mere state of waiting.","cn":"八个义项沿同一道目光展开：把视线提前投向某件事。它依次被读作信念、盼望、标准、应得的继承、平均值、运算、经济力量，以及单纯的等待状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: someone on a platform scanning the empty track.","cn":"核心意象：站台上的人扫视空荡的轨道。"},"chain":["AWAIT","FORESEE","HOPE","REQUIRE","CALCULATE THE MEAN","OUTLOOK"],"branches":[{"senses":"01 · 08","en":"FORECAST AND WAITING: the belief and the bare stretch of waiting are the same watch at two temperatures.","cn":"预判与等待：信念与单纯的等待，是同一道目光的两种温度。"},{"senses":"02","en":"WISH COLOURS THE WATCH: the same forecast tinged by desire becomes hope.","cn":"愿望染色：同一个预判被愿望染过，就成了盼望。"},{"senses":"03 · 04","en":"DUTY AND DUE: a standard others hold you to, and property you are due to receive.","cn":"义务与应得：他人要求你达到的标准，以及你应当得到的财产。"},{"senses":"05 · 06","en":"THE NUMBER AND THE OPERATOR: the average and the function that assigns it are the forecast made exact.","cn":"数字与运算：平均值与给出平均值的函数，是精确化的预判。"},{"senses":"07","en":"FORECAST AS FORCE: in economics the expectation itself moves prices, so it acts rather than merely predicts.","cn":"预判即力量：在经济学中，预期本身推动价格，因此它在行动而不只是预测。"}]},"affixes":{"intro":{"en":"Expectation is a Latin prefix, a Latin looking root and two Latin suffixes, all of which recur across English.","cn":"expectation 由一个拉丁前缀、一个表「看」的拉丁词根和两个拉丁后缀构成，这些成分在英语中反复出现。"},"latinIntro":{"en":"The looking root gives spectator, spectacle, inspect and respect; the prefix meaning 'out' gives export, exclude and extend.","cn":"表「看」的词根衍生 spectator、spectacle、inspect 与 respect；表「向外」的前缀衍生 export、exclude 与 extend。"},"items":[{"word":"ex-","structure":"ex- (Latin prefix, 'out, out of')","meaning":"out; outward","meaningCN":"向外；出去","example":"The prefix sends the looking beyond the present place.","exampleCN":"这个前缀把目光送出当下所在。"},{"word":"spectare","structure":"spectare (Latin frequentative verb)","meaning":"to look at repeatedly","meaningCN":"反复地看","example":"The root carries the watching, repeated until something appears.","exampleCN":"这个词根带着「看」，反复地看直到某物出现。"},{"word":"exspectare","structure":"ex- + spectare","meaning":"to look out for","meaningCN":"向外张望；等待","example":"The verb is the everyday act behind the noun.","exampleCN":"这个动词是这个名词背后的日常动作。"},{"word":"expect","structure":"exspectare through French","meaning":"to look for, await","meaningCN":"期待；料想","example":"English keeps the verb beside the longer noun.","exampleCN":"英语在较长的名词旁保留了动词。"},{"word":"-ation","structure":"-atio (Latin noun suffix, 'action or result')","meaning":"the act or result","meaningCN":"行为或结果","example":"The suffix builds the noun of the act of watching.","exampleCN":"这个后缀造出「看」这一行为的名词。"},{"word":"expectation","structure":"expect + -ation","meaning":"a looking-for","meaningCN":"向外张望；预期","example":"The noun covers both the forecast and the standard.","exampleCN":"这个名词同时覆盖预判与标准。"},{"word":"-ant","structure":"-ans (Latin adjective suffix, 'doing')","meaning":"doing, being in a state","meaningCN":"正在……的","example":"The suffix produces the adjective for someone who waits.","exampleCN":"这个后缀造出形容正在等待者的形容词。"},{"word":"expectant","structure":"expect + -ant","meaning":"waiting","meaningCN":"期待着的","example":"The adjective is common in medical and formal writing.","exampleCN":"这个形容词常用于医疗与正式写作。"},{"word":"-ancy","structure":"-antia (Latin noun suffix, 'state')","meaning":"state of being","meaningCN":"……的状态","example":"The suffix turns the waiting adjective into a measurable state.","exampleCN":"这个后缀把「等待」的形容词变成可测的状态。"},{"word":"expectancy","structure":"expectant + -ancy","meaning":"the state of awaiting","meaningCN":"期待的状态","example":"Psychology uses the state noun where it needs a variable.","exampleCN":"心理学在需要变量时用这个表状态的名词。"}],"latinEntries":[{"word":"spectare","structure":"spectare, spectavi, spectatum (verb, first conjugation)","meaning":"to look at, watch","meaningCN":"看；观看"},{"word":"exspectare","structure":"exspectare, exspectavi, exspectatum (verb, first conjugation)","meaning":"to look out for, await","meaningCN":"张望；等待"},{"word":"exspectatio","structure":"exspectatio, exspectationis (f., third declension)","meaning":"a looking for, expectation","meaningCN":"期待；预期"},{"word":"spectus","structure":"spectus, -a, -um (past participle)","meaning":"seen, looked at","meaningCN":"被看见的"}]}},{"word":"expect","ipa_uk":"/ɪkˈspekt/","ipa_us":"/ɪkˈspekt/","definition_zh":"期待；预计；要求；料想；怀有身孕","definition_en":"to believe that something will happen, to await it, or to require it as a duty","core_image":"一个人站在门口向外望，手里已经握住门把","scene":"站台上，家长不断看表，孩子乘坐的列车还有十分钟到站。She did not expect the train to be so crowded.","sceneCN":"这里 expect 指「料想某事会发生」（第 1 个义项：认为某事将会发生）；句意为他没想到列车会这么拥挤。场景要素：站台、看表的手、到站显示屏。","pos":[{"tag":"vt.","zh":"期待；预计；要求；料想"},{"tag":"vi.","zh":"怀有身孕（进行时）"}],"collocations":[{"phrase":"expect to do something","zh":"预计会做某事"},{"phrase":"expect somebody to do something","zh":"指望某人做某事"},{"phrase":"as expected","zh":"如预期那样"},{"phrase":"expect the best","zh":"往好处想"},{"phrase":"be expecting a baby","zh":"怀着孩子"},{"phrase":"expect a rise in prices","zh":"预计价格上涨"}],"forms":[{"label":"三单（he/she/it）","form":"expects"},{"label":"过去式","form":"expected"},{"label":"过去分词","form":"expected"},{"label":"现在分词","form":"expecting"},{"label":"名词","form":"expectation"},{"label":"形容词","form":"expectant"}],"derivatives":[{"word":"expectation","pos":"n.","zh":"由 expect 加名词后缀构成，指预期或期望的事物"},{"word":"expected","pos":"adj.","zh":"由 expect 加过去分词词尾构成，指按计划应当发生的"},{"word":"unexpected","pos":"adj.","zh":"由否定前缀加 expected 构成，指出乎意料的"},{"word":"expectant","pos":"adj.","zh":"由 expect 加形容词后缀构成，指期待着的或即将为人父母的"},{"word":"expectantly","pos":"adv.","zh":"由 expectant 加副词后缀构成，指以期待的神情"}],"senses":[{"no":"01","title":"Believe something will happen","titleCN":"认为某事将会发生","definition":"to think that an event is likely to happen, on the basis of evidence or habit","definitionCN":"基于证据或习惯，认为某事件很可能会发生","example":"Economists expect a slight fall in exports this quarter.","exampleCN":"经济学家预计本季度出口会小幅下降。","why":"The Latin verb means to look out for, so the modern verb is that watch turned into a claim about the future.","whyCN":"那个拉丁动词意为「向外张望」，因此现代动词就是那种张望变成了对未来的断言。"},{"no":"02","title":"Await an arrival","titleCN":"等着某人到来","definition":"to be waiting for a person or thing that is due to come","definitionCN":"正在等候按计划要来的人或物","example":"We expect the auditors at nine and the courier before noon.","exampleCN":"我们等审计人员九点到，快递中午前到。","why":"Waiting is the original physical sense, and it survives whenever the object is a person or a delivery rather than a fact.","whyCN":"等待是最初的具体义，只要对象是人或送来的东西而非事实，它就仍然成立。"},{"no":"03","title":"Require as a duty","titleCN":"按规矩或职责要求","definition":"to require something of someone because a rule, role or standard demands it","definitionCN":"因规则、身份或标准而要求某人做到某事","example":"The school expects students to cite every source.","exampleCN":"学校要求学生为每一处来源标注出处。","why":"A prediction about a person's behaviour easily becomes an obligation, which is how the demanding sense grew out of the forecasting one.","whyCN":"对人的行为所作预判很容易变成义务，要求的义项就是这样从预判义长出来的。"},{"no":"04","title":"Suppose without certainty","titleCN":"不确定地推测","definition":"to suppose or guess, often marked as uncertain in speech","definitionCN":"推测或猜想，口语中常带不确定的标记","example":"I expect you have already heard the news.","exampleCN":"我猜你已经听说这个消息了。","why":"When the evidence is thin, the same verb softens into mere supposition, and English marks this with a plain declarative tone.","whyCN":"证据不足时，同一个动词软化为单纯的推测，英语靠平直的陈述语气来标出这一点。"},{"no":"05","title":"Be expecting a baby","titleCN":"怀着孩子","definition":"in the progressive, to be pregnant","definitionCN":"用于进行时，指正在怀孕","example":"She is expecting in early spring and has already told her team.","exampleCN":"她初春就要生产，已经告诉了团队。","why":"The waiting sense is applied to a birth, and English uses the progressive as a polite stand-in for the word pregnant.","whyCN":"等待义被用到生产上，英语用进行时作为「怀孕」的委婉说法。"},{"no":"06","title":"Forecast in figures","titleCN":"以数字作预测","definition":"to forecast a quantity, as analysts do with prices, demand or earnings","definitionCN":"像分析师对价格、需求或收益那样预测一个数量","example":"Analysts expect inflation to stay above target until winter.","exampleCN":"分析师预计通胀会一直高于目标直到冬季。","why":"Once the object is a number, the verb belongs to forecasting, and the sentence reads as a projection rather than a hope.","whyCN":"一旦对象是数字，这个动词就属于预测语境，句子读起来是投影而非愿望。"},{"no":"07","title":"Require much of someone","titleCN":"对某人要求很高","definition":"to demand a high level of effort or behaviour from someone","definitionCN":"对某人的努力或表现提出很高要求","example":"The coach expects a great deal from the senior rowers.","exampleCN":"教练对资深桨手要求很高。","why":"The demanding sense intensifies when the standard is high, and the verb then describes pressure rather than prediction.","whyCN":"标准一高，要求的义项就加重，这个动词于是描述压力而不是预判。"},{"no":"08","title":"Be due to arrive","titleCN":"按时刻应当到达","definition":"to be scheduled or due, as a train or flight is","definitionCN":"如列车或航班那样，按安排应当到达","example":"The flight is expected at half past six, weather permitting.","exampleCN":"天气允许的话，这班飞机预计六点半到。","why":"Schedules turned the verb into a passive formula, which is why stations and airports use it for anything with a timetable.","whyCN":"时刻表把这个动词变成了被动套语，因此车站与机场用它指任何有时间表的事物。"}],"etymology":{"intro":{"en":"Expect comes from Latin exspectare 'to look out for', a prefix meaning 'out' plus a frequentative verb for looking. Dates are approximate.","cn":"expect 来自拉丁语 exspectare「向外张望」，由表「向外」的前缀加一个表示反复看的动词构成。年代均为约数。"},"items":[{"era":"LATIN EX-","en":"The prefix meant 'out, outward', aiming the gaze beyond the present spot.","cn":"这个前缀意为「向外、出去」，把目光投向当下位置之外。"},{"era":"LATIN SPECTARE","en":"Spectare 'to look at' was built on the verb for seeing; the deeper origin of that verb is not established.","cn":"spectare「看」建立在表「看见」的动词上；那个动词的更早来源未得到证明。"},{"era":"LATIN EXSPECTARE","en":"The compound meant 'to look out for, await', and it already carried both the watching and the believing.","cn":"这个复合动词意为「向外张望、等待」，已经同时带着「看」与「相信」。"},{"era":"FRENCH AND ENGLISH","en":"The verb reached English in the fourteenth century, and the sense of requiring something of a person appears by the sixteenth.","cn":"这个动词在十四世纪进入英语，而「对人提出要求」的义项到十六世纪才出现。"},{"era":"MODERN USES","en":"Timetables gave the passive formula for arrivals, and the progressive became a standard way to say that someone is pregnant.","cn":"时刻表给出了关于到达的被动套语，进行时则成为说某人怀孕的常用方式。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use is recorded only approximately, and the pre-Latin origin of the verb for seeing is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：最早的英语用例只有约略记载；那个表「看见」的动词在拉丁语之前的来源亦无定论，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root words and the near look-alike that share the looking verb; group two holds near neighbours for waiting and for requiring.","cn":"第一组是同根词以及共用「看」这一动词的近形词；第二组是表示等待与要求的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"expectation","ipa":"/ˌekspekˈteɪʃn/","tag":"the noun","definition":"The noun for the belief or the standard; the verb needs a subject and a clause where the noun needs only a possessive.","definitionCN":"指信念或标准的名词；动词需要主语与从句，而名词只需所有格。"},{"word":"expectant","ipa":"/ɪkˈspektənt/","tag":"waiting as a state","definition":"An adjective describing someone already in a waiting state; the verb describes the act of forecasting.","definitionCN":"形容已处在等待状态的人；动词描述的是预判这一行为。"},{"word":"inspect","ipa":"/ɪnˈspekt/","tag":"look into","definition":"Built with a prefix meaning 'in, into' plus the same looking root, so it means examining closely, not awaiting.","definitionCN":"由表「向内」的前缀加同一个「看」词根构成，意为仔细检查而非等待。"},{"word":"respect","ipa":"/rɪˈspekt/","tag":"look back at","definition":"Built with a prefix meaning 'back' plus the same root, so it originally meant looking back with regard; it has no forecasting sense.","definitionCN":"由表「向后」的前缀加同一词根构成，原指回头看重，并无预判义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anticipate","ipa":"/ˈæntɪsɪpeɪt/","tag":"act before","definition":"To expect something and often to act in advance because of it; the English verb stresses the preparation, not the belief.","definitionCN":"指预料某事，且常因此提前行动；这个英语动词强调准备而非信念。"},{"word":"await","ipa":"/əˈweɪt/","tag":"wait for","definition":"A formal verb for waiting on a person or event; it carries no forecasting claim about whether the thing will come.","definitionCN":"正式用语，指等候某人或某事；它并不断言那件事是否真会来。"},{"word":"suppose","ipa":"/səˈpəʊz/","tag":"think without certainty","definition":"To assume something for the sake of argument or in the absence of proof; expect is usually stronger.","definitionCN":"指为讨论起见或在无证据时假定某事；expect 通常更强。"},{"word":"require","ipa":"/rɪˈkwaɪə/","tag":"demand by right","definition":"To demand something as necessary, often with authority; expect only implies a demand when context supplies the authority.","definitionCN":"指凭借权威要求某事为必需；expect 只有在语境给出权威时才含要求。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real looking root, the real family and the real patterns.","cn":"正常联想：真实的前缀、表「看」的词根、真实的词族与真实的句式。"},"normal":[{"en":"The Latin verb means to look out for, so expecting is keeping watch in advance.","cn":"那个拉丁动词意为「向外张望」，因此期待就是提前守住目光。"},{"en":"The looking root also builds spectator, inspect, respect and spectacle.","cn":"表「看」的词根还构成 spectator、inspect、respect 与 spectacle。"},{"en":"The family runs expect, expected, unexpected, expectant, expectation, expectancy.","cn":"同族词包括 expect、expected、unexpected、expectant、expectation、expectancy。"},{"en":"The common patterns are expect to do and expect somebody to do.","cn":"常见句式是「预计做某事」与「指望某人做某事」。"},{"en":"The progressive be expecting is the polite way to say pregnant.","cn":"进行时说法是「怀孕」的委婉表达。"}],"abstract":[{"en":"Picture a hand already on the door handle before the knock comes.","cn":"想象敲门声还没响，手已经握在门把上。"},{"en":"Picture a timetable that announces a train nobody can see yet.","cn":"想象时刻表宣布一班还看不见的列车。"},{"en":"Picture a teacher who writes the standard on the board before the work starts.","cn":"想象老师在开工前先把标准写在黑板上。"}]},"examples":[{"en":"We expect the results by Friday, though the lab has not promised anything.","cn":"我们预计周五前出结果，尽管实验室并未承诺。"},{"en":"She expects her students to question every figure they are given.","cn":"她要求学生质疑给到他们的每一个数字。"},{"en":"The concert is expected to start twenty minutes late.","cn":"音乐会预计晚二十分钟开始。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「向外看」——把目光提前投出去等结果，就是期待与预计","word":"expect"},"root":"拉丁 exspectare「向外张望」由意为「向外」的前缀加 spectare（反复看）；spectare 出自表「看见」的词根，该词根更深来源不确定。英语 expect。","sensesIntro":{"en":"Eight senses follow one watch: looking out for what is coming. The watch becomes a forecast, then a wait, then a rule imposed on someone, then a bare guess, then a pregnancy, then a projection in figures, then a high demand, and finally a line on a timetable.","cn":"八个义项沿同一道目光展开：向外张望将要到来之物。这道目光依次变成预判、等候、加于他人的规矩、纯然的猜测、怀孕、以数字作出的投影、很高的要求，最后是时刻表上的一行。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person at a doorway looking outward with a hand already on the handle.","cn":"核心意象：一个人站在门口向外望，手已经握在门把上。"},"chain":["LOOK OUT","FORESEE","AWAIT","DEMAND","CARRY A CHILD","DUE TO ARRIVE"],"branches":[{"senses":"01 · 06","en":"FORECAST: a plain belief about the future and a projection in figures are the same claim at different precision.","cn":"预判：对未来的朴素信念与以数字作出的投影，是同一断言的不同精度。"},{"senses":"02 · 08","en":"WAITING: awaiting a guest and a flight due on a timetable are the watch made concrete.","cn":"等待：等客人，与等时刻表上的航班，都是那道目光的具体化。"},{"senses":"03 · 07","en":"DEMAND: a rule imposed on someone and a high standard set for them are expectation turned into pressure.","cn":"要求：加于人的规矩与为人设下的高标准，都是预期变成了压力。"},{"senses":"04","en":"BARE GUESS: when evidence thins, the same verb softens into supposition.","cn":"纯然猜测：证据变薄时，同一个动词软化为推测。"},{"senses":"05","en":"WAITING FOR A BIRTH: the polite progressive borrows the waiting sense for pregnancy.","cn":"等待生产：委婉的进行时把等待义借去指怀孕。"}]},"affixes":{"intro":{"en":"Expect is a short Latin verb of two pieces, and both pieces build large English families.","cn":"expect 是一个由两部分构成的简短拉丁动词，两部分都构成大族英语词。"},"latinIntro":{"en":"The prefix meaning 'out' gives export, exclude and extend; the looking root gives inspect, respect, spectator and spectacle.","cn":"表「向外」的前缀衍生 export、exclude 与 extend；表「看」的词根衍生 inspect、respect、spectator 与 spectacle。"},"items":[{"word":"ex-","structure":"ex- (Latin prefix, 'out')","meaning":"out; outward","meaningCN":"向外；出去","example":"The prefix aims the looking beyond the present place.","exampleCN":"这个前缀把目光投向当下所在之外。"},{"word":"spectare","structure":"spectare (Latin frequentative verb)","meaning":"to look at","meaningCN":"看；观看","example":"The root supplies the watching that the word is built on.","exampleCN":"这个词根提供这个词所由建立的「看」。"},{"word":"expect","structure":"exspectare through French","meaning":"to look out for","meaningCN":"向外张望；期待","example":"The verb keeps the prefix and drops the repeated-looking suffix.","exampleCN":"动词保留前缀，去掉了表反复看的那层后缀。"},{"word":"-ation","structure":"-atio (Latin noun suffix)","meaning":"action or result","meaningCN":"行为或结果","example":"The suffix builds the noun of the act.","exampleCN":"这个后缀造出该行为的名词。"},{"word":"expectation","structure":"expect + -ation","meaning":"a looking-for","meaningCN":"预期；期望","example":"The noun is far more common than a literal translation suggests.","exampleCN":"这个名词远比字面直译看来常用。"},{"word":"-ant","structure":"-ans (Latin adjective suffix, 'doing')","meaning":"doing, in a state","meaningCN":"正在……的","example":"The suffix builds the adjective for someone waiting.","exampleCN":"这个后缀造出形容等待者的形容词。"},{"word":"expectant","structure":"expect + -ant","meaning":"waiting; about to become a parent","meaningCN":"期待着的；即将为人父母的","example":"The adjective has a settled medical use.","exampleCN":"这个形容词有固定的医疗用法。"},{"word":"-ed","structure":"-ed (English participial suffix)","meaning":"having been","meaningCN":"已被……的","example":"The participle form builds the ordinary adjective of scheduled things.","exampleCN":"分词形式造出指按计划之事的常用形容词。"},{"word":"expected","structure":"expect + -ed","meaning":"scheduled, foreseen","meaningCN":"按计划发生的；被预见的","example":"The adjective appears in timetables and in test marking.","exampleCN":"这个形容词出现在时刻表与阅卷语境中。"},{"word":"un-","structure":"un- (English negative prefix)","meaning":"not","meaningCN":"不","example":"The negative prefix marks what no forecast covered.","exampleCN":"否定前缀标出预判未覆盖之事。"}],"latinEntries":[{"word":"spectare","structure":"spectare, spectavi, spectatum (verb, first conjugation)","meaning":"to look at","meaningCN":"看；观看"},{"word":"exspectare","structure":"exspectare, exspectavi, exspectatum (verb, first conjugation)","meaning":"to look out for, await","meaningCN":"张望；等待"},{"word":"exspectatio","structure":"exspectatio, exspectationis (f., third declension)","meaning":"expectation","meaningCN":"预期"},{"word":"spectus","structure":"spectus, -a, -um (past participle)","meaning":"looked at, seen","meaningCN":"被看见的"}]}},{"word":"attitude","ipa_uk":"/ˈætɪtjuːd/","ipa_us":"/ˈætɪtuːd/","definition_zh":"态度；看法；姿态；（芭蕾）阿蒂迪德舞姿","definition_en":"a settled way of thinking or feeling about someone or something, or a posture of the body","core_image":"一个人站定，肩膀微微侧转，眼神已经表明了立场","scene":"面试候场区，一名求职者靠在椅背上，双臂交叠。The interviewer noted his relaxed attitude and asked an easier question first.","sceneCN":"这里 attitude 指「对眼前处境所持的心态」（第 1 个义项：对人对事的稳定心态）；句意为面试官注意到他放松的态度，于是先问了个容易的问题。场景要素：候场椅、交叠的双臂、简历夹。","pos":[{"tag":"n.","zh":"态度；看法；姿态；（芭蕾）一种舞姿"}],"collocations":[{"phrase":"a positive attitude","zh":"积极的态度"},{"phrase":"attitude towards","zh":"对……的态度"},{"phrase":"change one's attitude","zh":"改变态度"},{"phrase":"an attitude problem","zh":"态度有问题"},{"phrase":"strike an attitude","zh":"摆出姿态"},{"phrase":"attitude survey","zh":"态度调查"}],"forms":[{"label":"复数","form":"attitudes"},{"label":"形容词","form":"attitudinal"},{"label":"副词","form":"attitudinally"}],"derivatives":[{"word":"attitudinal","pos":"adj.","zh":"由 attitude 加形容词后缀构成，指与态度有关的"},{"word":"attitudinize","pos":"v.","zh":"由 attitude 加动词后缀构成，指装腔作势地摆姿态"},{"word":"aptitude","pos":"n.","zh":"与 attitude 同出拉丁语「适合」一词，指天生的能力倾向，词义已分岔"},{"word":"apt","pos":"adj.","zh":"同词根的形容词，指恰当的、易于……的"}],"senses":[{"no":"01","title":"A settled way of thinking or feeling","titleCN":"稳定的想法或感受","definition":"a fairly fixed orientation of mind toward a person, object or situation","definitionCN":"对某人、某物或某种处境较为固定的心理取向","example":"Her attitude toward the new policy softened after she read the report.","exampleCN":"读完报告后，她对新政策的态度软化了。","why":"The word's base means 'fitness' or 'aptness', so an attitude was first a fitting arrangement, and the mental sense keeps that idea of a settled arrangement.","whyCN":"这个词的基底意为「合适、贴合」，因此态度最初指恰当的摆位，心理义保留了「稳定摆好」的意思。"},{"no":"02","title":"A posture of the body","titleCN":"身体的姿态","definition":"the position in which a person holds the body, especially a studied one","definitionCN":"人保持身体的姿势，尤指刻意摆出的姿势","example":"He listened with his head tilted in an attitude of patience.","exampleCN":"他微微偏头，摆出一副耐心倾听的姿态。","why":"The physical sense is the oldest, and it survives in art criticism, dance and descriptions of bearing.","whyCN":"身体义是最古老的一层，至今保存在艺术评论、舞蹈与举止描写中。"},{"no":"03","title":"A confident or assertive manner","titleCN":"自信张扬的做派","definition":"a manner that projects self-assurance, sometimes deliberately provocative","definitionCN":"表现出自信的做派，有时带故意的挑衅","example":"The young guitarist walked on stage with attitude and no introduction.","exampleCN":"年轻吉他手带着一股张扬劲儿上台，没有一句开场白。","why":"Once posture becomes a signal, it can be worn like clothing, and the word comes to name a projected manner.","whyCN":"姿态一旦成为信号，就可以像衣服一样穿在身上，这个词于是指一种对外投射的做派。"},{"no":"04","title":"A hostile or confrontational manner","titleCN":"对抗性的态度","definition":"a manner that challenges the other party, often in casual speech as a complaint","definitionCN":"对对方带挑战意味的做派，口语中常作为抱怨说法","example":"The clerk gave me attitude when I asked for a receipt.","exampleCN":"我要收据时，那名店员给我脸色看。","why":"The same projected manner can be read as hostility, and everyday speech narrowed the word to that reading.","whyCN":"同一种投射出来的做派也可以被读作敌意，日常口语把这个词收窄到这一读法。"},{"no":"05","title":"The orientation of a vehicle in space","titleCN":"飞行器在空间中的姿态","definition":"the orientation of an aircraft or spacecraft relative to a reference frame","definitionCN":"飞行器相对于某个参照系的朝向","example":"The thrusters fired to correct the capsule's attitude before re-entry.","exampleCN":"返回舱再入前，推进器点火修正它的姿态。","why":"Engineering simply kept the old sense of a body's position and removed the mind entirely.","whyCN":"工程学只是保留了「物体的位置」这一旧义，把心智那部分完全去掉。"},{"no":"06","title":"An evaluative disposition measured by scales","titleCN":"可用量表测量的评价倾向","definition":"in psychology, a relatively stable evaluation of an object, measured along dimensions such as favour and strength","definitionCN":"心理学中，对某对象的较稳定评价，按喜好程度与强度等维度测量","example":"The questionnaire scored attitudes toward recycling on a seven-point scale.","exampleCN":"问卷用七点量表测量人们对回收的态度。","why":"To be studied, the orientation had to be turned into a number, and the word moved into the laboratory.","whyCN":"要研究这种取向，就得把它变成数字，这个词于是进入实验室。"},{"no":"07","title":"A shared orientation within a group","titleCN":"群体中共有的取向","definition":"in sociology, an orientation widely held in a group and transmitted through it","definitionCN":"社会学中，一个群体广泛持有并相互传递的取向","example":"Public attitudes toward the levy shifted within a single generation.","exampleCN":"公众对这项征税的态度在一代人之内就变了。","why":"When the orientation is counted across many people, it stops being personal and becomes a social fact.","whyCN":"当这种取向在许多人身上被计数时，它就不再是个人的，而成为社会事实。"},{"no":"08","title":"A stance taken in a negotiation","titleCN":"谈判中所取的立场","definition":"the position one adopts toward a deal, such as flexibility or firmness","definitionCN":"在一笔交易中所采取的立场，如灵活或强硬","example":"Their opening attitude was conciliatory, which made the later demand look harder.","exampleCN":"他们开场的态度是和解的，这反而让后来的要求显得更强硬。","why":"A posture toward an opponent is only a metaphor away from a posture of the body, and negotiation language took it.","whyCN":"对对手的「姿态」离身体的姿态只差一个比喻，谈判语言就把它借了过去。"}],"etymology":{"intro":{"en":"Attitude comes through French and Italian from Late Latin aptitudo 'fitness', built on aptus 'fit, suited'. It is not related to the verb for acting. Dates are approximate.","cn":"attitude 经法语与意大利语来自晚期拉丁语 aptitudo「合适」，其基础是 aptus「适合的」。它与表「行动」的动词并无亲缘关系。年代均为约数。"},"items":[{"era":"LATIN APTUS","en":"Aptus meant 'fit, suited, fastened'. The same root gives adapt and apt in English.","cn":"aptus 意为「适合的、合身的、系紧的」。同一词根在英语中给出 adapt 与 apt。"},{"era":"LATE LATIN APTITUDO","en":"The noun aptitudo named fitness or suitability, the state of being well arranged.","cn":"名词 aptitudo 指合适或相称，即摆得妥当的状态。"},{"era":"ITALIAN ATTITUDINE","en":"Italian shortened and reshaped the noun into attitudine, which also named a posture of the body in art.","cn":"意大利语把这个名词缩短改形为 attitudine，也用来指艺术中身体的姿势。"},{"era":"FRENCH ATTITUDE","en":"French took the art sense and passed it to English in the seventeenth century, where posture came first.","cn":"法语接走这层艺术义，并在十七世纪传入英语，最初正是身体姿势。"},{"era":"MENTAL SENSE","en":"By the eighteenth century the word was applied to the mind's stance, and psychology later made that stance measurable.","cn":"到十八世纪，这个词被用到心智所取的立场，心理学后来让这种立场变得可测量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use is recorded only approximately, and the pre-Latin origin of aptus is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：最早的英语用例只有约略记载；aptus 在拉丁语之前的来源亦无定论，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds look-alike words from the same fitness root or mistaken for it; group two holds near neighbours for a view or a bearing.","cn":"第一组是同出「适合」词根、或被误认为同源的近形词；第二组是表示看法或举止的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"aptitude","ipa":"/ˈæptɪtjuːd/","tag":"same root, ability","definition":"Built on the same Latin word for fitness, but it means a natural capacity for learning something, not a stance.","definitionCN":"建立在同一个表「适合」的拉丁词上，但指学习某事的天然能力，而非立场。"},{"word":"altitude","ipa":"/ˈæltɪtjuːd/","tag":"different root","definition":"Built on the Latin word for high, so it means height above a reference level; it is not a relative of attitude.","definitionCN":"建立在拉丁语中表「高」的词上，指相对某基准的高度；与 attitude 并非同族。"},{"word":"attitudinal","ipa":"/ˌætɪˈtjuːdɪnl/","tag":"the adjective","definition":"The adjective for anything concerning attitudes, common in survey research.","definitionCN":"指与态度有关的形容词，常用于调查研究中。"},{"word":"apt","ipa":"/æpt/","tag":"the bare root word","definition":"Means suitable or quick to learn; it keeps the old fitness sense without any mental stance.","definitionCN":"意为合适的或学得快的，保留了古老「适合」义，不含心理立场。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stance","ipa":"/stæns/","tag":"a taken position","definition":"A public position on an issue, often deliberate; attitude can stay private and unstated.","definitionCN":"指对某议题公开采取的立场，往往是有意为之；attitude 可以是私下未说出的。"},{"word":"outlook","ipa":"/ˈaʊtlʊk/","tag":"the general view","definition":"A broad way of seeing life or the future; attitude is usually aimed at a particular object.","definitionCN":"指看待生活或未来的总体眼光；attitude 通常针对具体对象。"},{"word":"posture","ipa":"/ˈpɒstʃə/","tag":"the body only","definition":"The position of the body, or a deliberately assumed position; it keeps the physical sense that attitude partly abandoned.","definitionCN":"指身体的位置，或刻意摆出的立场，保留了 attitude 部分放弃的身体义。"},{"word":"opinion","ipa":"/əˈpɪnjən/","tag":"a stated view","definition":"A view one holds and can state; attitude adds the emotional tone and the readiness to act.","definitionCN":"指所持并可陈述的看法；attitude 多了情绪色彩与行动准备。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real fitness root, the real family and the real phrases, plus the odd vehicle sense.","cn":"正常联想：真实的「适合」词根、真实的词族、真实的短语，以及那个特别的飞行器义。"},"normal":[{"en":"The Latin base means fit or suited, so the oldest sense of attitude is a well-arranged posture.","cn":"拉丁语基底意为「适合、相称」，因此 attitude 最古老的义项是摆得妥当的姿势。"},{"en":"The family runs apt, aptitude, attitude, attitudinal, adapt.","cn":"同族词包括 apt、aptitude、attitude、attitudinal、adapt。"},{"en":"Fixed phrases mark the mental sense: a positive attitude, attitude towards, an attitude problem.","cn":"固定搭配标出心理义：积极的态度、对……的态度、态度有问题。"},{"en":"Dance and art criticism keep the body sense, and aviation keeps the orientation sense.","cn":"舞蹈与艺术评论保留身体义，航空领域保留朝向义。"},{"en":"The word is not related to the verb for acting, despite the similar sound of the two in English.","cn":"这个词与表「行动」的动词并无亲缘，尽管两个英语词听起来相近。"}],"abstract":[{"en":"Picture a body turned three quarters toward the door before a word is spoken.","cn":"想象还没开口，身体已侧转到四分之三朝向门口。"},{"en":"Picture a pair of glasses worn on the mind rather than on the face.","cn":"想象一副戴在心上而不是脸上的眼镜。"},{"en":"Picture a spacecraft slowly rotating to face the sun.","cn":"想象一艘飞船缓慢转动，让朝向对准太阳。"}]},"examples":[{"en":"The training changed attitudes toward error reporting more than any rule did.","cn":"相比任何规定，这项培训更有效地改变了对上报差错的态度。"},{"en":"She answered every question with the same calm attitude.","cn":"她以同样沉着的态度回答了每个问题。"},{"en":"The pilot reported an unusual attitude after the turbulence.","cn":"遭遇颠簸后，飞行员报告了异常的机身姿态。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「摆好姿势」——身体摆好是姿态，心里摆好就是态度","word":"attitude"},"root":"晚期拉丁 aptitudo「合适」= aptus「适合的」+ 名词后缀，经意大利语与法语进入英语；aptus 更深来源不确定。英语 attitude。","sensesIntro":{"en":"Eight senses follow one arrangement of the body or mind: something is set in a position toward something else. The arrangement is read as a mental stance, a physical posture, a projected manner, a hostile manner, a vehicle's orientation, a measured score, a group's shared view and a negotiator's position.","cn":"八个义项沿同一个「摆位」展开：身体或心智朝向某物摆好。这个摆位依次被读作心理立场、身体姿势、外在做派、对抗姿态、飞行器朝向、量表得分、群体共有看法与谈判立场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body already turned toward the door before a single word is spoken.","cn":"核心意象：一句话还没说，身体已经转向门口。"},"chain":["TAKE A POSITION","SET THE BODY","PROJECT A MANNER","POINT IN SPACE","MEASURE IT","SHARE IT"],"branches":[{"senses":"01 · 07","en":"PERSONAL AND SHARED: one person's settled view and a group's counted view are the same arrangement at two scales.","cn":"个人与共有：一个人的稳定看法与一个群体被计数的看法，是同一摆位的两种尺度。"},{"senses":"02","en":"BODY FIRST: the physical posture is the oldest sense and the source of the metaphor.","cn":"身体在先：身体姿势是最古老的义项，也是整个比喻的来源。"},{"senses":"03 · 04","en":"MANNER: the same projected bearing can read as confidence or as hostility.","cn":"做派：同一种外显举止，可以被读作自信，也可以被读作敌意。"},{"senses":"05 · 08","en":"POSITION IN SPACE AND IN TALK: a spacecraft's orientation and a negotiator's opening stance are both a pointing-toward.","cn":"空间与言谈中的位置：飞行器朝向与谈判开场的立场，都是一种「指向」。"},{"senses":"06","en":"MADE COUNTABLE: psychology turns the arrangement into a score on a scale.","cn":"变成可计数：心理学把这种摆位变成量表上的分数。"}]},"affixes":{"intro":{"en":"Attitude is a Latin adjective plus two Latin noun layers, filtered through Italian and French, and the same root builds apt and adapt.","cn":"attitude 是一个拉丁形容词加两层拉丁名词，再经意大利语与法语过滤而成；同一词根还构成 apt 与 adapt。"},"latinIntro":{"en":"Latin aptus gives apt, aptitude, attitude and adapt; the noun-forming layers recur in latitude, longitude and solitude.","cn":"拉丁 aptus 衍生 apt、aptitude、attitude 与 adapt；那些名词后缀还出现在 latitude、longitude 与 solitude 中。"},"items":[{"word":"aptus","structure":"aptus, -a, -um (Latin adjective)","meaning":"fit, suited, fastened","meaningCN":"适合的；系紧的","example":"The root supplies the idea of something well fitted to its place.","exampleCN":"这个词根提供「某物与所处位置相合」的意思。"},{"word":"aptitudo","structure":"aptus + -itudo (Late Latin noun suffix)","meaning":"fitness, suitability","meaningCN":"合适；相称","example":"The Late Latin noun named the state of being well arranged.","exampleCN":"这个晚期拉丁名词指摆得妥当的状态。"},{"word":"-itudo","structure":"-itudo (Latin noun suffix, 'state')","meaning":"state of being","meaningCN":"……的状态","example":"The suffix builds abstract nouns of condition.","exampleCN":"这个后缀造出表状态的名词。"},{"word":"attitudine","structure":"Italian reshaping of aptitudo","meaning":"posture, disposition","meaningCN":"姿势；倾向","example":"Italian added the body sense that English first borrowed.","exampleCN":"意大利语加入了身体义，英语最初借的正是这一层。"},{"word":"attitude","structure":"attitudine through French","meaning":"posture, then mental stance","meaningCN":"姿势，后指心理立场","example":"The English word moved from body to mind.","exampleCN":"这个英语词从身体移到了心智。"},{"word":"aptitude","structure":"aptus + -itudo (French route)","meaning":"natural ability","meaningCN":"天资；能力倾向","example":"The same root took a different road and kept the ability sense.","exampleCN":"同一词根走了另一条路，保留了能力义。"},{"word":"apt","structure":"aptus (Latin) directly","meaning":"suitable, quick","meaningCN":"合适的；敏捷的","example":"The bare adjective survives beside the long noun.","exampleCN":"光秃秃的形容词与长长的名词并存。"},{"word":"adapt","structure":"ad- 'to' + aptare","meaning":"to fit to","meaningCN":"使适应","example":"A prefixed verb from the same root means fitting one thing to another.","exampleCN":"同词根加前缀的动词，意为把一物配到另一物上。"},{"word":"attitudinal","structure":"attitude + -inal","meaning":"relating to attitudes","meaningCN":"与态度有关的","example":"The adjective is standard in survey research.","exampleCN":"这个形容词在调查研究中是标准用法。"}],"latinEntries":[{"word":"aptus","structure":"aptus, -a, -um (adjective)","meaning":"fit, suited","meaningCN":"适合的"},{"word":"aptitudo","structure":"aptitudo, aptitudinis (f., third declension)","meaning":"fitness, suitability","meaningCN":"合适；相称"},{"word":"aptare","structure":"aptare, aptavi, aptatum (verb, first conjugation)","meaning":"to fit, to adapt","meaningCN":"使适合；配好"}]}},{"word":"cognitive bias","ipa_uk":"/ˌkɒɡnətɪv ˈbaɪəs/","ipa_us":"/ˌkɑːɡnətɪv ˈbaɪəs/","definition_zh":"认知偏差；思维中系统性偏离理性判断的倾向","definition_en":"a systematic pattern of deviation from rational judgment in perceiving, remembering or deciding","core_image":"同一张照片被两副有色镜片各染成一种颜色","scene":"研究课上，学生先被告知某组数据支持假设，再回头看同一份表格。The lecturer explains that this shift in reading is a cognitive bias, not dishonesty.","sceneCN":"这里 cognitive bias 指「思维系统性地偏离理性判断的倾向」（第 1 个义项：判断系统性偏离）；句意为讲师说明这种读表方式的偏移属于认知偏差，而非不诚实。场景要素：同一份表格、两副有色镜片、投影幕。","pos":[{"tag":"n.","zh":"认知偏差；系统性思维偏移"}],"collocations":[{"phrase":"a common cognitive bias","zh":"常见的认知偏差"},{"phrase":"cognitive bias in judgment","zh":"判断中的认知偏差"},{"phrase":"reduce cognitive bias","zh":"减少认知偏差"},{"phrase":"a catalogue of cognitive biases","zh":"认知偏差名录"},{"phrase":"cognitive bias in forecasting","zh":"预测中的认知偏差"},{"phrase":"debiasing cognitive bias","zh":"矫正认知偏差"}],"forms":[{"label":"复数","form":"cognitive biases"},{"label":"形容词","form":"cognitively biased"},{"label":"相关名词","form":"bias"}],"derivatives":[{"word":"bias","pos":"n./v.","zh":"该短语的中心词，来自法语中表「斜」的词，指偏向或使有偏向"},{"word":"biased","pos":"adj.","zh":"由 bias 加过去分词词尾构成，指带有偏向的"},{"word":"unbiased","pos":"adj.","zh":"由否定前缀加 biased 构成，指不带偏向的"},{"word":"debias","pos":"v.","zh":"由否定前缀加 bias 构成的动词，指去除偏差"},{"word":"cognitive","pos":"adj.","zh":"短语前半，指与心理加工有关的"}],"senses":[{"no":"01","title":"Systematic deviation from rational judgment","titleCN":"系统性偏离理性判断","definition":"a repeatable pattern in which judgments depart from what the evidence supports","definitionCN":"判断反复偏离证据支持之结论的一种可重复模式","example":"The sunk-cost effect is a cognitive bias that keeps money flowing into a failed project.","exampleCN":"沉没成本效应是一种认知偏差，它让钱继续流进一个失败的项目。","why":"Every part of the phrase does work: the first word says the deviation lives in mental processing, the second says it leans, and systematic separates it from a random mistake.","whyCN":"短语的每一部分都在起作用：前半说偏移发生在心理加工中，后半说它有所偏斜，而「系统性」把它与随机失误区分开。"},{"no":"02","title":"A shortcut that predictably misfires","titleCN":"可预期地出错的思维捷径","definition":"a mental shortcut that saves effort and fails in a predictable direction","definitionCN":"节省心力、并朝可预测方向失效的心理捷径","example":"Availability is a cognitive bias because vivid cases crowd out the base rate.","exampleCN":"可得性是一种认知偏差，因为鲜活的个例会挤掉基础比率。","why":"Shortcuts are necessary for a mind with limited time, so the bias is not a defect added on but the price of a working heuristic.","whyCN":"对时间有限的心智来说捷径是必需的，因此这种偏差不是外加的缺陷，而是可用启发式的代价。"},{"no":"03","title":"Distortion in perception or memory","titleCN":"知觉或记忆中的扭曲","definition":"a systematic warp in what is seen, recalled or reconstructed rather than in what is concluded","definitionCN":"发生在看见、回忆或重构之中的系统性扭曲，而非结论层面的偏差","example":"The peak-end effect is a cognitive bias in memory: the last minute outweighs the other fifty.","exampleCN":"峰终效应是记忆中的认知偏差：最后一分钟压过了其余五十分钟。","why":"Once the deviation is located in the recording stage rather than in reasoning, the same phrase covers perception and recall as well as choice.ll as choice.","whyCN":"一旦偏移被定位在记录阶段而非推理阶段，同一个短语就同时覆盖知觉、回忆与选择。"},{"no":"04","title":"Anchoring and framing in choice","titleCN":"选择中的锚定与框架效应","definition":"a bias produced by the first number offered or by the way options are worded","definitionCN":"由最先给出的数字或选项的措辞方式造成的偏差","example":"The first quote anchored every later offer, a textbook cognitive bias in negotiation.","exampleCN":"第一个报价锚定了之后每一份出价，这是谈判中的教科书式认知偏差。","why":"Choice is especially vulnerable because the frame arrives before the reasoning, so the mind inherits a starting point it did not choose.","whyCN":"选择尤其脆弱，因为框架先于推理到达，心智于是继承了一个并非自己选定的起点。"},{"no":"05","title":"A bias shared within a group","titleCN":"群体内共有的偏差","definition":"a deviation that is amplified by group membership, such as in-group favouritism","definitionCN":"因群体归属而被放大的偏移，如对内群体的偏袒","example":"Hiring panels showed a cognitive bias toward candidates from their own alma mater.","exampleCN":"招聘小组对来自本校的候选人表现出一种认知偏差。","why":"When many minds lean the same way, the individual warp becomes a social pattern, and the phrase travels from psychology to organizational research.","whyCN":"当许多心智朝同一方向倾斜，个人的扭曲就变成社会模式，这个短语于是从心理学走进组织研究。"},{"no":"06","title":"Bias in research design","titleCN":"研究设计中的偏差","definition":"a systematic error introduced by sampling, measurement or the wording of a study, as distinct from a thinking habit","definitionCN":"由抽样、测量或问卷措辞引入的系统误差，与思维习惯不同","example":"The survey suffered from a cognitive bias in its sampling frame, not from dishonest answers.","exampleCN":"这项调查的问题出在抽样框上的系统性偏差，而不是回答不实。","why":"The phrase is sometimes stretched over study design, where the mechanism is in the instrument rather than in the mind, and careful writing marks the difference.","whyCN":"这个短语有时被拉去指研究设计，其机制在工具而不在心智，严谨的写作会标出这一区别。"},{"no":"07","title":"Algorithmic bias from training data","titleCN":"源自训练数据的算法偏差","definition":"a systematic skew in a model that inherits patterns from its data","definitionCN":"模型从数据中继承模式而形成的系统性偏斜","example":"The screening tool reproduced a cognitive bias present in the historical labels.","exampleCN":"这套筛选工具复制了历史标签中已有的认知偏差。","why":"Machines learn the leanings of their examples, so the human phrase was borrowed to describe an inherited skew.","whyCN":"机器会学到示例中的倾斜，于是人们借用这个描述人的短语来说一种被继承的偏斜。"},{"no":"08","title":"Debiasing and correction","titleCN":"矫正偏差的做法","definition":"the set of practices aimed at noticing and reducing such deviations","definitionCN":"旨在察觉并减少此类偏移的一套做法","example":"Checklists and blind review are standard tools against cognitive bias in hiring.","exampleCN":"清单与盲审是招聘中对抗认知偏差的常用工具。","why":"If the deviation is systematic, it can be countered systematically, and the phrase acquires a practical, corrective sense.","whyCN":"既然偏移是系统性的，就可以被系统地对抗，这个短语于是获得实用的矫正义。"}],"etymology":{"intro":{"en":"Cognitive bias joins a Latin-derived adjective for mental processing to a French-derived noun for a slant. The compound is a twentieth-century coinage. Dates are approximate.","cn":"cognitive bias 把一个拉丁来源、指心理加工的形容词，接在一个法语来源、指倾斜的名词上。这个复合词是二十世纪的造词。年代均为约数。"},"items":[{"era":"LATIN COGNOSCERE","en":"The first half rests on the Latin verb for getting to know, built with a prefix meaning 'thoroughly'.","cn":"前半部分基于拉丁语中表「逐渐认识」的动词，带一个意为「彻底」的前缀。"},{"era":"LATIN COGNITIO","en":"The noun cognitio named the act of knowing and the knowledge gained, and English borrowed it as cognition.","cn":"名词 cognitio 指认识行为与所得知识，英语把它借作 cognition。"},{"era":"OLD FRENCH BIAIS","en":"Biais meant 'slant, oblique', and its deeper origin is not established; suggestions linking it to a Latin word for slanting remain hypotheses.","cn":"biais 意为「倾斜、斜的」，其更早来源未得到证明；把它与某个表「斜」的拉丁词联系起来的说法仍属假说。"},{"era":"ENGLISH BIAS","en":"English took the noun in the sixteenth century for a slanting line, then for a leaning of the mind, and later for a systematic leaning.","cn":"英语在十六世纪借入这个名词，先指斜线，再指心智的偏向，后来指系统性的偏向。"},{"era":"MODERN COMPOUND","en":"The compound spread in the nineteen seventies with research on heuristics, where the deviation was shown to be regular rather than random.","cn":"这个复合词在二十世纪七十年代随启发式研究传播开来，那里偏移被证明是规则的而非随机的。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use and the origin of the slanting word): the earliest citation of the compound is not settled, and the pre-French origin of the noun for a slant is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（复合词最早书证与「倾斜」一词的来源）：这个复合词的最早用例尚无定论；那个表「倾斜」的名词在法语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the phrase from the bare words it is built on; group two holds near neighbours for a leaning or a mistake.","cn":"第一组把这个短语与构成它的单词区分开；第二组是表示偏向或错误的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bias","ipa":"/baɪəs/","tag":"the bare noun","definition":"Any leaning, including sampling bias and outright prejudice; the full phrase marks the leaning as a feature of mental processing.","definitionCN":"泛指任何偏向，包括抽样偏差与公开表露的成见；完整短语把这种偏向标为心理加工的特征。"},{"word":"cognitive","ipa":"/ˈkɒɡnətɪv/","tag":"the adjective alone","definition":"Relating to mental processing in general, with no suggestion of error.","definitionCN":"泛指与心理加工有关，并不暗示错误。"},{"word":"heuristic","ipa":"/hjuːˈrɪstɪk/","tag":"the mechanism, not the error","definition":"A mental shortcut that usually works; it becomes a bias only when it fails systematically.","definitionCN":"指通常有效的思维捷径；只有当它系统性地失效时才成为偏差。"},{"word":"prejudice","ipa":"/ˈpredʒudɪs/","tag":"a social attitude","definition":"A preconceived opinion about people, often hostile; cognitive bias covers any systematic deviation, including harmless perceptual ones.","definitionCN":"指对人预先形成、往往敌意的看法；认知偏差覆盖任何系统性偏移，包括无害的知觉偏移。"}]},{"heading":"NEAR MEANING","entries":[{"word":"error","ipa":"/ˈerə/","tag":"a single wrong result","definition":"One incorrect answer or measurement; a cognitive bias is a pattern that recurs in one direction.","definitionCN":"指一次错误的答案或测量；认知偏差是朝一个方向反复出现的模式。"},{"word":"distortion","ipa":"/dɪˈstɔːʃn/","tag":"a warped shape","definition":"A twisting of a shape, a signal or a record; it can be physical and need not involve thinking.","definitionCN":"指形状、信号或记录的扭曲，可以是物理的，未必涉及思考。"},{"word":"stereotype","ipa":"/ˈsteriətaɪp/","tag":"a fixed picture of a group","definition":"An oversimplified image of a group; it can feed a cognitive bias but is a content, not a mechanism.","definitionCN":"指对某群体的过度简化形象；它可以喂养认知偏差，但本身是内容而非机制。"},{"word":"illusion","ipa":"/ɪˈluːʒn/","tag":"a false perception","definition":"A perceptual falsehood, such as a line that looks longer; cognitive bias is wider and includes judgment.","definitionCN":"指知觉上的错误，如看起来更长的线；认知偏差范围更广，也包含判断。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves, the real research phrases and the real distinction from a plain mistake.","cn":"正常联想：两个真实的构成部分、真实的研究搭配，以及与单纯失误的真实区别。"},"normal":[{"en":"The first word places the deviation in mental processing and the second says it leans, so the phrase means a leaning built into thought.","cn":"前半把偏移放在心理加工里，后半说它偏斜，因此短语意为「长在思维里的偏斜」。"},{"en":"Research phrases fix the term: a common cognitive bias, reduce cognitive bias, a catalogue of cognitive biases.","cn":"研究搭配把这个术语固定下来：常见的认知偏差、减少认知偏差、认知偏差名录。"},{"en":"The key word is systematic: a bias repeats in one direction, while a mistake is scattered.","cn":"关键词是「系统性」：偏差朝一个方向反复出现，而失误是散乱的。"},{"en":"The family runs bias, biased, unbiased, debias, cognitive.","cn":"同族词包括 bias、biased、unbiased、debias、cognitive。"},{"en":"Perception, memory, choice and even training data can all carry the same leaning.","cn":"知觉、记忆、选择乃至训练数据，都可以带同一种偏斜。"}],"abstract":[{"en":"Picture one photograph viewed through two differently tinted lenses.","cn":"想象同一张照片透过两副颜色不同的镜片来观看。"},{"en":"Picture a scale whose zero is slightly off, so every weighing leans the same way.","cn":"想象一台零点偏了一点点的秤，每次称都朝同一边倾。"},{"en":"Picture a road that bends a little every kilometre and ends far from the map's destination.","cn":"想象一条路每公里都弯一点点，最后离地图上的目的地很远。"}]},"examples":[{"en":"Confirmation is a cognitive bias that makes searching for evidence feel like finding it.","cn":"确认是一种认知偏差，它让搜寻证据感觉像是找到了证据。"},{"en":"The committee added a blind review step to reduce cognitive bias in promotions.","cn":"委员会增加盲审环节，以减少晋升中的认知偏差。"},{"en":"Forecasters who keep score learn to recognise their own cognitive biases.","cn":"坚持记分的预测者会学会识别自己的认知偏差。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cognition 认知 + bias 斜」——思维本身斜了，就是认知偏差","word":"cognitive bias"},"root":"拉丁 cognitio「认识」+ 古法语 biais「倾斜」；后者更深来源不确定，二者合为现代心理学复合词。英语 cognitive bias。","sensesIntro":{"en":"Eight senses follow one leaning built into thought: the mind tilts and keeps tilting the same way. The tilt is read as a systematic deviation, as a shortcut that misfires, as a warp in perception and memory, as an anchoring frame, as a group pattern, as a flaw in a study, as a defect learned by a model, and as something that can be corrected.","cn":"八个义项沿同一个「长在思维里的倾斜」展开：心智倾了，而且总朝同一边倾。这个倾斜依次被读作系统性偏移、会失效的捷径、知觉与记忆的扭曲、锚定框架、群体模式、研究设计缺陷、模型学到的缺点，以及可以被矫正之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: one photograph seen through two differently tinted lenses.","cn":"核心意象：同一张照片透过两副颜色不同的镜片来看。"},"chain":["SEE","JUDGE","TAKE A SHORTCUT","LEAN THE SAME WAY","SHARE THE LEAN","CORRECT IT"],"branches":[{"senses":"01 · 03","en":"THE LEAN ITSELF: deviation in judgment and warp in perception or memory are the same tilt at different stages.","cn":"倾斜本身：判断上的偏移与知觉记忆上的扭曲，是同一倾斜发生在不同阶段。"},{"senses":"02 · 04","en":"THE MECHANISM AND THE STARTING POINT: a shortcut and an anchor both give the mind a place to stand.","cn":"机制与起点：捷径与锚点都给心智一个落脚处。"},{"senses":"05","en":"SHARED LEAN: many minds tilting together turn a private warp into a social pattern.","cn":"共享的倾斜：许多心智同向倾斜，把私人的扭曲变成社会模式。"},{"senses":"06 · 07","en":"LEANS OUTSIDE THE MIND: a study design and a trained model can both inherit a skew.","cn":"心智之外的倾斜：研究设计与训练出的模型都可能继承偏斜。"},{"senses":"08","en":"CORRECTION: because the lean is regular, it can be met with a regular countermeasure.","cn":"矫正：正因为倾斜有规律，才可以用有规律的矫正手段对抗。"}]},"affixes":{"intro":{"en":"The phrase is half Latin and half French, and the two halves come from very different histories, which is worth keeping apart.","cn":"这个短语一半来自拉丁语、一半来自法语，两半的历史差别很大，值得分开记。"},"latinIntro":{"en":"The Latin half brings cognition, cognitive and recognize; the French half brings bias, biased and the verb to bias.","cn":"拉丁那一半带来 cognition、cognitive 与 recognize；法语那一半带来 bias、biased 以及动词 bias。"},"items":[{"word":"cognoscere","structure":"cognoscere (Latin verb, third conjugation)","meaning":"to come to know","meaningCN":"逐渐认识","example":"The root supplies the mental half of the phrase.","exampleCN":"这个词根提供短语中「心智」的那一半。"},{"word":"cognitio","structure":"cognoscere + -io","meaning":"knowledge, a knowing","meaningCN":"认识；知识","example":"The noun became the English cognition.","exampleCN":"这个名词成为英语的 cognition。"},{"word":"-ive","structure":"-ivus (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes the adjective of mental processing.","exampleCN":"这个后缀造出指心理加工的形容词。"},{"word":"cognitive","structure":"cognitio + -ive","meaning":"relating to mental processing","meaningCN":"与心理加工有关的","example":"The adjective says where the deviation sits.","exampleCN":"这个形容词说明偏移发生在哪里。"},{"word":"biais","structure":"biais (Old French noun, 'slant')","meaning":"a slant","meaningCN":"斜面；倾斜","example":"The French noun supplied the leaning half.","exampleCN":"这个法语名词提供「倾斜」那一半。"},{"word":"bias","structure":"biais (Old French) into English","meaning":"a leaning, a slant","meaningCN":"偏向；倾斜","example":"English extended the slant of a line to a slant of the mind.","exampleCN":"英语把线条的斜延伸到心智的斜。"},{"word":"-ed","structure":"-ed (English participial suffix)","meaning":"having","meaningCN":"具有……的","example":"The participle builds the adjective for something that has a lean.","exampleCN":"分词造出表示「带有倾斜」的形容词。"},{"word":"biased","structure":"bias + -ed","meaning":"having a lean","meaningCN":"带偏向的","example":"The adjective describes data or people that lean.","exampleCN":"这个形容词形容倾斜的数据或人。"},{"word":"un-","structure":"un- (English negative prefix)","meaning":"not","meaningCN":"不","example":"The negative form names the ideal for a study or a model.","exampleCN":"否定形式指研究或模型所追求的理想状态。"},{"word":"de-","structure":"de- (Latin prefix, 'away from')","meaning":"removing","meaningCN":"去掉","example":"The prefix builds the verb for taking a lean away.","exampleCN":"这个前缀造出「把倾斜去掉」的动词。"}],"latinEntries":[{"word":"cognoscere","structure":"cognoscere, cognovi, cognitum (verb, third conjugation)","meaning":"to get to know","meaningCN":"认识；得知"},{"word":"cognitio","structure":"cognitio, cognitionis (f., third declension)","meaning":"knowledge, a knowing","meaningCN":"认识；知识"},{"word":"cognitus","structure":"cognitus, -a, -um (past participle)","meaning":"known","meaningCN":"已知的"}]}},{"word":"prejudice","ipa_uk":"/ˈpredʒudɪs/","ipa_us":"/ˈpredʒudɪs/","definition_zh":"偏见；成见；使有偏见；损害","definition_en":"a preconceived opinion formed without adequate grounds, or to bias someone or to harm a right or interest","core_image":"一叠贴好标签的档案袋，还没打开就已经判定了内容","scene":"招聘会上，一名主管看到简历上的外地学校名称，就把材料放到一边。The trainer calls that reflex prejudice rather than a hiring rule.","sceneCN":"这里 prejudice 指「未经充分了解就形成的成见」（第 1 个义项：预先形成、缺乏依据的看法）；句意为培训师把那种反射式的反应称为偏见，而非招聘规则。场景要素：简历堆、标签、被推到一边的文件夹。","pos":[{"tag":"n.","zh":"偏见；成见；（法律）损害"},{"tag":"vt.","zh":"使有偏见；损害（权利、机会）"}],"collocations":[{"phrase":"racial prejudice","zh":"种族偏见"},{"phrase":"prejudice against","zh":"对……的偏见"},{"phrase":"overcome prejudice","zh":"克服偏见"},{"phrase":"without prejudice","zh":"不影响法律权利地；不损及权益"},{"phrase":"dismiss with prejudice","zh":"以终局方式驳回"},{"phrase":"to the prejudice of","zh":"损害……的利益"}],"forms":[{"label":"复数","form":"prejudices"},{"label":"动词三单","form":"prejudices"},{"label":"过去式","form":"prejudiced"},{"label":"过去分词","form":"prejudiced"},{"label":"现在分词","form":"prejudicing"},{"label":"形容词（抱偏见的）","form":"prejudiced"},{"label":"形容词（有害的）","form":"prejudicial"}],"derivatives":[{"word":"prejudiced","pos":"adj.","zh":"由 prejudice 加过去分词词尾构成，指自己抱有偏见的"},{"word":"prejudicial","pos":"adj.","zh":"由 prejudice 加形容词后缀构成，指会造成损害的"},{"word":"unprejudiced","pos":"adj.","zh":"由否定前缀加 prejudiced 构成，指不带偏见的"},{"word":"prejudge","pos":"v.","zh":"由表「在前」的前缀加 judge 构成，指事先就作出判断"}],"senses":[{"no":"01","title":"An opinion formed without adequate grounds","titleCN":"缺乏充分依据的看法","definition":"a judgment about someone or something made before the facts are known","definitionCN":"在了解事实之前就对某人某物作出的判断","example":"Her prejudice about the neighbourhood faded after a single afternoon there.","exampleCN":"她对那个街区的成见，在待了一个下午之后就淡了。","why":"The Latin noun means a judgment made beforehand, so the word records not hatred but the timing of the judgment.","whyCN":"那个拉丁名词意为「事先作出的判断」，因此这个词记录的不是仇恨，而是判断的时点。"},{"no":"02","title":"Hostility toward a group","titleCN":"对某个群体的敌意","definition":"a hostile or unfair orientation toward people because of the group they belong to","definitionCN":"因某人所属的群体而对其持有的敌意或不公取向","example":"The report documented prejudice against migrant workers in hiring.","exampleCN":"报告记录了招聘中对外来务工人员的偏见。","why":"A pre-judgment aimed at a whole category turns into hostility, and this is the sense most people mean today.","whyCN":"针对整个类别的预先判断会变成敌意，这也是今天多数人所指的义项。"},{"no":"03","title":"A favourable pre-judgment","titleCN":"偏于有利的预先判断","definition":"a pre-judgment that can lean in someone's favour as well as against them","definitionCN":"一种可能有利于某人、也可能不利于某人的预先判断","example":"His prejudice in favour of old buildings made him miss the mould in the basement.","exampleCN":"他对老房子的偏爱让他忽略了地下室的霉斑。","why":"English keeps the neutral frame, so the word can describe a favourable lean, which is why 'prejudice in favour of' still occurs.","whyCN":"英语保留了中性框架，因此这个词可以形容有利的倾斜，「偏爱」的说法至今仍在用。"},{"no":"04","title":"To bias someone's mind","titleCN":"使某人的判断带上偏向","definition":"to cause someone to form an opinion in advance of the evidence","definitionCN":"使某人在证据出现之前就形成看法","example":"The leaked summary prejudiced the panel before it heard a witness.","exampleCN":"提前流出的摘要让评审团在听证之前就有了倾向。","why":"The verb turns the state into an act: someone or something does the pre-judging to another mind.","whyCN":"动词把这个状态变成动作：某人或某物把预先判断做进了另一个头脑。"},{"no":"05","title":"To harm a right or interest","titleCN":"损害某项权利或利益","definition":"to damage or impair a legal right, a claim or a chance","definitionCN":"损害或削弱某项法律权利、主张或机会","example":"The delay prejudiced the tenant's claim to compensation.","exampleCN":"这拖延损害了租客获得补偿的主张。","why":"Law generalised the word from a wrong opinion to any action that puts a right at a disadvantage.","whyCN":"法律把这个词从「错误的看法」推广到任何使权利处于不利地位的行为。"},{"no":"06","title":"A dismissal that bars refiling","titleCN":"不得再诉的驳回","definition":"in procedure, a final dismissal of a claim that prevents it being brought again","definitionCN":"程序上对某项主张的终局驳回，使其不得再次提出","example":"The case was dismissed with prejudice after the plaintiff failed to appear.","exampleCN":"原告未出庭后，案件以终局方式驳回。","why":"A final ruling 'prejudges' the matter for good, which is why the old word survives in this narrow procedural formula.","whyCN":"终局裁决等于把这件事实地预先判定了，因此这个古老的词在这条狭窄的程序套语里留存。"},{"no":"07","title":"A social attitude distinct from behaviour","titleCN":"与社会行为相区别的态度","definition":"in social psychology, an attitude toward a group, studied separately from discriminatory acts","definitionCN":"社会心理学中，对某群体的态度，与歧视行为分开研究","example":"Prejudice and discrimination are measured as attitude and action, not as one thing.","exampleCN":"偏见与歧视被分别测作态度与行为，而不是同一件事。","why":"The discipline needed to split the inner leaning from the outward act, so the word was fixed to the inner side.","whyCN":"这门学科需要把内心的倾斜与外显的行为分开，于是把这个词固定在内心一侧。"},{"no":"08","title":"To the detriment of someone","titleCN":"使某人处于不利","definition":"in the fixed phrase, to the disadvantage or injury of a person or interest","definitionCN":"在固定说法中，指使某人或某种利益处于不利或受损","example":"The new route was chosen to the prejudice of the fishing village.","exampleCN":"新路线被选中，代价是渔村受损。","why":"The prepositional phrase keeps the harm sense alive outside courtrooms, where it means damage in plain speech.","whyCN":"这个介词短语把损害义留在法庭之外，日常言谈中它就指造成的损失。"}],"etymology":{"intro":{"en":"Prejudice comes through Old French from Latin praejudicium 'a judgment beforehand', built from a prefix meaning 'before' and the noun for judgment. Dates are approximate.","cn":"prejudice 经古法语来自拉丁语 praejudicium「事先的判断」，由表「在前」的前缀与表「判断」的名词构成。年代均为约数。"},"items":[{"era":"LATIN PRAE-","en":"The prefix meant 'before, in front', and it fixes the timing of the judgment in the word itself.","cn":"这个前缀意为「在前、在之前」，它把判断的时点固定在词里。"},{"era":"LATIN JUDICIUM","en":"Judicium meant a declaring or a ruling, built on judex 'judge', itself from law plus the verb for declaring.","cn":"judicium 意为宣告或裁断，建立在 judex「法官」之上，而后者又由「法律」与表「宣告」的动词构成。"},{"era":"LATIN PRAEJUDICIUM","en":"The compound named a preliminary ruling and, in ordinary use, an opinion formed before the case was heard.","cn":"这个复合名词指初步裁决，在日常用法中也指在听取案件之前就形成的看法。"},{"era":"OLD FRENCH","en":"Old French prejudice carried both the legal and the mental senses into English in the fourteenth century.","cn":"古法语在十四世纪把这个词的法律义与心智义一并带入英语。"},{"era":"MODERN SOCIAL SENSE","en":"From the nineteenth century the word narrowed toward hostility between groups, and psychology later separated it from discrimination.","cn":"从十九世纪起，这个词向群体间的敌意收窄，心理学后来把它与歧视区分开。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first date and deeper root): the earliest English use is recorded only approximately, and the pre-Latin origin of the word for law is unsettled, so any older form offered for it is a reconstruction.","cn":"来源不确定（首见年代与更深词根）：最早的英语用例只有约略记载；那个表「法律」的词在拉丁语之前的来源亦无定论，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root words and adjectives that are routinely mixed up with the noun; group two holds near neighbours for a group-directed attitude.","cn":"第一组是同根词，以及常与本名词弄混的形容词；第二组是表示针对群体的态度的近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"prejudiced","ipa":"/prɪˈdʒudɪst/","tag":"the adjective for a person","definition":"Describes a person who holds a prejudice; the noun names the prejudice itself, and the two are not interchangeable.","definitionCN":"形容人抱有偏见；名词指偏见本身，两者不能互换。"},{"word":"prejudicial","ipa":"/prɪˌdʒuːˈdɪʃl/","tag":"causing harm","definition":"Means likely to cause damage to a right or a case; it does not mean full of prejudice.","definitionCN":"意为很可能损害某项权利或案件，并不表示「充满偏见」。"},{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"the neutral relative","definition":"A ruling or a formed opinion without the prefix, so it says nothing about whether the opinion came too early.","definitionCN":"不带该前缀的裁决或看法，因此并不表明这个看法是否来得太早。"},{"word":"prejudge","ipa":"/priːˈdʒʌdʒ/","tag":"the verb built with the same prefix","definition":"To judge before hearing the evidence; it is the act that produces a prejudice.","definitionCN":"指在听取证据之前就判断，正是产生偏见的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bias","ipa":"/baɪəs/","tag":"a leaning","definition":"Any leaning, often unconscious and sometimes harmless; prejudice implies an unfair or unfounded leaning.","definitionCN":"泛指任何偏向，往往无意识且有时无害；prejudice 暗示不公或缺乏依据。"},{"word":"discrimination","ipa":"/dɪˌskrɪmɪˈneɪʃn/","tag":"the act, not the attitude","definition":"Treating people differently in practice; psychology keeps it separate from the inner attitude that prejudice names.","definitionCN":"指实际行为上的区别对待；心理学把它与 prejudice 所指的内心的态度分开。"},{"word":"stereotype","ipa":"/ˈsteriətaɪp/","tag":"the picture, not the stance","definition":"A simplified image of a group; a stereotype can supply the content of a prejudice but is not itself hostility.","definitionCN":"指对某群体的简化形象；它可为偏见提供内容，但本身不是敌意。"},{"word":"bigotry","ipa":"/ˈbɪɡətri/","tag":"hateful intolerance","definition":"Stubborn intolerance of another group, stronger and more openly hostile than prejudice.","definitionCN":"指对另一群体的顽固不容忍，比 prejudice 更强、更公开敌意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real judging root, the real family and the real legal phrases.","cn":"正常联想：真实的前缀、表「判断」的词根、真实的词族与真实的法律说法。"},"normal":[{"en":"The prefix means before and the base means judgment, so prejudice is a judgment that arrives before the facts.","cn":"前缀意为「在前」，基底意为「判断」，因此偏见就是赶在事实之前到达的判断。"},{"en":"The family runs judge, judgment, judicial, prejudice, prejudiced, prejudicial, prejudge.","cn":"同族词包括 judge、judgment、judicial、prejudice、prejudiced、prejudicial、prejudge。"},{"en":"Legal phrases preserve the harm sense: without prejudice, dismissed with prejudice, to the prejudice of.","cn":"法律说法保存了损害义：不损及权益、以终局方式驳回、损害……的利益。"},{"en":"The adjective prejudiced describes a person, while prejudicial describes something harmful.","cn":"形容词 prejudiced 形容人，而 prejudicial 形容有害之物。"},{"en":"Social psychology separates the attitude from the act, calling them prejudice and discrimination.","cn":"社会心理学把态度与行为分开，分别称为偏见与歧视。"}],"abstract":[{"en":"Picture a folder labelled before it has been opened.","cn":"想象一个还没打开就已经贴好标签的文件夹。"},{"en":"Picture a lens ground before the optician has measured the eye.","cn":"想象磨好的镜片，而验光师还没量过眼睛。"},{"en":"Picture a gavel that falls before the witness is sworn.","cn":"想象法槌在证人宣誓之前就落下了。"}]},"examples":[{"en":"The campaign measured prejudice through questions about hiring and housing.","cn":"这场运动通过招聘与住房方面的问题来测量偏见。"},{"en":"Reading one bad review prejudiced him against the whole school of thought.","cn":"读了一篇差评，就让他对整个学派有了成见。"},{"en":"The ruling was issued without prejudice to either party's further claims.","cn":"该裁定不损及双方后续的主张。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「pre 在前 + judge 判断」——还没看清就先判了，就是偏见","word":"prejudice"},"root":"拉丁 praejudicium「事先的判断」由意为「在前」的前缀加 judicium（裁断，出自 judex「法官」= jus「法律」+ dicere「宣告」）；jus 更深来源不确定。英语 prejudice。","sensesIntro":{"en":"Eight senses follow one early judgment: a verdict is reached before the evidence arrives. It is read as an unfounded opinion, as hostility toward a group, as a favourable lean, as the act of biasing a mind, as harm to a right, as a final dismissal, as an attitude studied apart from behaviour, and as a plain phrase for damage.","cn":"八个义项沿同一个「提前的判断」展开：证据未到，裁决先落。它依次被读作缺乏依据的看法、对群体的敌意、有利的倾斜、使他人带上偏向的行为、对权利的损害、终局驳回、与行为分开研究的态度，以及日常说法中的损失。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stack of folders already labelled before any is opened.","cn":"核心意象：一叠档案袋还没打开，标签就已经贴好。"},"chain":["JUDGE IN ADVANCE","FIX A LABEL","TURN HOSTILE","IMPAIR A RIGHT","FINAL DISMISSAL","BLOCK THE VIEW"],"branches":[{"senses":"01 · 03","en":"THE PRE-JUDGMENT: an unfounded opinion and a favourable one share the same timing, which is the real subject of the word.","cn":"预先的判断：缺乏依据的看法与有利的看法共享同一个时点，时点才是这个词真正的主题。"},{"senses":"02","en":"FROM OPINION TO ENMITY: when the early judgment is aimed at a whole group, it hardens into hostility.","cn":"从看法到敌意：当提前的判断对准整个群体，它就硬化为敌意。"},{"senses":"04","en":"DOING IT TO A MIND: the verb marks the moment one person's lean is planted in another.","cn":"做进别人脑中：动词标出某人的倾斜被栽进另一个人头脑的那一刻。"},{"senses":"05 · 08","en":"HARM: legal impairment and the everyday phrase for damage both turn a wrong opinion into a lost right.","cn":"损害：法律上的削弱与日常说到损失的说法，都把错误的看法变成失去的权利。"},{"senses":"06 · 07","en":"FIXED IN PLACE: a dismissal that bars refiling and an attitude studied apart from action both keep the first judgment from moving.","cn":"固定原位：不得再诉的驳回与与行为分开研究的态度，都让最初的判断无法移动。"}]},"affixes":{"intro":{"en":"Prejudice is a Latin prefix plus the same judging noun that builds judge and judgment, so the whole legal family reads together.","cn":"prejudice 是一个拉丁前缀加那个构成 judge 与 judgment 的「判断」名词，因此整个法律词族可以一起读。"},"latinIntro":{"en":"The judging noun gives judge, judgment, judicial and judicious; the prefix meaning 'before' gives predict, prevent and prepare.","cn":"那个「判断」名词衍生 judge、judgment、judicial 与 judicious；表「在前」的前缀衍生 predict、prevent 与 prepare。"},"items":[{"word":"prae-","structure":"prae- (Latin prefix, 'before, in front')","meaning":"before","meaningCN":"在前","example":"The prefix fixes the timing that defines the word.","exampleCN":"这个前缀固定了定义这个词的时点。"},{"word":"judicium","structure":"judicium (Latin noun)","meaning":"a ruling, a judgment","meaningCN":"裁断；判断","example":"The base supplies both the legal and the mental side.","exampleCN":"基底同时提供法律与心智两面。"},{"word":"praejudicium","structure":"prae- + judicium","meaning":"a judgment beforehand","meaningCN":"事先的判断","example":"The Latin compound already had both a legal and a general use.","exampleCN":"这个拉丁复合词早已兼有法律与一般用法。"},{"word":"prejudice","structure":"praejudicium through French","meaning":"a preconceived opinion","meaningCN":"预先形成的看法","example":"English kept the legal and the mental senses side by side.","exampleCN":"英语让法律义与心智义并排留存。"},{"word":"prejudiced","structure":"prejudice + -ed","meaning":"holding a prejudice","meaningCN":"抱有偏见的","example":"The participle form describes the person, not the opinion.","exampleCN":"分词形式形容人，而不是那个看法。"},{"word":"-ial","structure":"-ialis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"A different suffix produces the sense of causing harm.","exampleCN":"换一个后缀就产生「造成损害」的意思。"},{"word":"prejudicial","structure":"prejudice + -ial","meaning":"causing harm","meaningCN":"有害的；损及权利的","example":"The adjective is common in legal and formal writing.","exampleCN":"这个形容词常见于法律与正式写作。"},{"word":"un-","structure":"un- (English negative prefix)","meaning":"not","meaningCN":"不","example":"The negative form describes a mind without the lean.","exampleCN":"否定形式形容不带这种倾斜的头脑。"},{"word":"prejudge","structure":"prae- + judge","meaning":"to judge in advance","meaningCN":"预先判断","example":"The verb names the act that produces the state.","exampleCN":"这个动词指产生该状态的行为。"}],"latinEntries":[{"word":"judicium","structure":"judicium, judicii (n., second declension)","meaning":"a ruling, a judgment","meaningCN":"裁断；判断"},{"word":"judex","structure":"judex, judicis (m., third declension)","meaning":"a judge","meaningCN":"法官"},{"word":"praejudicium","structure":"praejudicium, praejudicii (n., second declension)","meaning":"a previous judgment","meaningCN":"事先的判断"},{"word":"judicare","structure":"judicare, judicavi, judicatum (verb, first conjugation)","meaning":"to judge","meaningCN":"评判；裁断"}]}},{"word":"sociology","ipa_uk":"/ˌsəʊsiˈɒlədʒi/","ipa_us":"/ˌsoʊsiˈɑːlədʒi/","definition_zh":"社会学；研究社会与社会关系的学科","definition_en":"the systematic study of society, social relations, institutions and group behaviour","core_image":"一张城市剖面图，把家庭、学校与市场画成彼此相连的房间","scene":"社区中心里，研究者连续三个月记录邻里如何互相帮忙。Her sociology project compares two housing estates.","sceneCN":"这里 sociology 指「研究社会与社会关系的学科」（第 1 个义项：对社会的系统研究）；句意为她的社会学研究比较两个住宅区。场景要素：记录表、社区公告栏、两片住宅楼。","pos":[{"tag":"n.","zh":"社会学；社会学学科"}],"collocations":[{"phrase":"the sociology of education","zh":"教育社会学"},{"phrase":"applied sociology","zh":"应用社会学"},{"phrase":"a degree in sociology","zh":"社会学学位"},{"phrase":"comparative sociology","zh":"比较社会学"},{"phrase":"urban sociology","zh":"城市社会学"},{"phrase":"the sociology department","zh":"社会学系"}],"forms":[{"label":"形容词","form":"sociological"},{"label":"副词","form":"sociologically"},{"label":"从业者","form":"sociologist"},{"label":"复数（罕用）","form":"sociologies"}],"derivatives":[{"word":"sociologist","pos":"n.","zh":"由 sociology 加表人后缀构成，指从事社会学研究的人"},{"word":"sociological","pos":"adj.","zh":"由 sociology 加形容词后缀构成，指与社会学有关的"},{"word":"social","pos":"adj.","zh":"与社会学同出拉丁语「同伴」一词，指社会的、社交的，词义更宽"},{"word":"society","pos":"n.","zh":"同根名词，指社会或社团，是社会学研究的对象本身"},{"word":"sociable","pos":"adj.","zh":"同根形容词，指好交际的，语义已转向个人性格"}],"senses":[{"no":"01","title":"The systematic study of society","titleCN":"对社会的系统研究","definition":"the academic study of how societies are organised, how groups behave and how institutions persist","definitionCN":"研究社会如何组织、群体如何行动、制度如何延续的学科","example":"Sociology began by asking how industrial cities held together at all.","exampleCN":"社会学最初追问的是工业城市究竟靠什么维持在一起。","why":"The second half of the word means 'study of', so the coinage literally promised a science of the social, and that promise is the first sense.","whyCN":"这个词的后半意为「……之学」，因此这个造词字面上承诺了一门关于社会的科学，这个承诺就是第一个义项。"},{"no":"02","title":"The discipline as an institution","titleCN":"作为建制的一门学科","definition":"the department, degree and professional field rather than the subject matter","definitionCN":"指院系、学位与职业领域，而非研究对象","example":"The sociology department hired two specialists in migration.","exampleCN":"社会学系聘用了两位移民研究专家。","why":"A field of study becomes an institution with budgets and hiring, and the word then names the institution as much as the inquiry.","whyCN":"一个研究领域会变成有预算、有招聘的建制，这个词于是既指探究，也指建制。"},{"no":"03","title":"A body of theory about social structure","titleCN":"关于社会结构的理论体系","definition":"a particular theoretical tradition that explains how social structures shape action","definitionCN":"解释社会结构如何塑造行动的一种理论传统","example":"Classical sociology treated class as a structure that outlives its members.","exampleCN":"古典社会学把阶级视为比其成员活得更久的结构。","why":"Once a discipline accumulates explanations, its name also stands for those explanations taken together.","whyCN":"一门学科积累了各种解释之后，它的名字也代表这些解释的总体。"},{"no":"04","title":"The methods of the field","titleCN":"该领域的研究方法","definition":"the surveys, interviews, observations and statistical tools used to study social life","definitionCN":"研究社会生活所用的调查、访谈、观察与统计工具","example":"The course teaches sociology through fieldwork before it teaches theory.","exampleCN":"这门课先通过实地调查教社会学，再教理论。","why":"Methods are what make a study systematic rather than merely reflective, so they become part of what the name covers.","whyCN":"方法使研究成为系统的而非仅只反思性的，因此方法也进入这个名字所覆盖的范围。"},{"no":"05","title":"Applied sociology","titleCN":"应用社会学","definition":"the use of sociological research to design policy, services or organisational practice","definitionCN":"运用社会学研究来设计政策、服务或组织实践","example":"Applied sociology shaped the city's plan for evening clinics.","exampleCN":"应用社会学影响了该市夜间诊所的规划。","why":"When findings leave the seminar room for a budget meeting, the discipline acquires an applied face.","whyCN":"当研究结论从研讨室走进预算会议，这门学科就多了一张应用的面孔。"},{"no":"06","title":"A specialised subfield","titleCN":"一个专门的分支","definition":"a named branch devoted to one institution or domain, such as education or medicine","definitionCN":"以某一制度或领域为对象的命名分支，如教育或医疗","example":"The sociology of medicine studies how diagnoses travel between wards.","exampleCN":"医学社会学研究诊断如何在病房间流转。","why":"Any institution can be studied sociologically, and each such study gets a name built on the same word.","whyCN":"任何制度都可以被社会学地研究，每一类研究都会用同一个词造出一个名称。"},{"no":"07","title":"Loose social analysis outside the academy","titleCN":"学院之外的宽泛社会分析","definition":"informal commentary that explains events by social forces rather than individual motives","definitionCN":"以社会力量而非个人动机来解释事件的非正式评论","example":"His essay was sociology rather than journalism, though he never cited a study.","exampleCN":"他那篇文章算社会分析而非新闻，尽管他从未引用过研究。","why":"A name for a discipline is also borrowed for the kind of thinking it made ordinary, even when no method is used.","whyCN":"学科之名也会被借去指它使之变得平常的那种思考，即便没有使用任何方法。"},{"no":"08","title":"The school subject as taught","titleCN":"作为课程的学科","definition":"the subject taught at school or in an introductory course, with its own syllabus","definitionCN":"学校或导论课中按大纲讲授的科目","example":"Sociology is now a compulsory subject in the second year.","exampleCN":"社会学如今是二年级的必修科目。","why":"Teaching requires a syllabus, and a syllabus turns a discipline into a subject with examinations.","whyCN":"教学需要大纲，而大纲把学科变成有考试的科目。"}],"etymology":{"intro":{"en":"Sociology is a modern compound of a Latin word for companion and a Greek element meaning 'study of'. It is usually attributed to the French thinker Auguste Comte. Dates are approximate.","cn":"sociology 是一个现代复合词，由拉丁语中表「同伴」的词与一个意为「……之学」的希腊成分构成。它一般认为是法国思想家孔德所造。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant 'companion, ally'. Its deeper origin is not established; the link sometimes suggested to the verb for following is a hypothesis.","cn":"socius 意为「同伴、盟友」。其更早来源未得到证明；有人提出它与表「跟随」的动词有关，那只是假说。"},{"era":"LATIN SOCIETAS","en":"The noun societas named an association or a partnership, and it is the direct ancestor of the English word society.","cn":"名词 societas 指联合或合伙，是英语 society 的直接前身。"},{"era":"GREEK -LOGIA","en":"The Greek element meant 'the study or account of', and it had already built geology, biology and theology.","cn":"这个希腊成分意为「……之学、……的论述」，此前已造出 geology、biology 与 theology。"},{"era":"MODERN COINAGE","en":"The compound is generally attributed to Auguste Comte in the eighteen thirties, who wanted a science of society on the model of the natural sciences.","cn":"这个复合词一般认为是孔德在十九世纪三十年代所造，他想要一门以自然科学为模型的社会科学。"},{"era":"INSTITUTIONAL SPREAD","en":"Departments, journals and degrees followed in the late nineteenth and early twentieth centuries, giving the word its institutional sense.","cn":"十九世纪后期至二十世纪初，院系、期刊与学位相继出现，使这个词获得建制义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (exact first printed use and the origin of the companion word): the precise earliest citation is not settled, and the pre-Latin origin of the word for companion is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（确切的最早书证与「同伴」一词的来源）：最早用例尚无定论；那个表「同伴」的词在拉丁语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root words whose meaning has drifted; group two holds neighbouring disciplines and general terms.","cn":"第一组是同根词，词义各有漂移；第二组是相邻学科与一般说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃl/","tag":"the adjective, much wider","definition":"Relating to society or to interaction in general; sociology is the name of a discipline, not a description of anything social.","definitionCN":"泛指与社会的或互动有关的；sociology 是一门学科之名，并不描述任何社会性事物。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"the object of study","definition":"The collectivity itself, or an association; the discipline studies it but is not it.","definitionCN":"指社会集合本身或社团；学科研究它，但并不等于它。"},{"word":"sociable","ipa":"/ˈsəʊʃiəbl/","tag":"friendly in company","definition":"Describes a person who enjoys company; the root drifted from partnership to a personal trait.","definitionCN":"形容喜欢与人相处的人；词根从「合伙」漂移到个人性格。"},{"word":"sociologist","ipa":"/ˌsəʊsiˈɒlədʒɪst/","tag":"the practitioner","definition":"The person who practices the discipline; the discipline is the field, not the practitioner.","definitionCN":"指从事这门学科的人；学科是领域，不是从业者。"}]},{"heading":"NEAR MEANING","entries":[{"word":"anthropology","ipa":"/ˌænθrəˈpɒlədʒi/","tag":"study of people broadly","definition":"The study of human societies and cultures, often through long fieldwork; it overlaps with sociology but leans toward culture and small communities.","definitionCN":"指对人类社群与文化的研究，常用长期田野调查；与社会学重叠，但偏向文化与小型社群。"},{"word":"social psychology","ipa":"/ˌsəʊʃl saɪˈkɒlədʒi/","tag":"the individual in groups","definition":"The study of how individuals think and act in social settings; sociology begins with structures rather than individuals.","definitionCN":"研究个体在群体情境中如何思考与行动；社会学则从结构出发。"},{"word":"demography","ipa":"/dɪˈmɒɡrəfi/","tag":"the counting of populations","definition":"The statistical study of births, deaths and migration; it supplies sociology with data rather than theory.","definitionCN":"指对出生、死亡与迁移的统计研究，为社会学家提供数据而非理论。"},{"word":"social science","ipa":"/ˌsəʊʃl ˈsaɪəns/","tag":"the umbrella term","definition":"The whole family of disciplines, including sociology, economics and political science.","definitionCN":"指包括社会学、经济学与政治学在内的整个学科群。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves, the real coinage story and the real professional phrases.","cn":"正常联想：两个真实的构成部分、真实的造词来历与真实的专业搭配。"},"normal":[{"en":"The first half means companion and the second means study of, so the word reads as the study of what people form together.","cn":"前半意为「同伴」，后半意为「……之学」，因此这个词读作「对人们共同结成之物的研究」。"},{"en":"The family runs society, social, sociable, sociologist, sociological.","cn":"同族词包括 society、social、sociable、sociologist、sociological。"},{"en":"The coinage is generally attributed to Auguste Comte, who modelled it on the natural sciences.","cn":"这个造词一般认为是孔德所为，他以自然科学为模型。"},{"en":"Professional phrases mark the institution: a degree in sociology, the sociology department, applied sociology.","cn":"专业搭配标出建制：社会学学位、社会学系、应用社会学。"},{"en":"The same ending appears in biology, geology and theology, all names of studies.","cn":"同一个词尾还出现在 biology、geology 与 theology，都是学科之名。"}],"abstract":[{"en":"Picture a cutaway of a city with every room joined by pipes.","cn":"想象一张城市剖面图，每个房间都由管道相连。"},{"en":"Picture a map on which a family and a school sit at the same intersection.","cn":"想象一张地图，家庭与学校坐在同一个路口。"},{"en":"Picture a crowd treated as one body with a pulse.","cn":"想象把人群当作一个有一根脉搏的身体。"}]},"examples":[{"en":"Sociology asks why two identical neighbourhoods develop different fortunes.","cn":"社会学追问：两个一模一样的街区为何命运不同。"},{"en":"She read sociology before moving into urban planning.","cn":"她在转入城市规划之前读的是社会学。"},{"en":"The sociology of science studies how laboratories agree on a fact.","cn":"科学社会学研究实验室如何就一个事实达成一致。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「soci（同伴）+ ology（学问）」——研究人们如何结成同伴的学问，就是社会学","word":"sociology"},"root":"拉丁 socius「同伴」+ 希腊语「……之学」；一般认为是孔德于十九世纪三十年代所造；socius 更深来源不确定。英语 sociology。","sensesIntro":{"en":"Eight senses follow one decision to study society as a thing: the inquiry, the institution that houses it, the theories it accumulates, the methods it uses, its applied face, its named subfields, its loose everyday imitation and its syllabus.","cn":"八个义项沿同一个决定展开：把社会当作一个可研究的对象。它依次是这项探究、承载它的建制、积累的理论、使用的方法、应用的面孔、命名的分支、日常的宽泛模仿，以及课程大纲。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cutaway drawing of a city where every room is joined to the next by pipes.","cn":"核心意象：一张城市剖面图，每个房间都与下一个由管道相连。"},"chain":["SOCIETY","RELATIONS","STRUCTURE","METHOD","POLICY","SUBJECT TAUGHT"],"branches":[{"senses":"01 · 03","en":"INQUIRY AND THEORY: the study of society and the accumulated explanations of its structure are the same project at two depths.","cn":"探究与理论：对社会的系统研究与关于其结构积累的解释，是同一项工程的两个深度。"},{"senses":"02 · 08","en":"THE INSTITUTION AND THE CLASSROOM: a department with a budget and a subject with a syllabus are the discipline made durable.","cn":"建制与课堂：有预算的院系与有大纲的科目，是这门学科被做成持久之物的两种形态。"},{"senses":"04 · 06","en":"METHOD AND SUBFIELD: tools produce results, and results organise themselves into named branches.","cn":"方法与分支：工具产出结果，结果又自行组织成命名分支。"},{"senses":"05","en":"APPLIED FACE: findings leave the seminar room and enter a budget meeting.","cn":"应用的面孔：研究结论离开研讨室，进入预算会议。"},{"senses":"07","en":"EVERYDAY IMITATION: the discipline's way of thinking is borrowed even where no method is used.","cn":"日常模仿：即便不动用任何方法，人们也会借走这门学科的思考方式。"}]},"affixes":{"intro":{"en":"Sociology is one Latin noun and one Greek element, a combination typical of nineteenth-century science names.","cn":"sociology 是一个拉丁名词加一个希腊成分，这是十九世纪学科名称的典型组合。"},"latinIntro":{"en":"Latin socius gives society, social, sociable and associate; the Greek element recurs in biology, geology and theology.","cn":"拉丁 socius 衍生 society、social、sociable 与 associate；那个希腊成分还出现在 biology、geology 与 theology 中。"},"items":[{"word":"socius","structure":"socius, -i (Latin noun and adjective)","meaning":"companion, ally","meaningCN":"同伴；盟友","example":"The root supplies the idea of people joined together.","exampleCN":"这个词根提供「人们结成一体」的意思。"},{"word":"societas","structure":"socius + -tas (Latin noun suffix)","meaning":"association, partnership","meaningCN":"联合；合伙","example":"The Latin noun is the direct ancestor of society.","exampleCN":"这个拉丁名词是 society 的直接前身。"},{"word":"-logia","structure":"-logia (Greek element, 'study of')","meaning":"the study of","meaningCN":"……之学","example":"The element was already standard in science names before this coinage.","exampleCN":"在本次造词之前，这个成分已是学科名称的惯用部件。"},{"word":"sociology","structure":"socius + -logia","meaning":"the study of society","meaningCN":"社会学","example":"The compound promises a science of the social, and the promise is part of the meaning.","exampleCN":"这个复合词承诺了一门关于社会的科学，这份承诺本身也构成词义。"},{"word":"-ist","structure":"-ista (Greek and Latin agent suffix)","meaning":"one who practices","meaningCN":"从事者","example":"The suffix builds the name of the practitioner.","exampleCN":"这个后缀造出从业者的名称。"},{"word":"sociologist","structure":"sociology + -ist","meaning":"a practitioner of sociology","meaningCN":"社会学研究者","example":"The person noun is far more common than a plural of the discipline name.","exampleCN":"指人的名词远比这个学科名的复数常用。"},{"word":"-ical","structure":"-ical (Greek and Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"The adjective suffix is shared with dozens of discipline names.","exampleCN":"这个形容词后缀与许多学科名共用。"},{"word":"sociological","structure":"sociology + -ical","meaning":"relating to sociology","meaningCN":"与社会学有关的","example":"The adjective also describes an approach that social forces explain.","exampleCN":"这个形容词也形容以社会力量作解释的取向。"},{"word":"social","structure":"socius + -alis","meaning":"relating to companions or society","meaningCN":"与同伴或社会有关的","example":"The shorter adjective is far wider in use.","exampleCN":"较短的形容词用法宽广得多。"},{"word":"associate","structure":"ad- 'to' + socius","meaning":"to join as a companion","meaningCN":"结为同伴","example":"The prefixed verb shows how productive the root is.","exampleCN":"加前缀的动词显示出这个词根的生产力。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, partnership","meaningCN":"联合；合伙"},{"word":"sociare","structure":"sociare, sociavi, sociatum (verb, first conjugation)","meaning":"to join, unite","meaningCN":"联合；结合"}]}},{"word":"sociological","ipa_uk":"/ˌsəʊsiəˈlɒdʒɪkl/","ipa_us":"/ˌsoʊsiəˈlɑːdʒɪkl/","definition_zh":"社会学的；从社会结构角度解释的","definition_en":"relating to sociology, or explaining behaviour by social structures rather than individual choices","core_image":"把一间屋子的墙拆掉，露出与整条街相连的水管","scene":"一份关于通勤时间的报告不再归咎于个人选择，而是追问住房与地铁线路的布局。The report offers a sociological explanation of lateness.","sceneCN":"这里 sociological 指「从社会结构出发来解释的」（第 2 个义项：以社会结构而非个人来解释）；句意为这份报告对迟到给出了社会学解释。场景要素：通勤路线图、住房分布、报告封面。","pos":[{"tag":"adj.","zh":"社会学的；从社会角度解释的"}],"collocations":[{"phrase":"a sociological study","zh":"一项社会学研究"},{"phrase":"a sociological explanation","zh":"社会学的解释"},{"phrase":"sociological factors","zh":"社会因素"},{"phrase":"sociological imagination","zh":"社会学想象力"},{"phrase":"a sociological perspective","zh":"社会学视角"},{"phrase":"sociological research","zh":"社会学研究"}],"forms":[{"label":"比较级","form":"more sociological"},{"label":"最高级","form":"most sociological"},{"label":"副词","form":"sociologically"},{"label":"名词","form":"sociology"}],"derivatives":[{"word":"sociology","pos":"n.","zh":"由 sociological 去掉形容词后缀构成的名词，指社会学"},{"word":"sociologically","pos":"adv.","zh":"由 sociological 加副词后缀构成，指从社会学角度"},{"word":"sociologist","pos":"n.","zh":"由 sociology 加表人后缀构成，指社会学者"},{"word":"social","pos":"adj.","zh":"与 sociological 同根但更宽，泛指社会的"},{"word":"societal","pos":"adj.","zh":"由 society 加形容词后缀构成，指整个社会层面的"}],"senses":[{"no":"01","title":"Relating to the discipline","titleCN":"与社会学这门学科有关","definition":"belonging to or produced within the academic field of sociology","definitionCN":"属于社会学领域或在该领域内产生的","example":"The journal published a sociological study of remote work.","exampleCN":"该期刊发表了一项关于远程办公的社会学研究。","why":"The adjective is simply the discipline's name with its regular ending, so its first job is to attach things to the field.","whyCN":"这个形容词就是学科名加上常规词尾，因此它的第一项工作是把事物挂到这门学科上。"},{"no":"02","title":"Explaining by social structure","titleCN":"以社会结构作解释","definition":"explaining an outcome through structures such as class, housing or institutions rather than personal choice","definitionCN":"通过阶级、住房或制度等结构，而非个人选择，来解释某个结果","example":"A sociological account of dropout rates begins with catchment areas.","exampleCN":"对辍学率的社会学解释，从学区划分开始。","why":"The discipline's main move is to shift the cause outward, so the adjective most often modifies explanation and account.","whyCN":"这门学科的主要动作是把原因向外移，因此这个形容词最常修饰「解释」与「叙述」。"},{"no":"03","title":"Concerned with groups and institutions","titleCN":"关注群体与制度","definition":"focused on collectivities, organisations and shared practices rather than single persons","definitionCN":"以集体、组织与共同实践为焦点，而非单个个人","example":"The sociological view treats a family budget as a product of wages and rents.","exampleCN":"社会学视角把家庭预算看作工资与房租的产物。","why":"Once the unit of analysis is the group, the adjective marks that choice of unit.","whyCN":"一旦分析单位是群体，这个形容词就标出这一选择。"},{"no":"04","title":"Using social-science methods","titleCN":"使用社会科学方法","definition":"produced with surveys, interviews, observation or official statistics","definitionCN":"通过调查、访谈、观察或官方统计得来的","example":"Her evidence was sociological rather than anecdotal: three thousand interviews.","exampleCN":"她的证据是社会学的而非轶事式的：三千份访谈。","why":"Methods are what separate this adjective from mere social commentary, so it often appears before data and evidence.","whyCN":"方法把这个形容词与单纯的社会评论区分开，因此它常出现在「数据」「证据」之前。"},{"no":"05","title":"Stressing collective causes","titleCN":"强调集体成因","definition":"attributing outcomes to shared conditions instead of to individual effort or character","definitionCN":"把结果归于共同处境，而不是个人努力或性格","example":"A sociological reading of absenteeism points to shift patterns, not laziness.","exampleCN":"对缺勤的社会学解读指向轮班安排，而不是懒惰。","why":"The shift of blame from person to condition is the adjective's most contested use, and it is where arguments usually start.","whyCN":"把责任从人移到处境，是这个形容词最有争议的用法，争论通常也从这里开始。"},{"no":"06","title":"Framing a private trouble as a public issue","titleCN":"把个人困扰框定为公共议题","definition":"in the tradition of the sociological imagination, connecting personal difficulty to public arrangement","definitionCN":"在社会学想象力的传统中，把个人困境与公共安排连起来","example":"The lecturer gave a sociological name to what students had felt as private failure.","exampleCN":"讲师给学生们的私人挫败感起了一个社会学的名字。","why":"The most famous version of this move turns one person's unemployment into a question about how work is distributed.","whyCN":"这一动作最著名的版本，是把一个人的失业变成关于工作如何分配的问题。"},{"no":"07","title":"Relating to a named subfield","titleCN":"与某个命名分支有关","definition":"describing work inside a specialised branch such as the sociology of medicine or of science","definitionCN":"形容医学社会学或科学社会学等专门分支内的工作","example":"The sociological study of diagnosis compared two hospital wards.","exampleCN":"关于诊断的社会学研究比较了两个医院病区。","why":"Every institution can be looked at this way, and each such look adds a compound to the adjective's range.","whyCN":"每个制度都可以这样看，每一次这样的看都为这个形容词增加一个复合用法。"},{"no":"08","title":"Treating social facts as external constraints","titleCN":"把社会事实视为外在约束","definition":"in the classic formulation, treating social facts as things that constrain individuals from outside","definitionCN":"在经典表述中，把社会事实当作从外部约束个人的事物","example":"A sociological treatment of language policy treats the rules as external facts.","exampleCN":"对语言政策的社会学处理把规则当作外在事实。","why":"The strongest form of the outward turn is to treat social arrangements as objects with force of their own.","whyCN":"向外移最彻底的形态，是把社会安排当作自有力量的对象。"}],"etymology":{"intro":{"en":"Sociological is sociology plus the adjective ending -ical; the noun is a nineteenth-century compound of Latin and Greek. Dates are approximate.","cn":"sociological 是 sociology 加形容词词尾；那个名词是十九世纪由拉丁语与希腊语构成的复合词。年代均为约数。"},"items":[{"era":"LATIN SOCIUS","en":"The root meant 'companion, ally', and its deeper origin is not established; a link to the verb for following is a hypothesis.","cn":"这个词根意为「同伴、盟友」，其更早来源未得到证明；把它与表「跟随」的动词相联系的说法只是假说。"},{"era":"GREEK -LOGIA","en":"The Greek element meant 'the study of' and had already built names such as biology and geology.","cn":"这个希腊成分意为「……之学」，此前已造出 biology、geology 一类名称。"},{"era":"MODERN NOUN","en":"The noun is generally attributed to Auguste Comte in the eighteen thirties, who wanted a science of society.","cn":"这个名词一般认为是孔德在十九世纪三十年代所造，他想要一门关于社会的科学。"},{"era":"ADJECTIVE ENDING","en":"The ending -ical is the ordinary English way of turning a Greek-derived discipline name into an adjective.","cn":"词尾是英语把希腊来源的学科名变成形容词的常规方式。"},{"era":"DERIVED ADJECTIVE","en":"The adjective spread with the discipline in the twentieth century and now also describes any explanation that stresses social causes.","cn":"这个形容词在二十世纪随学科传播，如今也形容任何强调社会成因的解释。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain (first printed use of the adjective and the origin of the companion word): the earliest citation is not settled, and the pre-Latin origin of the root is unknown, so any older form offered for it is a reconstruction.","cn":"来源不确定（这个形容词的最早书证与「同伴」一词的来源）：最早用例尚无定论；该词根在拉丁语之前的来源亦不可考，凡为其提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds same-root adjectives that are easily confused; group two holds adjectives that also explain by structure.","cn":"第一组是同根形容词，极易混淆；第二组是同样以结构作解释的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃl/","tag":"wider and looser","definition":"Relating to society or to interaction; it can describe a party or a policy, while sociological points to the discipline or its style of explanation.","definitionCN":"泛指与社会的或互动有关的，可形容聚会或政策；而 sociological 指学科或其解释风格。"},{"word":"societal","ipa":"/səˈsaɪətl/","tag":"the whole society","definition":"Relating to society as a whole, often used for large-scale effects; it says nothing about the discipline.","definitionCN":"指整个社会层面的，常用于大规模影响，与学科无关。"},{"word":"sociology","ipa":"/ˌsəʊsiˈɒlədʒi/","tag":"the noun","definition":"The name of the field; the adjective modifies nouns, while this noun can be a subject or an object.","definitionCN":"是领域之名；形容词修饰名词，而这个名词可作主语或宾语。"},{"word":"sociologist","ipa":"/ˌsəʊsiˈɒlədʒɪst/","tag":"the person","definition":"The practitioner; a sociological argument need not be made by a sociologist.","definitionCN":"指从业者；一个社会学式论证未必由社会学者提出。"}]},{"heading":"NEAR MEANING","entries":[{"word":"structural","ipa":"/strʌkˈtʃərəl/","tag":"about structure","definition":"Relating to structure in any field, from engineering to economics; sociological specifies a social kind of structure.","definitionCN":"泛指任何领域的结构，从工程到经济；sociological 限定为社会结构。"},{"word":"institutional","ipa":"/ɪnˈstɪtjuːʃənl/","tag":"about institutions","definition":"Relating to established organisations and rules; it is one favourite cause inside sociological explanation.","definitionCN":"指与既有组织及规则有关的，是社会解释中最常用的一类成因。"},{"word":"demographic","ipa":"/dɪˈmɒɡrəfɪk/","tag":"about populations","definition":"Relating to the statistical makeup of a population; it supplies evidence rather than the whole explanation.","definitionCN":"指与人口统计构成有关的，提供证据而非整全解释。"},{"word":"anthropological","ipa":"/ˌænθrəˈpɒlədʒɪkl/","tag":"about culture and fieldwork","definition":"Relating to the study of cultures through close observation; it overlaps with sociological work but starts from culture.","definitionCN":"指通过近距离观察研究文化的，与社会学工作重叠但以文化为起点。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun base, the real adjective ending and the real phrases.","cn":"正常联想：真实的名词基底、真实的形容词词尾与真实的短语。"},"normal":[{"en":"The adjective is the discipline name with its regular ending, so it means belonging to that field.","cn":"这个形容词就是学科名加上常规词尾，因此意为「属于该领域」。"},{"en":"Its most common job is to mark an explanation that moves the cause from the person to the arrangement.","cn":"它最常见的用途，是标出一种把原因从人移到安排的说明。"},{"en":"Fixed phrases mark the uses: a sociological study, a sociological explanation, sociological factors.","cn":"固定搭配标出用法：社会学研究、社会学解释、社会因素。"},{"en":"The family runs society, social, societal, sociologist, sociology, sociological.","cn":"同族词包括 society、social、societal、sociologist、sociology、sociological。"},{"en":"The famous phrase sociological imagination names the move from a private trouble to a public issue.","cn":"著名说法「社会学想象力」正是指从个人困扰移到公共议题的那一步。"}],"abstract":[{"en":"Picture a room with one wall removed, showing the pipes shared with the whole street.","cn":"想象一间屋子被拆掉一面墙，露出与整条街共用的水管。"},{"en":"Picture a queue whose length is blamed on the timetable rather than on the people in it.","cn":"想象一条队伍，其长度被归因于时刻表而不是队伍里的人。"},{"en":"Picture a single cough heard as the sound of a whole building.","cn":"想象一声咳嗽被听成整栋楼的声音。"}]},"examples":[{"en":"The paper offers a sociological account of why the two districts diverged.","cn":"这篇论文对两个街区为何分化给出了社会学解释。"},{"en":"What looks like a personal habit is often a sociological pattern.","cn":"看似个人习惯的东西，往往是社会学的模式。"},{"en":"The course trains students to ask sociological questions about ordinary routines.","cn":"这门课训练学生对日常惯例提出社会学问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「soci 同伴 + ological 学问的」——从人群与结构看问题的，就是社会学的","word":"sociological"},"root":"sociology（拉丁 socius「同伴」+ 希腊「……之学」）+ 形容词词尾；学科名一般认为是孔德所造；socius 更深来源不确定。英语 sociological。","sensesIntro":{"en":"Eight senses follow one outward turn of the gaze: the cause is moved from the person to the arrangement. The adjective marks the field, the explanation, the group as unit, the methods, the collective cause, the private trouble made public, a named subfield, and finally social facts treated as external constraints.","cn":"八个义项沿目光向外的一次转动展开：原因从人身上移到安排上。这个形容词依次标出学科、解释、以群体为单位、方法、集体成因、被公共化的个人困扰、命名分支，最后是被当作外在约束的社会事实。"},"semanticMap":{"core":{"en":"CORE IMAGE: a room with one wall removed, revealing pipes shared with the whole street.","cn":"核心意象：一间屋子被拆掉一面墙，露出与整条街共用的水管。"},"chain":["SOCIETY","STRUCTURE","GROUP CAUSE","METHOD","PUBLIC ISSUE","INSTITUTION"],"branches":[{"senses":"01 · 04","en":"THE FIELD AND ITS TOOLS: the discipline's name and the methods that make its claims systematic belong together.","cn":"学科与工具：学科之名与使其主张成为系统的方法，同属一体。"},{"senses":"02 · 03","en":"STRUCTURE AND UNIT: explaining by structure and choosing the group as the unit are two halves of the same outward turn.","cn":"结构与单位：以结构作解释，与把群体定为分析单位，是同一向外转动的两半。"},{"senses":"05 · 08","en":"CAUSES OUTSIDE THE PERSON: collective conditions and social facts with force of their own both press on the individual from outside.","cn":"人之外的成因：共同处境与自有力量的社会事实，都从外部压向个人。"},{"senses":"06","en":"PRIVATE MADE PUBLIC: a personal failure is renamed as a question about how things are arranged.","cn":"私事公共化：个人的失败被改名成关于事物如何安排的问题。"},{"senses":"07","en":"NAMED SUBFIELD: every institution studied this way adds a compound to the adjective's range.","cn":"命名分支：每一个被这样研究的制度，都为这个形容词增添一个复合用法。"}]},"affixes":{"intro":{"en":"The adjective is a Greek-derived discipline name plus the ordinary English adjective ending, with a Latin root underneath.","cn":"这个形容词是一个希腊来源的学科名加常规英语形容词词尾，底下还有一个拉丁词根。"},"latinIntro":{"en":"Latin socius gives society, social, associate and sociable; the Greek element recurs in biology, geology and theology.","cn":"拉丁 socius 衍生 society、social、associate 与 sociable；那个希腊成分还出现在 biology、geology 与 theology 中。"},"items":[{"word":"socius","structure":"socius (Latin noun, 'companion')","meaning":"companion","meaningCN":"同伴","example":"The root supplies the social half of the meaning.","exampleCN":"这个词根提供词义中「社会」那一半。"},{"word":"-logia","structure":"-logia (Greek element, 'study of')","meaning":"the study of","meaningCN":"……之学","example":"The element turns a root into a discipline name.","exampleCN":"这个成分把词根变成学科名。"},{"word":"sociology","structure":"socius + -logia","meaning":"the study of society","meaningCN":"社会学","example":"The noun is the base of the adjective.","exampleCN":"这个名词是形容词的基底。"},{"word":"-ical","structure":"-ikos (Greek and Latin adjective ending)","meaning":"relating to","meaningCN":"与……有关的","example":"The ending is the standard way to make a discipline adjective in English.","exampleCN":"这个词尾是英语中把学科名变成形容词的标准方式。"},{"word":"sociological","structure":"sociology + -ical","meaning":"relating to sociology","meaningCN":"与社会学有关的","example":"The adjective also covers any explanation that stresses social causes.","exampleCN":"这个形容词也覆盖任何强调社会成因的解释。"},{"word":"-ly","structure":"-lice (English adverb suffix)","meaning":"in the stated manner","meaningCN":"以所述方式","example":"The adverb marks an argument made from this angle.","exampleCN":"这个副词标出从这一角度作出的论证。"},{"word":"sociologically","structure":"sociological + -ly","meaning":"from a sociological angle","meaningCN":"从社会学角度","example":"The adverb is common in research writing.","exampleCN":"这个副词在研究写作中很常见。"},{"word":"-ist","structure":"-ista (agent suffix)","meaning":"one who practices","meaningCN":"从事者","example":"The person noun names the practitioner of the field.","exampleCN":"指人的名词指该领域的从业者。"},{"word":"sociologist","structure":"sociology + -ist","meaning":"a practitioner","meaningCN":"社会学研究者","example":"A sociological claim can be made by anyone, not only by this person.","exampleCN":"社会学式主张任何人都能提出，不必出自这位从业者。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"A shorter suffix produces the adjective for society as a whole.","exampleCN":"一个更短的后缀造出指整个社会的形容词。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association","meaningCN":"联合；社会"},{"word":"sociare","structure":"sociare, sociavi, sociatum (verb, first conjugation)","meaning":"to join, unite","meaningCN":"联合；结合"}]}}]);
